/* generated for The Wine Goat — Spirits Level 1 films */
const I3_=(a,b,c)=>[a,b,c];
/* ---------- spirit drawing helpers (sp…) ---------- */
const spDefs=`<defs><linearGradient id="spcu" x1="0" x2="1"><stop offset="0" stop-color="#7f3f1a"/><stop offset=".42" stop-color="#eaa868"/><stop offset="1" stop-color="#743a18"/></linearGradient><linearGradient id="spgl" x1="0" x2="1"><stop offset="0" stop-color="#fff" stop-opacity=".08"/><stop offset=".3" stop-color="#fff" stop-opacity=".3"/><stop offset="1" stop-color="#fff" stop-opacity=".06"/></linearGradient><linearGradient id="spag" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#9cc3b8"/><stop offset="1" stop-color="#4f7f74"/></linearGradient></defs>`;
const spF=(inner,sky)=>fSvg(spDefs+inner,sky);
const spG=(x,y,s,inner)=>`<g transform="translate(${x} ${y}) scale(${s||1})">${inner}</g>`;
/* rising vapour / smoke wisps */
const spVapour=(x,y,n,h,col)=>{ n=n||3; return Array.from({length:n},(_,i)=>`<path d="M${x+(i-(n-1)/2)*8} ${y}q-4 -6 0 -12q4 -6 0 -12" stroke="${col||"rgba(255,244,220,.75)"}" stroke-width="2" fill="none" stroke-linecap="round" opacity="0"><animateTransform attributeName="transform" type="translate" from="0 0" to="0 ${-(h||22)}" dur="2.6s" begin="${-i*.85}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;0" dur="2.6s" begin="${-i*.85}s" repeatCount="indefinite"/></path>`).join(""); };
/* rising bubbles inside a liquid area */
const spBub=(x0,x1,yb,yt,n,col)=>Array.from({length:n||6},(_,i)=>`<circle cx="${x0+((i*37)%Math.max(1,x1-x0))}" cy="${yb}" r="${1.2+(i%3)*.5}" fill="${col||"rgba(255,255,255,.8)"}"><animate attributeName="cy" from="${yb}" to="${yt}" dur="${1.1+(i%4)*.35}s" begin="${-i*.3}s" repeatCount="indefinite"/></circle>`).join("");
/* poured stream from (x1,y1) to (x2,y2) */
const spPour=(x1,y1,x2,y2,col,w)=>`<path d="M${x1} ${y1}Q${(x1+x2)/2+6} ${y1} ${x2} ${y2}" stroke="${col||"#e9dc8c"}" stroke-width="${w||3}" fill="none" stroke-linecap="round" stroke-dasharray="7 4"><animate attributeName="stroke-dashoffset" from="22" to="0" dur=".7s" repeatCount="indefinite"/></path>`;
/* pot still: origin = bottom centre of the pot. o: {liq, out, fire:false, cond:false, vap:false} */
const spPotStill=(x,y,s,o)=>{ o=o||{}; const liq=o.liq||"#e9dc8c", out=o.out||"rgba(230,240,255,.9)"; let g="";
  if(o.fire!==false) g+=`<rect x="-30" y="0" width="60" height="14" rx="2" fill="#2b2222"/>${fFire(0,12)}`;
  g+=`<path d="M-34 0Q-46 -30 -26 -50Q0 -62 26 -50Q46 -30 34 0Z" fill="url(#spcu)" stroke="#5a2c12" stroke-width="1.5"/>`;
  g+=`<path d="M-30 -5Q-37 -18 -33 -26H33Q37 -18 30 -5Z" fill="${liq}" opacity=".9"/>${spBub(-26,26,-7,-25,7)}`;
  g+=`<rect x="-7" y="-72" width="14" height="22" fill="url(#spcu)" stroke="#5a2c12"/><ellipse cx="0" cy="-80" rx="17" ry="12" fill="url(#spcu)" stroke="#5a2c12"/>`;
  g+=`<path d="M10 -86Q46 -104 84 -66" stroke="#5a2c12" stroke-width="7" fill="none" stroke-linecap="round"/><path d="M10 -86Q46 -104 84 -66" stroke="url(#spcu)" stroke-width="4.6" fill="none" stroke-linecap="round"/>`;
  if(o.vap!==false) g+=Array.from({length:4},(_,i)=>`<circle r="2.2" fill="rgba(255,250,235,.9)"><animateMotion dur="2s" begin="${-i*.5}s" repeatCount="indefinite" path="M0 -60V-84Q40 -104 84 -66"/></circle>`).join("");
  if(o.cond!==false){ g+=`<rect x="74" y="-70" width="40" height="70" rx="4" fill="url(#fst)" stroke="#5c646b"/><rect x="77" y="-62" width="34" height="58" rx="3" fill="#9fd3f0" opacity=".45"/>`;
    g+=`<path d="M84 -66V-60Q104 -56 84 -48Q104 -44 84 -36Q104 -32 84 -24Q104 -20 94 -12H124" stroke="#b5642e" stroke-width="2.6" fill="none"/>`;
    g+=`<rect x="114" y="-14" width="12" height="4" fill="#b5642e"/>${fDrops(126,-9,6,out,3)}<path d="M118 6H134L132 0H120Z" fill="none"/><rect x="117" y="4" width="20" height="16" rx="2" fill="rgba(255,255,255,.18)" stroke="#e8dccf"/><rect x="118.5" y="12" width="17" height="7" fill="${out}"/>`; }
  return spG(x,y,s,g); };
/* column still: origin = bottom centre; h = height; plates = number of sections */
const spColumn=(x,y,h,plates,o)=>{ o=o||{}; const w=o.w||34, top=y-h; let g=`<rect x="${x-w/2}" y="${top}" width="${w}" height="${h}" rx="6" fill="url(#fst)" stroke="#5c646b" stroke-width="1.5"/>`;
  for(let i=1;i<plates;i++){ const py=top+i*h/plates; g+=`<path d="M${x-w/2+3} ${py}H${x+w/2-3}" stroke="#5c646b" stroke-width="1.6"/>`; }
  g+=Array.from({length:6},(_,i)=>`<circle cx="${x-8+(i%3)*8}" cy="${y-6}" r="2" fill="rgba(255,250,235,.95)"><animate attributeName="cy" from="${y-6}" to="${top+8}" dur="${2.4+(i%3)*.4}s" begin="${-i*.45}s" repeatCount="indefinite"/></circle>`).join("");
  g+=Array.from({length:3},(_,i)=>`<ellipse cx="${x+w/2-6}" cy="${top+10}" rx="1.6" ry="2.4" fill="${o.liq||"#e9dc8c"}"><animate attributeName="cy" from="${top+10}" to="${y-6}" dur="2.2s" begin="${-i*.7}s" repeatCount="indefinite"/></ellipse>`).join("");
  if(o.out!==false) g+=`<path d="M${x+w/2} ${top+8}H${x+w/2+20}V${top+20}" stroke="#9aa3ab" stroke-width="3" fill="none"/>${fDrops(x+w/2+20,top+24,top+40,"rgba(230,240,255,.9)",3)}`;
  if(o.steam!==false) g+=`<path d="M${x-w/2-26} ${y-10}H${x-w/2}" stroke="#d4a23a" stroke-width="2.4" marker-end="url(#fah)" fill="none"/>`;
  return g; };
/* vertical strength gauge */
const spAbv=(x,y,h,pct,lab,col,d,hide)=>{ const f=h*pct/100; return `<g><rect x="${x-7}" y="${y-h}" width="14" height="${h}" rx="7" fill="rgba(255,255,255,.12)" stroke="#e8dccf" stroke-width="1.2"/><rect x="${x-5}" y="${y-2}" width="10" height="0" rx="5" fill="${col||"#d4a23a"}"><animate attributeName="y" from="${y-2}" to="${y-2-f}" dur="1.6s" begin="${d||0}s" fill="freeze"/><animate attributeName="height" from="0" to="${f}" dur="1.6s" begin="${d||0}s" fill="freeze"/></rect>${hide?"":fPop(fT(x,y-h-6,pct+"%",10,"#f3cd8a"),(d||0)+1.4)}${lab?fT(x,y+13,lab,9):""}</g>`; };
/* spirit bottle (clear glass). o: {lab, cap, s} */
const spBottle=(x,y,col,o)=>{ o=o||{}; return spG(x,y,o.s,`<path d="M-5 -46H5V-34Q14 -30 14 -20V30Q14 34 10 34H-10Q-14 34 -14 30V-20Q-14 -30 -5 -34Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/>${col?`<path d="M-12 -16H12V30Q12 32 10 32H-10Q-12 32 -12 30Z" fill="${col}" opacity=".88"/>`:""}<rect x="-6" y="-52" width="12" height="7" rx="2" fill="${o.cap||"#3a2a2f"}"/>${o.lab?`<rect x="-12" y="0" width="24" height="18" rx="2" fill="#fbf3e2"/><text x="0" y="12" font-size="${o.lab.length>4?5.6:7}" text-anchor="middle" fill="#8c1d40" font-family="DM Sans,system-ui,sans-serif" font-weight="800">${esc(o.lab)}</text>`:""}`); };
/* tulip tasting glass */
const spTulip=(x,y,col,s)=>spG(x,y,s,`<path d="M-13 -16Q-12 -3 0 -3Q12 -3 13 -16Z" fill="${col||"#e9dc8c"}" opacity=".9"/><path d="M-8 -46Q-17 -30 -15 -16Q-13 -2 0 -2Q13 -2 15 -16Q17 -30 8 -46" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -2V20M-11 21H11" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>`);
/* tumbler (straight glass) */
const spTumbler=(x,y,col,s)=>spG(x,y,s,`<path d="M-15 -8H15V-2Q15 0 13 0H-13Q-15 0 -15 -2Z" fill="${col||"#e9dc8c"}"/><path d="M-16 -36H16V-2Q16 1 13 1H-13Q-16 1 -16 -2Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/>`);
/* ice cube */
const spIce=(x,y,s,r)=>`<g transform="translate(${x} ${y}) rotate(${r||0}) scale(${s||1})"><rect x="-6" y="-6" width="12" height="12" rx="2.5" fill="rgba(225,244,252,.85)" stroke="#bfe6f6"/><path d="M-3 -3h4" stroke="#fff" stroke-width="1.4"/></g>`;
/* citrus wheel */
const spCitrus=(x,y,r,col)=>`<g transform="translate(${x} ${y})"><circle r="${r}" fill="${col||"#9cc63a"}"/><circle r="${r*.82}" fill="${mixC(col||"#9cc63a","#ffffff",.45)}"/>${[0,1,2,3,4,5].map(i=>`<path d="M0 0L${(r*.8*Math.cos(i*Math.PI/3)).toFixed(1)} ${(r*.8*Math.sin(i*Math.PI/3)).toFixed(1)}" stroke="${col||"#9cc63a"}" stroke-width="1"/>`).join("")}</g>`;
const LIME="#8fc23a", LEMON="#f2d64b", ORANGE="#f39a2b", GRAPEF="#f08a6a";
/* cocktail glasses: type rocks|highball|coupe|martini|flute. o: {ice, gar:[colour], foam, bub, mint, salt, s} */
const spCocktail=(x,y,type,col,o)=>{ o=o||{}; let g="";
  if(type==="rocks"){ g+=`<path d="M-15 -20H15V-2Q15 0 13 0H-13Q-15 0 -15 -2Z" fill="${col}" opacity=".9"/>${o.ice?spIce(-6,-14,1,12)+spIce(6,-12,1,-8):""}<path d="M-17 -34H17V-2Q17 2 13 2H-13Q-17 2 -17 -2Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/>`; if(o.gar) g+=spCitrus(14,-34,6,o.gar); }
  if(type==="highball"){ g+=`<path d="M-11 -48H11V-2Q11 0 9 0H-9Q-11 0 -11 -2Z" fill="${col}" opacity=".88"/>${o.ice?spIce(-3,-40,.9,10)+spIce(3,-27,.9,-12)+spIce(-2,-14,.9,6):""}${o.bub?spBub(-8,8,-4,-46,6):""}${o.mint?fLeaf(-3,-46,.7,-20,"#4f9a3a")+fLeaf(4,-48,.6,25,"#5eae44"):""}<path d="M-12 -62H12V-2Q12 2 9 2H-9Q-12 2 -12 -2Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/>`; if(o.gar) g+=spCitrus(11,-61,6,o.gar); }
  if(type==="coupe"){ g+=`<path d="M-19 -40Q-15 -27 0 -26Q15 -27 19 -40Z" fill="${col}" opacity=".9"/>${o.foam?`<path d="M-19 -40Q0 -44 19 -40Q16 -37 0 -37Q-16 -37 -19 -40Z" fill="#f6f1e2"/>`:""}<path d="M-21 -42Q-18 -24 0 -24Q18 -24 21 -42" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -24V-1M-11 0H11" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>`; if(o.gar) g+=spCitrus(19,-42,5,o.gar); }
  if(type==="martini"){ g+=`<path d="M-17 -40L0 -24L17 -40Z" fill="${col}" opacity=".9"/><path d="M-22 -45L0 -22L22 -45" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -22V-1M-11 0H11" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>${o.salt?`<path d="M-22 -45H22" stroke="#fff" stroke-width="2.4" stroke-dasharray="1.5 1.5"/>`:""}`; if(o.gar) g+=spCitrus(20,-45,5,o.gar); if(o.olive) g+=`<path d="M-8 -44L4 -30" stroke="#d4a23a" stroke-width="1"/><ellipse cx="2" cy="-32" rx="3.4" ry="2.6" fill="#7a9a3a"/>`; }
  if(type==="flute"){ g+=`<path d="M-6 -46H6L5 -22Q0 -18 -5 -22Z" fill="${col}" opacity=".9"/>${spBub(-4,4,-22,-46,4)}<path d="M-7 -56H7L6 -22Q0 -16 -6 -22Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -18V-1M-9 0H9" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>`; }
  return spG(x,y,o.s,g); };
/* cocktail shaker, optionally shaking */
const spShaker=(x,y,s,shake)=>`<g transform="translate(${x} ${y}) scale(${s||1})"><g>${shake?`<animateTransform attributeName="transform" type="rotate" values="-14;14;-14" dur=".5s" repeatCount="indefinite"/>`:""}<path d="M-13 -10L-10 26Q0 30 10 26L13 -10Z" fill="url(#fst)" stroke="#5c646b"/><path d="M-11 -24L-13 -10H13L11 -24Z" fill="url(#fst)" stroke="#5c646b"/><rect x="-6" y="-32" width="12" height="8" rx="3" fill="url(#fst)" stroke="#5c646b"/></g></g>`;
/* bar spoon stirring in a mixing glass */
const spStir=(x,y,col)=>`<g transform="translate(${x} ${y})"><path d="M-14 -40H14V-2Q14 1 11 1H-11Q-14 1 -14 -2Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M-12 -20H12V-2H-12Z" fill="${col||"#c98a3a"}" opacity=".85"/>${spIce(-5,-14,.8,10)+spIce(5,-10,.8,-10)}<g><animateTransform attributeName="transform" type="rotate" values="-8 0 -20;8 0 -20;-8 0 -20" dur="1.2s" repeatCount="indefinite"/><path d="M2 -60V-6" stroke="#c9ced3" stroke-width="1.6"/><ellipse cx="2" cy="-5" rx="2.4" ry="1.5" fill="#c9ced3"/></g></g>`;
/* sugar cubes */
const spSugar=(x,y,n)=>Array.from({length:n||2},(_,i)=>`<rect x="${x+i*11-5}" y="${y-(i%2)*4-10}" width="10" height="10" rx="1.5" fill="#fbf6ec" stroke="#d8cdb8"/>`).join("");
/* small labelled bottle for cocktail ingredients */
const spIng=(x,y,col,lab,d)=>fD(d||0,spBottle(x,y,col,{s:.62})+fT(x,y+36,lab,8.5,"#f3cd8a"));
/* dash bottle (bitters) dripping */
const spBitters=(x,y,drip)=>`<g transform="translate(${x} ${y})"><path d="M-3 -30H3V-24Q9 -21 9 -14V8Q9 10 7 10H-7Q-9 10 -9 8V-14Q-9 -21 -3 -24Z" fill="#5a2a1a" stroke="#e8dccf"/><rect x="-7" y="-10" width="14" height="10" fill="#fbf3e2"/><rect x="-4" y="-35" width="8" height="5" rx="1" fill="#e8dccf"/>${drip?fDrops(0,-30,-6,"#7a2a1a",2):""}</g>`;
/* barley ear (col for rye) */
const spBarley=(x,y,s,col)=>{ col=col||"#e0b85a"; let g=`<path d="M0 0V-56" stroke="${mixC(col,"#6b8a3a",.4)}" stroke-width="2"/>`; for(let i=0;i<7;i++){ const yy=-24-i*5; g+=`<ellipse cx="-3.2" cy="${yy}" rx="2.6" ry="4" fill="${col}" transform="rotate(-25 -3.2 ${yy})"/><ellipse cx="3.2" cy="${yy-2}" rx="2.6" ry="4" fill="${col}" transform="rotate(25 3.2 ${yy-2})"/><path d="M-4 ${yy-3}l-5 -12M4 ${yy-5}l5 -12" stroke="${col}" stroke-width=".7"/>`; } return spG(x,y,s,g); };
/* corn cob */
const spCorn=(x,y,s)=>{ let g=`<path d="M-12 0Q-16 -30 0 -52Q-6 -20 -12 0Z" fill="#6f9e3a"/><ellipse cx="2" cy="-26" rx="9" ry="24" fill="#f2c443"/>`; for(let r=0;r<8;r++) for(let c=-1;c<=1;c++) g+=`<circle cx="${2+c*5}" cy="${-44+r*5.4}" r="2" fill="#e8a92e"/>`; g+=`<path d="M14 0Q18 -30 4 -52Q10 -20 14 0Z" fill="#7fae46"/>`; return spG(x,y,s,g); };
/* potato */
const spPotato=(x,y,s)=>spG(x,y,s,`<path d="M-16 0Q-20 -14 -6 -18Q10 -22 16 -10Q20 2 4 4Q-12 6 -16 0Z" fill="#b8915a" stroke="#7a5a33"/><circle cx="-6" cy="-9" r="1.3" fill="#7a5a33"/><circle cx="6" cy="-6" r="1.3" fill="#7a5a33"/><circle cx="1" cy="-13" r="1.1" fill="#7a5a33"/>`);
/* sugar cane stalks */
const spCane=(x,y,s,h)=>{ h=h||90; let g=""; [-8,0,8].forEach((dx,k)=>{ g+=`<path d="M${dx} 0V${-h+k*8}" stroke="#7fa83a" stroke-width="5"/>`; for(let yy=-12;yy>-h+k*8;yy-=14) g+=`<path d="M${dx-3} ${yy}h6" stroke="#4f7a28" stroke-width="1.6"/>`; g+=`<path d="M${dx} ${-h+k*8}q-18 -4 -26 8M${dx} ${-h+k*8+6}q16 -6 26 4M${dx} ${-h+k*8+2}q-4 -16 4 -24" stroke="#5e9a32" stroke-width="2.4" fill="none"/>`; }); return spG(x,y,s,g); };
/* agave plant (blue-green spiky rosette) */
const spAgave=(x,y,s)=>{ const a=[-70,-50,-30,-12,8,28,48,68]; return spG(x,y,s,`<ellipse cx="0" cy="-6" rx="16" ry="11" fill="#7aa79c"/>${a.map((d,i)=>`<path d="M-3 -6L0 ${-48-(i%2)*10}L3 -6Z" fill="url(#spag)" stroke="#3f6b61" stroke-width=".6" transform="rotate(${d} 0 -6)"/>`).join("")}`); };
/* agave core (piña), cooked = brown */
const spPina=(x,y,s,cooked)=>{ const c=cooked?"#b5732e":"#cfd9a0", e=cooked?"#7a4518":"#8aa36a"; let g=`<ellipse cx="0" cy="-16" rx="18" ry="16" fill="${c}" stroke="${e}" stroke-width="1.2"/>`; for(let r=0;r<3;r++) for(let k=-2;k<=2;k++) g+=`<path d="M${k*6-2} ${-26+r*9}l2 -4 2 4" stroke="${e}" stroke-width="1" fill="none"/>`; return spG(x,y,s,g); };
/* brick oven with glow, for agave */
const spOven=(x,y,s)=>spG(x,y,s,`<path d="M-44 0V-34Q-44 -60 0 -62Q44 -60 44 -34V0Z" fill="#9a4f32" stroke="#5e2c1a" stroke-width="1.5"/>${[-30,-14,2,18].map(yy=>`<path d="M-42 ${yy+8}H42" stroke="#6e3420" stroke-width=".8"/>`).join("")}<path d="M-20 0V-22Q0 -38 20 -22V0Z" fill="#2a1410"/><path d="M-18 0V-20Q0 -34 18 -20V0Z" fill="#f6a43a" opacity=".35"><animate attributeName="opacity" values=".25;.55;.25" dur="1.8s" repeatCount="indefinite"/></path>${spPina(-8,0,.42,1)+spPina(8,0,.42,1)}`);
/* juniper sprig with berries */
const spJuniper=(x,y,s)=>spG(x,y,s,`<path d="M-20 10Q0 0 22 -14" stroke="#4f6e3a" stroke-width="2" fill="none"/>${[-14,-6,2,10,18].map((t,i)=>`<path d="M${t} ${6-i*4}l-4 -9M${t} ${6-i*4}l6 -7" stroke="#6f9a5a" stroke-width="1.2"/>`).join("")}${[[-6,8],[0,4],[5,10],[10,2],[-1,12]].map(([a,b])=>`<circle cx="${a}" cy="${b}" r="4" fill="#3d4f8a"/><circle cx="${a-1.2}" cy="${b-1.2}" r="1.1" fill="#9fb3e0"/>`).join("")}`);
/* coriander seeds, angelica root, orris, peel */
const spSeeds=(x,y,col)=>[0,1,2,3,4,5].map(i=>`<circle cx="${x+(i%3)*7}" cy="${y+Math.floor(i/3)*7}" r="3" fill="${col||"#d6b77a"}" stroke="#9a7a42" stroke-width=".6"/>`).join("");
const spRoot=(x,y,col)=>`<path d="M${x} ${y}q6 10 2 22q-2 6 4 12M${x+2} ${y+12}l-6 8" stroke="${col||"#a87a4a"}" stroke-width="3" fill="none" stroke-linecap="round"/>`;
const spPeel=(x,y,col)=>`<path d="M${x-14} ${y}q14 -12 28 0q-14 -6 -28 0Z" fill="${col||ORANGE}" stroke="${mixC(col||ORANGE,"#000000",.25)}"/>`;
/* bed of charcoal inside a vat with spirit dripping through */
const spCharcoal=(x,y,w)=>`<g><rect x="${x}" y="${y}" width="${w}" height="46" rx="4" fill="url(#fst)" stroke="#5c646b"/>${Array.from({length:Math.floor(w/9)*3},(_,i)=>`<rect x="${x+4+(i*9)%(w-10)}" y="${y+8+Math.floor(i/Math.floor(w/9))*10}" width="7" height="6" rx="1.5" fill="#1e1a1a" transform="rotate(${(i*23)%40-20} ${x+7+(i*9)%(w-10)} ${y+11+Math.floor(i/Math.floor(w/9))*10})"/>`).join("")}${fDrops(x+w/2-6,y-14,y+6,"rgba(230,240,255,.9)",3)}${fDrops(x+w/2,y+46,y+60,"rgba(230,240,255,.9)",3)}</g>`;
/* peat bricks with fire and smoke */
const spPeat=(x,y)=>`<g transform="translate(${x} ${y})">${[[-18,0],[0,0],[18,0],[-9,-9],[9,-9]].map(([a,b])=>`<rect x="${a-8}" y="${b-8}" width="16" height="8" rx="1.5" fill="#4a3324" stroke="#2a1c12"/>`).join("")}${fFire(0,-14)}${spVapour(0,-34,3,30,"rgba(170,170,170,.7)")}</g>`;
/* balance scale: tilts then settles */
const spScale=(x,y,a,b)=>`<g transform="translate(${x} ${y})"><path d="M0 0V-62M-16 0H16" stroke="#d4a23a" stroke-width="3" stroke-linecap="round"/><circle cy="-62" r="3.4" fill="#d4a23a"/><g><animateTransform attributeName="transform" type="rotate" values="-14 0 -62;10 0 -62;-5 0 -62;0 0 -62" dur="3s" fill="freeze"/><path d="M-70 -62H70" stroke="#d4a23a" stroke-width="3" stroke-linecap="round"/><path d="M-70 -62l-14 26h28zM70 -62l-14 26h28z" fill="none" stroke="#d4a23a" stroke-width="1.2"/><path d="M-86 -36h32q-2 8 -16 8t-16 -8zM54 -36h32q-2 8 -16 8t-16 -8z" fill="#d4a23a"/>${a}${b}</g></g>`;
/* map pin */
const spPin=(x,y,col)=>`<g transform="translate(${x} ${y})"><path d="M0 0C-8 -10 -8 -20 0 -20C8 -20 8 -10 0 0Z" fill="${col||"#b5334a"}" stroke="#fff4dc" stroke-width="1"><animateTransform attributeName="transform" type="translate" values="0 -6;0 0;0 -2;0 0" dur="1s" fill="freeze"/></path><circle cy="-14" r="2.6" fill="#fff4dc"/></g>`;
/* molasses jar */
const spMolasses=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M-14 -34H14V-2Q14 1 11 1H-11Q-14 1 -14 -2Z" fill="#2a160c" stroke="#e8dccf" stroke-width="1.2"/><path d="M-14 -34Q-8 -28 -6 -22Q-4 -28 2 -34" fill="#3b1e0e"/><rect x="-16" y="-38" width="32" height="5" rx="2" fill="#7a5236"/></g>`;
/* water jug pouring */
const spJug=(x,y,pour,tx,ty)=>`<g><g transform="translate(${x} ${y}) rotate(${pour?-30:0})"><path d="M-12 -30H10L16 -36V-30Q14 -14 12 0H-12Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M-11 -20H11V0H-11Z" fill="#9fd3f0" opacity=".6"/><path d="M-12 -24Q-22 -18 -12 -8" stroke="#e8dccf" stroke-width="2" fill="none"/></g>${pour?spPour(x+14,y-36,tx,ty,"#bfe6f6",2.4):""}</g>`;
/* stainless tank, compact */
const spSteel=(x,y,w,h,col)=>`<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="url(#fst)" stroke="#5c646b"/><rect x="${x+5}" y="${y+h*.35}" width="${w-10}" height="${h*.6}" rx="4" fill="${col||"rgba(230,240,255,.55)"}"/><path d="M${x+w/2} ${y-6}V${y}" stroke="#5c646b" stroke-width="3"/></g>`;
/* colour swatch row (appearance) */
const spSwatches=(x,y,cols,labs,d,gap)=>cols.map((c,i)=>fD((d||0)+i*.35,`<circle cx="${x+i*(gap||44)}" cy="${y}" r="14" fill="${c}" stroke="#e8dccf" stroke-width="1.2"/>`+(labs?fT(x+i*(gap||44),y+28,labs[i],8.5):""))).join("");
/* tropical fruit */
const spBanana=(x,y,s)=>spG(x,y,s,`<path d="M-18 -8Q0 14 20 -10Q4 4 -18 -8Z" fill="#f2d64b" stroke="#a88a2a"/><path d="M-18 -8l-3 -3M20 -10l2 -3" stroke="#5a4a2a" stroke-width="2"/>`);
const spPineapple=(x,y,s)=>spG(x,y,s,`<path d="M0 -20l-8 -12M0 -20l0 -15M0 -20l8 -12M0 -20l-12 -6M0 -20l12 -6" stroke="#5e9a32" stroke-width="2.6" stroke-linecap="round"/><ellipse cx="0" cy="0" rx="12" ry="18" fill="#e8a92e" stroke="#9a6a1a"/><path d="M-10 -10L10 10M-12 2L4 16M-4 -16L12 0M10 -10L-10 10M12 2L-4 16M4 -16L-12 0" stroke="#9a6a1a" stroke-width=".9"/>`);
/* two crushing rollers */
const spRollers=(x,y,s)=>spG(x,y,s,[-12,12].map((dx,i)=>`<g transform="translate(${dx} 0)"><circle r="12" fill="url(#fst)" stroke="#5c646b"/><path d="M-10 0H10M0 -10V10" stroke="#5c646b"><animateTransform attributeName="transform" type="rotate" from="0" to="${i?-360:360}" dur="2s" repeatCount="indefinite"/></path></g>`).join(""));
/* red cross over something */
const spNo=(x,y,r)=>`<path d="M${x-r} ${y-r}L${x+r} ${y+r}M${x+r} ${y-r}L${x-r} ${y+r}" stroke="#e2622a" stroke-width="4" stroke-linecap="round"/>`;
/* wormwood sprig (silvery, feathery) */
const spWormwood=(x,y,s)=>spG(x,y,s,`<path d="M0 0V-60" stroke="#8fa39a" stroke-width="2"/>${[-50,-40,-30,-20,-10].map((yy,i)=>`<path d="M0 ${yy}q${i%2?12:-12} -4 ${i%2?20:-20} -12M0 ${yy}q${i%2?6:-6} -8 ${i%2?8:-8} -16" stroke="#b9c9c0" stroke-width="2.2" fill="none" stroke-linecap="round"/>`).join("")}${[-58,-52,-46].map(yy=>`<circle cx="${(yy%4)}" cy="${yy}" r="2" fill="#e0d48a"/>`).join("")}`);
/* eye, nose, spoon, spittoon for tasting */
const spEye=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M-14 0Q0 -12 14 0Q0 12 -14 0Z" fill="#fbf3e2" stroke="#3a2a2f" stroke-width="1.4"/><circle r="5" fill="#5e8c31"/><circle r="2.2" fill="#1a1012"/></g>`;
const spNose=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M-4 -20Q2 -6 10 6Q6 10 -2 9" fill="none" stroke="#f3cd8a" stroke-width="2.4" stroke-linecap="round"/><path d="M2 8q-2 -3 -5 -1" fill="none" stroke="#f3cd8a" stroke-width="1.6"/></g>`;
const spSpoon=(x,y,col)=>`<g transform="translate(${x} ${y})"><path d="M14 0H54" stroke="#c9ced3" stroke-width="3.4" stroke-linecap="round"/><ellipse rx="16" ry="8" fill="#c9ced3"/><ellipse cy="-1" rx="12" ry="5" fill="${col||"#d9a441"}"/></g>`;
const spSpittoon=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M-18 -30H18L14 0H-14Z" fill="url(#fst)" stroke="#5c646b"/><ellipse cy="-30" rx="18" ry="4" fill="#3a3a3a"/></g>`;
/* a named drink: glass, name chip on top, ingredient lines below */
const spDrink=(x,name,type,col,o,ings,d)=>fD(d||0,fChip(x,24,name,"#8c1d40")+spCocktail(x,116,type,col,o)+ings.map((t,i)=>fT(x,136+i*12.5,t,8.6,"#f3cd8a")).join(""));
window.TWG_MEDIA = window.TWG_MEDIA || {};
TWG_MEDIA.fsec = { v: I3_("Come si fa un distillato","Fabriquer un spiritueux","Making spirits"), c: I3_("Le famiglie di distillati","Les familles de spiritueux","Spirit families"), s: I3_("Distillati aromatizzati e vini aromatizzati","Spiritueux aromatisés et vins aromatisés","Flavoured spirits and aromatised wines"), t: I3_("Degustazione e cocktail","Dégustation et cocktails","Tasting and cocktails") };
TWG_MEDIA.films = [
/* ===================== p1 ===================== */
{id:"s1_stills", sec:"v", ch:"p1", ic:"order", t:I3_("Quattro passaggi e due alambicchi","Quatre étapes et deux alambics","Four steps and two stills"), s:[
 {h:I3_("Le quattro tappe di ogni distillato","Les quatre étapes de tout spiritueux","The four steps of every spirit"),
  c:I3_("Ogni distillato, dalla vodka al Cognac, segue le stesse quattro tappe. Prima una materia prima vegetale diventa un liquido zuccherino. Poi i lieviti lo fermentano in alcol. La distillazione rende quell'alcol più forte. Infine il produttore decide che cosa fare del distillato nuovo: invecchiarlo, aromatizzarlo, addolcirlo, colorarlo e diluirlo.",
   "Chaque spiritueux, de la vodka au Cognac, suit les mêmes quatre étapes. D'abord une matière première végétale devient un liquide sucré. Puis les levures le fermentent en alcool. La distillation rend cet alcool plus fort. Enfin le producteur décide quoi faire de l'eau-de-vie nouvelle : la vieillir, l'aromatiser, la sucrer, la colorer et la diluer.",
   "Every spirit, from vodka to Cognac, follows the same four steps. First a plant raw material is turned into a sugary liquid. Then yeast ferments it into alcohol. Distillation makes that alcohol stronger. Finally the producer decides what to do with the new spirit: age it, flavour it, sweeten it, colour it and dilute it."),
  v:()=>spF([[w3("Materia prima","Matière première","Raw material")],[w3("Fermentazione","Fermentation","Fermentation")],[w3("Distillazione","Distillation","Distillation")],[w3("Dopo l'alambicco","Après l'alambic","After the still")]].map(([l],i)=>fD(.3+i*.7,fBox(8+i*78,22,70,28,l,{fill:i===2?"rgba(140,29,64,.7)":undefined})+(i<3?fArrow(`M${79+i*78} 36H${85+i*78}`):""))).join("")
   +fD(.6,spBarley(26,176,.75)+fBunch(52,118,1.5,"#6b2d5c"))+fD(1.3,fTank(98,104,44,64,{col:"#e9dc8c",bub:5}))+fD(2,spPotStill(186,170,.42,{fire:true}))+fD(2.7,fBarrel(270,146,.55)+spBottle(302,152,"#c98a3a",{s:.5})))},
 {h:I3_("Un liquido zuccherino da una pianta","Un liquide sucré tiré d'une plante","A sugary liquid from a plant"),
  c:I3_("Senza zucchero non c'è fermentazione, quindi il primo obiettivo è ottenere un liquido zuccherino da una pianta. L'uva e la canna da zucchero contengono già zucchero facile da estrarre. I cereali non ne hanno: vanno lavorati per crearlo. Qualunque sia la pianta, lascia la sua firma, perché ogni materia prima porta i propri aromi.",
   "Sans sucre, pas de fermentation : le premier but est donc d'obtenir un liquide sucré à partir d'une plante. Le raisin et la canne à sucre contiennent déjà du sucre facile à extraire. Les céréales n'en ont pas : il faut les transformer pour en créer. Quelle que soit la plante, elle laisse sa signature, car chaque matière première apporte ses propres arômes.",
   "Fermentation needs sugar, so step one is to get a sugary liquid from a plant. Grapes and sugar cane already contain sugar that is easy to extract. Cereals contain none: they must be processed to create it. Whatever the plant, it leaves its signature, because each raw material brings its own aromas to the spirit."),
  v:()=>spF(fBunch(36,30,1.7,"#6b2d5c")+spCane(84,92,.55)+fD(.6,fChip(150,54,w3("zucchero pronto","sucre déjà là","sugar ready"),"#5e8c31"))+fArrow("M190 54Q220 60 236 84",null,1)
   +spBarley(30,176,.75)+spBarley(48,176,.75)+spCorn(82,176,.75)+fD(1.4,fChip(176,150,w3("amido: da trasformare","amidon : à transformer","starch: must convert"),"#8c1d40"))+fArrow("M190 146Q220 140 236 124",null,1)
   +fD(2.2,fTank(240,82,60,70,{col:"#e9dc8c"})+fChip(270,176,w3("liquido zuccherino","liquide sucré","sugary liquid"))),"summer")},
 {h:I3_("La fermentazione crea l'alcol","La fermentation crée l'alcool","Fermentation makes the alcohol"),
  c:I3_("I lieviti sono minuscoli organismi viventi. Si nutrono dello zucchero e lasciano etanolo, l'alcol che si cerca, e anidride carbonica, un gas che se ne va. Il liquido fermentato arriva di solito all'8–10% vol., più o meno come una birra forte. I lieviti creano anche nuovi aromi, soprattutto fruttati.",
   "Les levures sont de minuscules organismes vivants. Elles se nourrissent du sucre et laissent de l'éthanol, l'alcool recherché, et du dioxyde de carbone, un gaz qui s'échappe. Le liquide fermenté atteint en général 8 à 10 % vol., à peu près une bière forte. Les levures créent aussi de nouveaux arômes, surtout fruités.",
   "Yeasts are tiny living organisms. They feed on the sugar and leave behind ethanol, the alcohol the distiller wants, and carbon dioxide, a gas that escapes. The fermented liquid usually reaches 8 to 10% abv, about the strength of a strong beer. Yeasts also create new aromas, especially fruity ones."),
  v:()=>spF(fTank(40,52,90,118,{col:"#e9dc8c",bub:10})+fD(.4,fYeast(66,130)+fYeast(100,112)+fYeast(78,150))+spVapour(85,40,3,24)+fD(.8,fT(85,24,"CO₂",11,"#9fd3f0"))
   +fD(1.2,fBox(160,46,140,24,w3("lieviti + zucchero","levures + sucre","yeast + sugar")))+fD(1.8,fArrow("M230 72V84")+fBox(160,88,140,24,w3("etanolo + CO₂","éthanol + CO₂","ethanol + CO₂"),{fill:"rgba(140,29,64,.7)"}))
   +fD(2.5,fChip(230,136,"8–10% vol","#d4a23a","#2a1b20"))+fD(3,fChip(230,162,w3("+ aromi fruttati","+ arômes fruités","+ fruity aromas"))))},
 {h:I3_("L'etanolo bolle prima dell'acqua","L'éthanol bout avant l'eau","Ethanol boils before water"),
  c:I3_("La distillazione si basa su un fatto semplice: l'etanolo bolle a una temperatura più bassa dell'acqua. Se si scalda il liquido fermentato, il vapore che sale è più ricco di alcol del liquido che resta. Raccolto e raffreddato, quel vapore torna liquido, più forte di quello di partenza.",
   "La distillation repose sur un fait simple : l'éthanol bout à une température plus basse que l'eau. Quand on chauffe le liquide fermenté, la vapeur qui monte est plus riche en alcool que le liquide qui reste. Recueillie et refroidie, cette vapeur redevient liquide, plus forte que celui du départ.",
   "Distillation relies on one simple fact: ethanol boils at a lower temperature than water. Heat the fermented liquid and the vapour rising from it is richer in alcohol than the liquid left behind. Collect that vapour and cool it, and it turns back into a liquid stronger than the one you started with."),
  v:()=>spF(`<path d="M50 96V160Q50 166 56 166H124Q130 166 130 160V96" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.6"/><rect x="53" y="120" width="74" height="44" rx="3" fill="#9fd3f0" opacity=".45"/>`+fFire(90,186)
   +Array.from({length:8},(_,i)=>`<circle cx="${60+i*9}" cy="150" r="3" fill="${i%3?"#7fc0e6":"#f3cd8a"}"/>`).join("")
   +Array.from({length:7},(_,i)=>`<circle cx="${62+(i*11)%60}" cy="118" r="3" fill="${i===3?"#7fc0e6":"#f3cd8a"}"><animate attributeName="cy" from="118" to="40" dur="${2+(i%3)*.4}s" begin="${i*.35}s" repeatCount="indefinite"/><animate attributeName="opacity" values="1;1;0" dur="${2+(i%3)*.4}s" begin="${i*.35}s" repeatCount="indefinite"/></circle>`).join("")
   +fD(.6,`<circle cx="160" cy="44" r="4" fill="#f3cd8a"/>`+fT(170,48,w3("etanolo: bolle prima","éthanol : bout d'abord","ethanol: boils first"),9.5,"#f3cd8a","start"))+fD(1.2,`<circle cx="160" cy="68" r="4" fill="#7fc0e6"/>`+fT(170,72,w3("acqua: bolle dopo","eau : bout plus tard","water: boils later"),9.5,"#9fd3f0","start"))
   +fD(2,fArrow("M150 110H210")+fChip(180,98,w3("vapore raffreddato","vapeur refroidie","cooled vapour")))+fD(2.6,spTumbler(250,166,"rgba(230,240,255,.8)",1.2)+fChip(250,112,w3("più forte","plus fort","stronger"),"#8c1d40")))},
 {h:I3_("Grado basso, più aroma","Degré bas, plus d'arômes","Low strength, more aroma"),
  c:I3_("Appena uscito dall'alambicco, un distillato può andare da circa il 60% al 96% vol., e questo grado ne decide il gusto. Più è basso, più gli aromi sono intensi. Più sale, meno aroma sopravvive. Al 96% non resta quasi nulla da annusare: il distillato si chiama neutro.",
   "À la sortie de l'alambic, une eau-de-vie peut aller d'environ 60 % à 96 % vol., et ce degré décide de son goût. Plus il est bas, plus les arômes sont intenses. Plus il monte, moins il reste d'arômes. À 96 %, il n'y a presque plus rien à sentir : on parle d'alcool neutre.",
   "Fresh from the still, a spirit can range from about 60% to 96% abv, and that strength shapes its flavour. The lower the strength, the more intense the aromas. The higher it goes, the less aroma survives. At 96% there is almost nothing left to smell: the spirit is called neutral."),
  v:()=>spF(spAbv(56,160,110,60,w3("grado basso","degré bas","low strength"),"#d4a23a",.2)+spTulip(116,150,"rgba(240,230,200,.7)",1.2)+spVapour(116,90,4,30,"#f6a43a")+fD(1.2,fChip(116,40,w3("aromi intensi","arômes intenses","intense aromas"),"#5e8c31"))
   +spAbv(208,160,110,96,w3("grado alto","degré élevé","high strength"),"#9fd3f0",.8)+spTulip(268,150,"rgba(230,240,255,.7)",1.2)+fD(2.2,fChip(268,40,w3("neutro","neutre","neutral"),"#5c646b")))},
 {h:I3_("L'alambicco discontinuo","L'alambic à repasse","The pot still"),
  c:I3_("Un alambicco discontinuo ha sempre tre parti: una caldaia su una fonte di calore, un condensatore e un tubo che li collega. Il liquido bolle nella caldaia, il vapore sale nel capitello e passa nel condensatore, dove una serpentina immersa in acqua fredda lo fa tornare liquido. Molti oggi si scaldano a vapore; quelli del Cognac usano bruciatori a gas.",
   "Un alambic à repasse a toujours trois parties : une chaudière sur une source de chaleur, un condenseur et un tuyau qui les relie. Le liquide bout dans la chaudière, la vapeur monte dans le chapiteau et passe dans le condenseur, où un serpentin plongé dans l'eau froide la remet à l'état liquide. Beaucoup sont chauffés à la vapeur ; ceux du Cognac utilisent des brûleurs à gaz.",
   "A pot still always has three parts: a pot on a heat source, a condenser, and a pipe linking the two. The liquid boils in the pot, the vapour climbs the still head and passes into the condenser, where a coiled tube in cold water turns it back into liquid. Many are steam-heated today; Cognac stills use gas burners."),
  v:()=>spF(spPotStill(96,164,1)+fCall(80,136,40,96,w3("caldaia + calore","chaudière + chaleur","pot + heat"),.6)+fCall(140,68,150,26,w3("tubo","tuyau","linking pipe"),1.4)+fCall(206,120,268,70,w3("condensatore","condenseur","condenser"),2.2)+fCall(232,172,282,150,w3("distillato","eau-de-vie","spirit"),3))},
 {h:I3_("A lotti, e due volte","Par lots, et deux fois","In batches, and twice"),
  c:I3_("L'alambicco discontinuo lavora a lotti, come una lavatrice: si carica, si fa il ciclo, poi si svuota e si pulisce prima del giro dopo. Un solo passaggio non basta, quindi quasi tutti distillano due volte: da circa il 10% al 25% vol., poi al 75%. Ne esce un distillato con aromi da medi a pronunciati e tanto carattere, mai neutro.",
   "L'alambic à repasse travaille par lots, comme une machine à laver : on le charge, on lance le cycle, puis on le vide et on le nettoie avant le suivant. Un seul passage ne suffit pas : on distille presque toujours deux fois, d'environ 10 % à 25 % vol., puis à 75 %. On obtient des arômes moyens à prononcés, beaucoup de caractère, jamais un alcool neutre.",
   "A pot still works in batches, like a washing machine: fill it, run the cycle, then empty and clean it before the next load. One pass is not enough, so most distillers run it twice: from about 10% abv to about 25%, then to about 75%. The result has medium to pronounced aromas and lots of character, but is never neutral."),
  v:()=>spF(fChip(160,22,w3("un lotto alla volta","un lot à la fois","one batch at a time"))+spAbv(36,156,90,10,w3("fermentato","fermenté","fermented"),"#e9dc8c",.2)+spPotStill(78,156,.34)+spAbv(156,156,90,25,w3("1ª distillazione","1re distillation","1st distillation"),"#e9dc8c",1.2)+spPotStill(198,156,.34)+spAbv(282,156,90,75,w3("2ª distillazione","2e distillation","2nd distillation"),"#d4a23a",2.2)+fD(3.2,fChip(220,186,w3("mai neutro","jamais neutre","never neutral"),"#8c1d40")))},
 {h:I3_("L'alambicco a colonna","La colonne à distiller","The column still"),
  c:I3_("La colonna è nata per lavorare senza fermarsi e raggiungere gradi alti. È una struttura verticale divisa in tante sezioni. Il vapore caldo sale mentre il liquido scende: è come avere molte distillazioni impilate, tutte nello stesso momento. Il distillato più forte si trova in cima, ed è lì che esce.",
   "La colonne est née pour fonctionner sans arrêt et atteindre des degrés élevés. C'est une structure verticale divisée en nombreuses sections. La vapeur chaude monte pendant que le liquide descend : comme si l'on empilait de nombreuses distillations, toutes en même temps. L'alcool le plus fort se trouve en haut, et c'est là qu'il sort.",
   "The column still was designed to run without stopping and to reach high strengths. It is a vertical structure divided into many sections. Hot vapour rises while liquid flows down: it is like many distillations stacked on top of one another, all happening at once. The strongest spirit is at the top, and that is where it leaves the still."),
  v:()=>spF(spColumn(150,182,160,9)+fD(.6,fChip(66,154,w3("vapore","vapeur","steam")))+fCall(144,120,70,100,w3("il vapore sale","la vapeur monte","vapour rises"),1.2)+fCall(162,70,236,96,w3("il liquido scende","le liquide descend","liquid flows down"),2)+fD(2.8,fChip(250,44,w3("il più forte in cima","le plus fort en haut","strongest at the top"),"#8c1d40"))+fD(3.4,fChip(250,150,w3("in continuo","en continu","continuous"),"#5e8c31")))},
 {h:I3_("Colonna corta o alta","Colonne courte ou haute","Short or tall column"),
  c:I3_("Non tutte le colonne sono uguali. Una colonna corta, con poche sezioni, dà un distillato di grado più basso con aromi medi o pronunciati, vicino a quello di un alambicco discontinuo. Una colonna alta, con molte sezioni, dà un distillato leggero; le più alte arrivano al 95–96% vol.: un distillato neutro, quasi senza odore, base della maggior parte delle vodka.",
   "Toutes les colonnes ne se valent pas. Une colonne courte, avec peu de sections, donne une eau-de-vie de degré plus bas aux arômes moyens ou prononcés, proche de celle d'un alambic à repasse. Une haute colonne, avec beaucoup de sections, donne un alcool léger ; les plus hautes atteignent 95–96 % vol. : un alcool neutre, presque sans odeur, base de la plupart des vodkas.",
   "Not all columns are alike. A short column with few sections gives a lower-strength spirit with medium or pronounced aromas, close to a pot still spirit. A tall column with many sections gives a light spirit, and the very tallest reach 95 to 96% abv: a neutral spirit with almost no smell, the base of most vodkas."),
  v:()=>spF(spColumn(80,178,74,3,{steam:false})+fD(.6,fChip(80,82,w3("colonna corta","colonne courte","short column"))+fChip(80,194,w3("aromatico","aromatique","flavourful"),"#5e8c31"))
   +fD(1.4,spColumn(220,178,156,11,{steam:false,liq:"#dfe9f0"})+fChip(150,40,w3("colonna alta","haute colonne","tall column"))+fChip(240,194,w3("leggero → neutro","léger → neutre","light → neutral"),"#5c646b"))+fD(2.4,fChip(280,90,"95–96%","#d4a23a","#2a1b20")))}
]},
/* ===================== p2 ===================== */
{id:"s1_flavour", sec:"v", ch:"p2", ic:"order", t:I3_("Gusto, dolcezza e colore","Goût, douceur et couleur","Flavour, sweetness and colour"), s:[
 {h:I3_("Da dove viene il gusto","D'où vient le goût","Where flavour comes from"),
  c:I3_("Il gusto di un distillato si costruisce passo dopo passo. La materia prima pone le basi: l'uva dà note fruttate e floreali, l'agave note erbacee e pepate. La fermentazione aggiunge altri aromi, soprattutto fruttati. La distillazione decide quanto ne resta: a grado basso gli aromi restano intensi, a grado molto alto quasi spariscono.",
   "Le goût d'un spiritueux se construit pas à pas. La matière première pose les bases : le raisin apporte des notes fruitées et florales, l'agave des notes herbacées et poivrées. La fermentation ajoute d'autres arômes, surtout fruités. La distillation décide de ce qui reste : à bas degré les arômes restent intenses, à très haut degré ils disparaissent presque.",
   "A spirit's flavour is built step by step. The raw material lays the foundation: grapes bring fruity and floral notes, agave herbal and peppery ones. Fermentation adds more aromas, mostly fruity. Distillation then decides how much survives: at a low strength the aromas stay intense, at a very high strength they almost vanish."),
  v:()=>spF([w3("Materia prima","Matière première","Raw material"),w3("Fermentazione","Fermentation","Fermentation"),w3("Grado di distillazione","Degré de distillation","Distillation strength")].map((l,i)=>fD(.3+i*.9,fBox(10+i*104,20,92,30,l)+(i<2?fArrow(`M${103+i*104} 35H${113+i*104}`):""))).join("")
   +fD(.6,fBunch(40,74,1.4,"#d8e08a")+spAgave(76,130,.7)+fChip(56,156,w3("fruttato · erbaceo","fruité · herbacé","fruity · herbal"),"#5e8c31"))
   +fD(1.5,fYeast(144,96)+fYeast(170,110)+fYeast(152,124)+fChip(160,156,w3("+ fruttato","+ fruité","+ fruity"),"#5e8c31"))
   +fD(2.4,spAbv(250,140,70,65,"",null,2.4,1)+spAbv(282,140,70,95,"","#9fd3f0",2.8,1)+fChip(266,170,w3("basso = intenso","bas = intense","low = intense"),"#8c1d40")))},
 {h:I3_("Incolore, secco, e tre strade","Incolore, sec, et trois voies","Colourless, dry, and three routes"),
  c:I3_("Qualunque sia l'origine, un distillato esce dall'alambicco incolore e secco, cioè senza zucchero. Poi il produttore prende una di tre strade, spesso imposte dalla legge: lasciarlo non invecchiato, per poco in acciaio inox; invecchiarlo in botti di rovere, di solito per anni; oppure aromatizzarlo con qualcosa che non sia il legno, come per il gin.",
   "Quelle que soit son origine, une eau-de-vie sort de l'alambic incolore et sèche, c'est-à-dire sans sucre. Le producteur prend alors l'une de trois voies, souvent imposées par la loi : la laisser non vieillie, brièvement en cuve inox ; la vieillir en fût de chêne, souvent des années ; ou l'aromatiser avec autre chose que le bois, comme le gin.",
   "Whatever its origin, a spirit leaves the still colourless and dry, meaning with no sugar. The producer then takes one of three routes, often set by law: keep it unaged, briefly in stainless steel; age it in oak barrels, usually for years; or flavour it with something other than wood, as happens with gin."),
  v:()=>spF(spTulip(52,120,"rgba(230,240,255,.6)",1.3)+fChip(52,152,w3("incolore","incolore","colourless"))+fChip(52,174,w3("secco","sec","dry"))
   +fD(.8,fArrow("M86 96Q120 60 150 50")+spSteel(170,26,44,46)+fT(266,52,w3("non invecchiato","non vieilli","unaged"),10,null,"middle"))
   +fD(1.6,fArrow("M88 104H150")+fBarrel(192,104,.75)+fT(266,108,w3("in rovere","en fût de chêne","oak-aged"),10))
   +fD(2.4,fArrow("M86 112Q120 150 150 160")+spJuniper(190,156,.9)+fT(266,164,w3("aromatizzato","aromatisé","flavoured"),10))+fD(3.2,fChip(160,192,w3("spesso per legge","souvent par la loi","often set by law"),"#8c1d40")))},
 {h:I3_("Acciaio o rovere: il colore","Inox ou chêne : la couleur","Steel or oak: colour"),
  c:I3_("L'acciaio inox non cede nulla: il distillato non invecchiato resta limpido e conserva gli aromi nati nell'alambicco. Il rovere invece lavora. Dà colore in una sequenza che va dal limone all'oro, poi all'ambra e, molto raramente, al marrone. Più la botte è nuova e più lunga la sosta, più il colore è profondo.",
   "L'inox ne cède rien : l'eau-de-vie non vieillie reste limpide et garde les arômes nés dans l'alambic. Le chêne, lui, travaille. Il apporte la couleur selon une suite qui va du citron à l'or, puis à l'ambre et, très rarement, au brun. Plus le fût est neuf et le séjour long, plus la couleur est profonde.",
   "Stainless steel gives nothing away: an unaged spirit stays clear and keeps the aromas born in the still. Oak does real work. It adds colour in a sequence that runs from lemon to gold, then amber and, very rarely, brown. The newer the barrel and the longer the stay, the deeper the colour."),
  v:()=>spF(spSteel(30,40,60,80)+fChip(60,138,w3("non cede nulla","ne cède rien","adds nothing"))+fD(.8,fBarrel(220,80,1,{cut:1,col:"#d9a441"})+fChip(220,138,w3("dà colore","donne la couleur","adds colour"),"#8a5a33"))
   +spSwatches(94,172,["#f3eaa0","#e8c25a","#c98a3a","#7a4a22"],null,1.6)+[w3("limone","citron","lemon"),w3("oro","or","gold"),w3("ambra","ambre","amber"),w3("marrone","brun","brown")].map((l,i)=>fD(1.6+i*.35,fT(94+i*44,196,l,8.5))).join(""))},
 {h:I3_("Botte nuova, botte usata","Fût neuf, fût usagé","New barrel, used barrel"),
  c:I3_("Il rovere porta anche aromi: vaniglia, cannella, chiodi di garofano, cocco. Una botte nuova, mai usata, ne dà molti. Una botte già usata ne dà meno, e un po' meno a ogni nuovo riempimento, come una bustina di tè messa in infusione più volte. Botti nuove per un'impronta forte, usate per un tocco più leggero.",
   "Le chêne apporte aussi des arômes : vanille, cannelle, clou de girofle, noix de coco. Un fût neuf, jamais utilisé, en donne beaucoup. Un fût usagé en donne moins, et un peu moins à chaque remplissage, comme un sachet de thé infusé plusieurs fois. Fûts neufs pour une empreinte forte, usagés pour une touche plus légère.",
   "Oak also brings aromas: vanilla, cinnamon, cloves and coconut. A new barrel, never used before, gives a lot of them. A used barrel gives less, and a little less again with every refill, just like a tea bag steeped several times. New barrels mean a strong oak imprint; used ones a gentler touch."),
  v:()=>spF(fBarrel(80,120,1.1)+fChip(80,168,w3("botte nuova","fût neuf","new barrel"),"#8c1d40")+[w3("vaniglia","vanille","vanilla"),w3("cannella","cannelle","cinnamon"),w3("chiodi di garofano","clou de girofle","cloves"),w3("cocco","coco","coconut")].map((l,i)=>fD(.5+i*.5,fChip(80+(i%2?34:-34),34+i*18,l,"rgba(212,162,58,.85)","#2a1b20"))).join("")
   +fD(2.6,`<g opacity=".75">${fBarrel(240,120,1.1)}</g>`+fChip(240,168,w3("botte usata","fût usagé","used barrel"),"#5c646b")+fChip(240,70,w3("vaniglia","vanille","vanilla"),"rgba(212,162,58,.45)")))},
 {h:I3_("Il tempo concentra","Le temps concentre","Time concentrates"),
  c:I3_("Conta anche il tempo. Attraverso il legno, acqua ed etanolo evaporano lentamente, e ciò che resta si concentra. Dopo molti anni, a volte decenni, compaiono nuovi aromi: torta di frutta, frutta secca, cuoio, cera per mobili. Per questo un distillato molto invecchiato sembra stratificato, e svela una sfumatura dopo l'altra.",
   "Le temps compte aussi. À travers le bois, l'eau et l'éthanol s'évaporent lentement, et ce qui reste se concentre. Après de nombreuses années, parfois des décennies, de nouveaux arômes apparaissent : cake aux fruits, fruits secs, cuir, cire à meubles. C'est pourquoi un spiritueux longuement vieilli paraît étagé, dévoilant une nuance après l'autre.",
   "Time matters too. Through the wood, water and ethanol slowly evaporate, so what remains becomes more concentrated. After many years, sometimes decades, new aromas appear: fruit cake, dried fruit, leather and wood polish. That is why a long-aged spirit feels layered, revealing one shade of flavour after another."),
  v:()=>spF(fBarrel(100,120,1.6,{cut:1,col:"#b9742e"})+spVapour(100,80,4,34)+fD(.3,fChip(100,40,w3("evaporazione","évaporation","evaporation")))+fClock(36,60,w3("anni","années","years"))
   +[w3("torta di frutta","cake aux fruits","fruit cake"),w3("frutta secca","fruits secs","dried fruit"),w3("cuoio","cuir","leather"),w3("cera per mobili","cire à meubles","wood polish")].map((l,i)=>fD(1+i*.6,fChip(250,62+i*28,l,"rgba(140,29,64,.75)"))).join(""))},
 {h:I3_("Assemblare: costanza e complessità","Assembler : constance et complexité","Blending: consistency and complexity"),
  c:I3_("Ogni botte è un piccolo mondo: due botti riempite lo stesso giorno non danno mai lo stesso risultato. Così il maestro assemblatore unisce molte botti, con due scopi. La costanza: la stessa bottiglia deve avere sempre lo stesso gusto. La complessità: unire distillati di carattere diverso è il modo più semplice per creare profondità.",
   "Chaque fût est un petit monde : deux fûts remplis le même jour ne donnent jamais exactement le même résultat. Le maître de chai assemble donc de nombreux fûts, avec deux buts. La constance : la même bouteille doit toujours avoir le même goût. La complexité : réunir des eaux-de-vie de caractères différents est le moyen le plus simple de créer de la profondeur.",
   "Every barrel is its own little world: two barrels filled on the same day never turn out exactly alike. So the blender combines many barrels, with two aims. Consistency: the same bottle should taste the same every time. Complexity: bringing together spirits with different characters is the easiest way to create depth."),
  v:()=>spF(["#e8c25a","#c98a3a","#d9a441","#a8662a"].map((c,i)=>fBarrel(46+i*76,48,.62,{cut:1,col:c})+fD(.5+i*.3,spPour(46+i*76,64,160,112,c,2.4))).join("")+fD(.4,fTank(124,104,72,70,{col:"#c98a3a"}))
   +fD(2,fChip(60,150,w3("costanza","constance","consistency"),"#5e8c31"))+fD(2.6,fChip(262,150,w3("complessità","complexité","complexity"),"#8c1d40")))},
 {h:I3_("Tre modi di aromatizzare","Trois façons d'aromatiser","Three ways to add flavour"),
  c:I3_("Gli aromi diversi dal legno si aggiungono in tre modi. Si ridistilla il distillato con erbe, semi o spezie: esce aromatizzato ma incolore. Si lasciano le piante in infusione nel distillato, come una tisana fredda: aroma e colore passano piano piano. Oppure si aggiungono aromi già pronti, naturali o artificiali.",
   "Les arômes autres que le bois s'ajoutent de trois façons. On redistille l'alcool avec des herbes, des graines ou des épices : il sort aromatisé mais incolore. On laisse les plantes infuser dans l'alcool, comme une tisane froide : arôme et couleur passent lentement. Ou l'on ajoute des arômes tout prêts, naturels ou artificiels.",
   "Flavours other than wood can be added in three ways. The spirit can be redistilled with herbs, seeds or spices: it comes out flavoured but colourless. The plants can soak in the spirit, like a cold herbal tea, so flavour and colour seep out slowly. Or ready-made flavourings, natural or artificial, are simply added."),
  v:()=>spF(spPotStill(34,150,.42)+spJuniper(30,70,.7)+fChip(54,182,w3("ridistillazione","redistillation","redistillation"))
   +fD(1,`<path d="M134 80H186V146Q186 152 180 152H140Q134 152 134 146Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><rect x="137" y="96" width="46" height="54" rx="3" fill="#e9dc8c" opacity=".3"><animate attributeName="fill" from="#e9dc8c" to="#c0552a" dur="4s" begin="1s" fill="freeze"/><animate attributeName="opacity" from=".3" to=".8" dur="4s" begin="1s" fill="freeze"/></rect>`+spPeel(152,124)+spSeeds(160,132)+fLeaf(170,120,.6,30)+fChip(160,182,w3("macerazione","macération","maceration")))
   +fD(2,spBitters(262,130,true)+spTumbler(262,170,"rgba(230,240,255,.6)",1)+fChip(266,182,w3("aromi aggiunti","arômes ajoutés","added flavourings"))))},
 {h:I3_("La diluizione","La dilution","Dilution"),
  c:I3_("L'ultima mossa prima dell'imbottigliamento è quasi sempre la diluizione. Si aggiunge acqua del tutto pura, e la maggior parte dei distillati scende al 40% vol. Il motivo è pratico: un alcol troppo forte anestetizza il palato, e il distillato non si può né degustare né apprezzare. L'acqua non porta aromi: abbassa solo il grado.",
   "Le dernier geste avant la mise en bouteille est presque toujours la dilution. On ajoute de l'eau parfaitement pure, et la plupart des spiritueux descendent à 40 % vol. La raison est pratique : un alcool trop fort anesthésie le palais, et l'on ne peut ni déguster ni apprécier le spiritueux. L'eau n'apporte aucun arôme : elle baisse seulement le degré.",
   "The last move before bottling is almost always dilution. Completely pure water is added, and most spirits come down to 40% abv. The reason is practical: alcohol that is too strong numbs the palate, so the spirit cannot be tasted or enjoyed. The water adds no aroma; it simply lowers the strength."),
  v:()=>spF(spAbv(40,160,110,70,w3("prima","avant","before"),"#f6a43a",.2)+fTank(100,80,70,90,{col:"#d9a441"})+spJug(204,74,1,150,84)+fD(.4,fChip(214,30,w3("acqua pura","eau pure","pure water"),"#3f7fa8"))
   +fD(1.4,fArrow("M176 140H226")+spBottle(250,140,"#d9a441",{lab:"40%"}))+spAbv(296,160,110,40,w3("in bottiglia","en bouteille","bottled"),"#d4a23a",2))},
 {h:I3_("La dolcezza è aggiunta","La douceur est ajoutée","Sweetness is added"),
  c:I3_("Ogni distillato esce secco dall'alambicco, quindi la dolcezza che si sente in bocca è stata aggiunta dopo, di solito come zucchero. Attenzione alla parola: dolce indica solo il sapore dello zucchero. Un whiskey con aromi di vaniglia e frutta può sembrare dolce al naso, ma senza zucchero aggiunto resta secco in bocca.",
   "Toute eau-de-vie sort sèche de l'alambic : la douceur perçue en bouche a donc été ajoutée après, en général sous forme de sucre. Attention au mot : sucré ne désigne que le goût du sucre. Un whiskey aux arômes de vanille et de fruits peut sembler doux au nez, mais sans sucre ajouté il reste sec en bouche.",
   "Every spirit leaves the still dry, so any sweetness you taste was added afterwards, usually as sugar. Careful with the word: sweet refers only to the taste of sugar. A whiskey with vanilla and fruity aromas may smell sweet, but with no added sugar it is still dry on the palate."),
  v:()=>spF(`<g>${spSugar(70,40,2)}<animateTransform attributeName="transform" type="translate" values="0 0;0 70;0 70" keyTimes="0;.5;1" dur="2.4s" repeatCount="indefinite"/></g>`+spTulip(76,160,"#d9a441",1.4)+fChip(76,190,w3("zucchero aggiunto","sucre ajouté","added sugar"),"#8c1d40")
   +fD(1.4,spTulip(236,160,"#d9a441",1.4)+spVapour(236,90,3,24,"#f3cd8a")+fChip(236,40,w3("profuma di vaniglia","sent la vanille","smells of vanilla")))+fD(2.6,fChip(236,190,w3("ma in bocca è secco","mais sec en bouche","but tastes dry"),"#5c646b")))},
 {h:I3_("Il colore non prova l'età","La couleur ne prouve pas l'âge","Colour does not prove age"),
  c:I3_("Il colore ha più fonti. Il rovere è la più naturale. Il caramello si usa in quantità minime per tenere ogni lotto della stessa tinta; usato bene, non dà dolcezza né aroma. Molti liquori ricevono coloranti naturali o artificiali, a volte vivacissimi. Quindi il colore non prova l'età: anche un distillato non invecchiato può essere scuro.",
   "La couleur a plusieurs sources. Le chêne est la plus naturelle. Le caramel s'utilise en quantités infimes pour garder chaque lot de la même teinte ; bien dosé, il n'apporte ni douceur ni arôme. Beaucoup de liqueurs reçoivent des colorants naturels ou artificiels, parfois très vifs. La couleur ne prouve donc pas l'âge : un spiritueux non vieilli peut être foncé.",
   "Colour has several sources. Oak is the most natural. Caramel is used in tiny amounts to keep every batch the same shade; used properly it adds no sweetness or aroma. Many liqueurs get natural or artificial colourings, sometimes very bright. So colour is no proof of age: an unaged spirit can be deeply coloured."),
  v:()=>spF(fBarrel(50,64,.7)+fT(50,104,w3("rovere","chêne","oak"),9.5)+fD(.6,spMolasses(160,78)+fT(160,104,w3("caramello","caramel","caramel"),9.5))+fD(1.2,spBottle(252,64,"#3fae6a",{s:.6})+spBottle(278,64,"#3f6fd0",{s:.6})+fT(266,104,w3("coloranti","colorants","colourings"),9.5))
   +fD(2,spBottle(110,160,"#7a4a22",{s:.7})+fChip(110,192,w3("non invecchiato","non vieilli","unaged"),"#8c1d40")+spBottle(210,160,"#e8c25a",{s:.7})+fChip(210,192,w3("anni in botte","des années en fût","years in oak"),"#5e8c31"))+fD(2.8,fT(160,150,"≠",22,"#f3cd8a")))}
]},
/* ===================== s1 Cognac ===================== */
{id:"s1_cognac", sec:"c", ch:"s1", ic:"grapes", t:I3_("Cognac","Cognac","Cognac"), s:[
 {h:I3_("Un brandy d'uva con un indirizzo","Un brandy de raisin avec une adresse","A grape brandy with an address"),
  c:I3_("Un brandy d'uva è semplicemente vino distillato, e il Cognac è il più famoso di tutti. Viene da una zona ben delimitata del sud-ovest della Francia, a nord della città di Bordeaux. Solo le uve coltivate lì possono diventare Cognac: il nome è un indirizzo preciso, non una ricetta da copiare altrove.",
   "Un brandy de raisin, c'est tout simplement du vin distillé, et le Cognac est le plus célèbre de tous. Il vient d'une zone bien délimitée du sud-ouest de la France, au nord de la ville de Bordeaux. Seuls les raisins cultivés là peuvent devenir du Cognac : le nom est une adresse précise, pas une recette à copier ailleurs.",
   "A grape brandy is simply distilled wine, and Cognac is the most famous of them all. It comes from a clearly defined area of south-west France, north of the town of Bordeaux. Only grapes grown there can become Cognac: the name is a precise address, not a recipe that can be copied elsewhere."),
  v:()=>spF(`<path d="M150 22L196 36L228 64L216 108L224 148L184 176L136 172L104 160L112 120L94 84L120 52Z" fill="#4f6e45" stroke="#e8dccf" stroke-width="1.4" opacity=".9"/>`+fT(170,100,"France",11,"rgba(255,244,220,.6)")
   +fD(.6,`<ellipse cx="122" cy="116" rx="16" ry="10" fill="#d4a23a" opacity=".75"><animate attributeName="opacity" values=".5;.9;.5" dur="2s" repeatCount="indefinite"/></ellipse>`)+fD(.6,spPin(122,114))+fCall(122,110,50,70,"Cognac",1)
   +fD(1.6,spPin(114,146,"#5c646b"))+fCall(110,144,50,162,"Bordeaux",1.8)+fD(2.6,fChip(270,40,w3("sud-ovest","sud-ouest","south-west"))+fChip(270,64,w3("a nord di Bordeaux","au nord de Bordeaux","north of Bordeaux"),"#8c1d40")))},
 {h:I3_("Prima di tutto, un vino","D'abord, un vin","First of all, a wine"),
  c:I3_("Le uve di questa zona danno al Cognac i suoi aromi di base, fruttati e floreali. Dopo la vendemmia si pressano, e il succo zuccherino non ha bisogno di lavorazioni complicate: fermenta subito. Ne nasce un vino, ed è questo vino, non l'uva, che va nell'alambicco. Prima di essere un distillato, il Cognac è un vino.",
   "Les raisins de cette zone donnent au Cognac ses arômes de base, fruités et floraux. Après la vendange, on les presse, et le jus sucré n'a besoin d'aucune transformation compliquée : il fermente tout de suite. On obtient un vin, et c'est ce vin, pas le raisin, qui part à l'alambic. Avant d'être un spiritueux, le Cognac est un vin.",
   "The grapes from this area give Cognac its basic aromas, fruity and floral. After harvest they are pressed, and the sugary juice needs no complicated processing: it is fermented straight away. The result is a wine, and it is this wine, not the grapes, that goes into the still. Before it is a spirit, Cognac is a wine."),
  v:()=>spF(fBunch(40,50,2.2,"#d8e08a")+fD(.4,fChip(40,128,w3("fruttato, floreale","fruité, floral","fruity, floral"),"#5e8c31"))+fD(.8,fArrow("M70 80H92")+fPress(96,56,"#e9dc8c","#c8d77a")+fT(150,150,w3("pressatura","pressurage","pressing"),9.5))
   +fD(1.8,fArrow("M210 80H226")+fTank(232,50,64,96,{col:"#e9dc8c",bub:6,lab:w3("vino","vin","wine")}))+fD(2.6,fChip(264,30,w3("fermenta subito","fermente aussitôt","fermented at once"),"#8c1d40")),"autumn")},
 {h:I3_("Due volte nell'alambicco discontinuo","Deux fois à l'alambic à repasse","Twice through the pot still"),
  c:I3_("Per il Cognac la legge non lascia scelta: il vino va distillato due volte in alambicco discontinuo, niente colonna. È un lavoro lento, a lotti, perché dopo ogni passaggio l'alambicco va svuotato e pulito. Gli alambicchi tradizionali del Cognac si scaldano con bruciatori a gas, e la serpentina sta in acqua fredda sempre rinnovata.",
   "Pour le Cognac, la loi ne laisse pas le choix : le vin doit être distillé deux fois à l'alambic à repasse, sans colonne. C'est un travail lent, par lots, car après chaque passage l'alambic doit être vidé et nettoyé. Les alambics traditionnels du Cognac sont chauffés par des brûleurs à gaz, et le serpentin baigne dans une eau froide sans cesse renouvelée.",
   "For Cognac the law leaves no choice: the wine must be distilled twice in a pot still, with no column allowed. It is slow, batch-by-batch work, because the still must be emptied and cleaned after every run. Traditional Cognac stills are heated with gas burners, and the condenser coil sits in constantly refreshed cold water."),
  v:()=>spF(spPotStill(42,158,.58)+fChip(42,40,"1")+fD(1.4,spPotStill(162,158,.58,{out:"rgba(240,235,215,.95)"})+fChip(162,40,"2"))+fD(.6,fChip(110,186,w3("bruciatori a gas","brûleurs à gaz","gas burners")))
   +fD(2.4,spColumn(284,150,90,5,{steam:false,out:false})+`<path d="M266 72L302 140M302 72L266 140" stroke="#e2622a" stroke-width="4" stroke-linecap="round"/>`+fChip(276,176,w3("per legge","par la loi","by law"),"#8c1d40")))},
 {h:I3_("Perché l'alambicco discontinuo","Pourquoi l'alambic à repasse","Why a pot still"),
  c:I3_("Perché tanta fatica? Perché l'alambicco discontinuo dà un distillato di grado relativamente basso, che conserva molto gusto e carattere: proprio ciò che serve al Cognac. Una colonna alta darebbe un distillato più leggero e meno espressivo, perdendo gran parte degli aromi fruttati e floreali dell'uva. La doppia distillazione protegge l'anima del vino.",
   "Pourquoi tant d'efforts ? Parce que l'alambic à repasse donne une eau-de-vie de degré relativement bas, qui garde beaucoup de goût et de caractère : exactement ce qu'il faut au Cognac. Une haute colonne donnerait un alcool plus léger et moins expressif, en perdant une grande partie des arômes fruités et floraux du raisin. La double distillation protège l'âme du vin.",
   "Why go to so much trouble? Because a pot still gives a spirit of relatively low strength that keeps plenty of flavour and character, exactly what Cognac needs. A tall column would make a lighter, less expressive spirit and lose much of the fruity and floral aromas of the grapes. Double distillation protects the soul of the wine."),
  v:()=>spF(spPotStill(30,150,.5)+fArrow("M100 110H112")+spTulip(132,150,"rgba(240,235,215,.7)",1.1)+spVapour(132,96,4,30,"#f6a43a")+fD(.8,fChip(92,40,w3("fruttato, floreale","fruité, floral","fruity, floral"),"#5e8c31")+fChip(92,186,w3("grado basso","degré bas","low strength"),"#8c1d40"))
   +fD(1.8,`<g opacity=".7">${spColumn(220,160,130,10,{steam:false,out:false})}</g>`+fArrow("M244 110H256")+spTulip(282,150,"rgba(230,240,255,.6)",1.1)+fChip(260,186,w3("più leggero","plus léger","lighter"),"#5c646b")))},
 {h:I3_("Almeno due anni in rovere","Au moins deux ans en fût de chêne","At least two years in oak"),
  c:I3_("Appena uscito dall'alambicco, il futuro Cognac non può ancora usare il nome: la legge chiede almeno due anni in botti di rovere. Il legno dà colore e aromi di vaniglia e tostato. I Cognac più pregiati restano in botte molto più a lungo, si concentrano e sviluppano note di torta di frutta, cuoio e cera per mobili.",
   "À la sortie de l'alambic, le futur Cognac ne peut pas encore porter son nom : la loi exige au moins deux ans en fût de chêne. Le bois apporte la couleur et des arômes de vanille et de grillé. Les plus beaux Cognacs restent bien plus longtemps en fût, se concentrent et développent des notes de cake aux fruits, de cuir et de cire à meubles.",
   "Fresh from the still, the future Cognac cannot use the name yet: the law requires at least two years in oak barrels. The wood gives colour and aromas of vanilla and toast. The finest Cognacs stay far longer, becoming concentrated and developing notes of fruit cake, leather and wood polish."),
  v:()=>spF(fBarrel(80,110,1.5,{cut:1,col:"#c98a3a"})+fClock(80,40,w3("2+ anni","2 ans et +","2+ years"))+fD(.8,fChip(80,160,w3("vaniglia, tostato","vanille, grillé","vanilla, toast"),"rgba(212,162,58,.85)","#2a1b20"))
   +fD(1.8,fT(240,40,w3("invecchiamento lungo","long vieillissement","long ageing"),10,"#f3cd8a"))+[w3("torta di frutta","cake aux fruits","fruit cake"),w3("cuoio","cuir","leather"),w3("cera per mobili","cire à meubles","wood polish")].map((l,i)=>fD(2.2+i*.5,fChip(240,70+i*28,l,"rgba(140,29,64,.75)"))).join(""))},
 {h:I3_("Assemblaggio, caramello, un po' di zucchero","Assemblage, caramel, un peu de sucre","Blending, caramel, a little sugar"),
  c:I3_("Quasi tutti i Cognac sono assemblaggi di distillati di età diverse: i più giovani portano freschezza, i più vecchi profondità, e insieme creano complessità. Prima della diluizione e dell'imbottigliamento si aggiunge spesso un po' di caramello, per tenere costante il colore, e un tocco di zucchero. Così un Cognac può sembrare un po' rotondo, pur essendo uscito secco dall'alambicco.",
   "Presque tous les Cognacs sont des assemblages d'eaux-de-vie d'âges différents : les plus jeunes apportent la fraîcheur, les plus vieilles la profondeur, et ensemble elles créent la complexité. Avant la dilution et la mise en bouteille, on ajoute souvent un peu de caramel, pour garder une couleur constante, et une pointe de sucre. Un Cognac peut donc sembler un peu rond, bien qu'il soit sorti sec de l'alambic.",
   "Nearly all Cognacs are blends of spirits of different ages: younger ones bring freshness, older ones depth, and together they build complexity. Before dilution and bottling it is common to add a little caramel, to keep the colour consistent, and a touch of sweetening. So a Cognac can feel slightly rounded, even though it left the still dry."),
  v:()=>spF(fBarrel(44,50,.6,{cut:1,col:"#e8c25a"})+fChip(44,82,w3("giovane: freschezza","jeune : fraîcheur","young: freshness"),"#5e8c31")+fBarrel(44,128,.6,{cut:1,col:"#9a5a22"})+fChip(44,160,w3("vecchio: profondità","vieux : profondeur","old: depth"),"#8c1d40")
   +fD(.6,spPour(70,50,128,96,"#e8c25a")+spPour(70,128,128,110,"#9a5a22"))+fD(.8,fTank(132,80,60,80,{col:"#c98a3a"}))
   +fD(1.8,spMolasses(232,70)+fT(232,90,w3("caramello","caramel","caramel"),9)+spSugar(222,128,2)+fT(232,142,w3("un po' di zucchero","un peu de sucre","a little sugar"),9))+fD(2.6,spBottle(290,140,"#b9742e",{s:.8,lab:"VSOP"})))},
 {h:I3_("VS, VSOP, XO","VS, VSOP, XO","VS, VSOP, XO"),
  c:I3_("Tre menzioni in etichetta indicano l'età, e si riferiscono sempre al distillato più giovane dell'assemblaggio. VS garantisce almeno 2 anni, VSOP almeno 4, XO almeno 10. Immagina una scala di tre gradini: 2, 4 e 10. Se un assemblaggio contiene un distillato di 5 anni e uno di 20, conta il 5: può essere un VSOP.",
   "Trois mentions sur l'étiquette indiquent l'âge, et elles se rapportent toujours à l'eau-de-vie la plus jeune de l'assemblage. VS garantit au moins 2 ans, VSOP au moins 4, XO au moins 10. Imaginez un escalier de trois marches : 2, 4 et 10. Si un assemblage contient une eau-de-vie de 5 ans et une de 20, c'est le 5 qui compte : ce peut être un VSOP.",
   "Three label terms show the age, and they always refer to the youngest spirit in the blend. VS means at least 2 years, VSOP at least 4, XO at least 10. Picture a staircase with three steps: 2, 4 and 10. If a blend contains a 5-year-old and a 20-year-old spirit, the 5 counts: it can be a VSOP."),
  v:()=>spF([["VS","2+",150,40],["VSOP","4+",112,78],["XO","10+",70,120]].map(([l,a,y,h],i)=>fD(.3+i*.6,`<rect x="${16+i*66}" y="${y}" width="62" height="${190-y}" rx="4" fill="${mixC("#e8c25a","#7a4a22",i/2)}" stroke="#2a1b20"/>`+fT(47+i*66,y+20,l,13,i>1?"#fff4dc":"#2a1b20")+fT(47+i*66,y+38,a+" "+w3("anni","ans","yrs"),10,i>1?"#fff4dc":"#2a1b20"))).join("")
   +fD(2.2,fBarrel(236,50,.5,{cut:1,col:"#e8c25a"})+fT(236,78,w3("5 anni","5 ans","5 yrs"),9.5)+fBarrel(290,50,.5,{cut:1,col:"#9a5a22"})+fT(290,78,w3("20 anni","20 ans","20 yrs"),9.5))
   +fD(3,fArrow("M262 88V108")+fChip(262,124,w3("conta il più giovane","le plus jeune compte","youngest counts"),"#8c1d40")+fChip(262,152,"→ VSOP","#d4a23a","#2a1b20")))}
]},
/* ===================== s2 Vodka ===================== */
{id:"s1_vodka", sec:"c", ch:"s2", ic:"maps", t:I3_("Vodka","Vodka","Vodka"), s:[
 {h:I3_("Qualsiasi materia prima, ovunque","N'importe quelle matière, partout","Any raw material, anywhere"),
  c:I3_("La vodka è il distillato più libero di tutti. Si può fare in qualsiasi paese e da qualsiasi materia prima vegetale. Non c'è una zona d'origine obbligatoria, come per il Cognac, né un ingrediente imposto, come l'agave per la Tequila. A fare una vodka non è il luogo né la pianta: è il grado a cui si distilla.",
   "La vodka est le spiritueux le plus libre de tous. On peut la faire dans n'importe quel pays et avec n'importe quelle matière première végétale. Pas de zone d'origine obligatoire, comme pour le Cognac, ni d'ingrédient imposé, comme l'agave pour la Tequila. Ce qui fait une vodka, ce n'est ni le lieu ni la plante : c'est le degré de distillation.",
   "Vodka is the freest spirit of all. It can be made in any country and from any plant raw material. There is no compulsory area of origin, as with Cognac, and no required ingredient, as agave is for Tequila. What makes a spirit vodka is neither the place nor the plant: it is the strength it is distilled to."),
  v:()=>spF(`<circle cx="160" cy="96" r="54" fill="#3f6f98" stroke="#e8dccf" stroke-width="1.4"/><path d="M122 70q16 -14 30 -4q4 14 -10 18q-14 10 -20 -14ZM166 60q22 -6 30 10q-4 16 -20 12q-14 -8 -10 -22ZM150 110q18 -4 22 12q-6 18 -18 14q-8 -10 -4 -26Z" fill="#5e8c4a"/><ellipse cx="160" cy="96" rx="54" ry="18" fill="none" stroke="rgba(255,255,255,.25)"/><path d="M160 42V150" stroke="rgba(255,255,255,.25)"/>`
   +[[136,74],[180,70],[160,124],[196,100]].map(([x,y],i)=>fD(.4+i*.3,spPin(x,y))).join("")
   +fD(1.4,fBunch(40,30,1.4,"#6b2d5c")+spCorn(282,80,.7)+spPotato(276,150,.9)+spCane(40,170,.4)+spBarley(70,170,.7))+fD(2.4,fChip(160,184,w3("conta il grado","défini par le degré","defined by strength"),"#8c1d40")))},
 {h:I3_("Le materie prime della vodka di qualità","Les matières des vodkas de qualité","Premium raw materials"),
  c:I3_("Anche se la scelta è libera, alcune materie prime sono legate alla vodka di qualità: i cereali, soprattutto orzo, frumento e segale, e le patate. Dopo la lavorazione che crea un liquido zuccherino, si fermenta come per ogni altro distillato. I primi due passaggi sono quelli classici; il vero tratto distintivo della vodka arriva con il terzo, la distillazione.",
   "Même si le choix est libre, certaines matières premières sont associées aux vodkas de qualité : les céréales, surtout l'orge, le blé et le seigle, et les pommes de terre. Après la transformation qui crée un liquide sucré, on fait fermenter comme pour tout autre spiritueux. Les deux premières étapes sont classiques ; le vrai trait distinctif de la vodka arrive avec la troisième, la distillation.",
   "Although the choice is open, some raw materials are linked with premium vodka: cereals, especially barley, wheat and rye, and potatoes. After processing to create a sugary liquid, it is fermented just like any other spirit. The first two steps are the classic ones; vodka's real distinguishing feature arrives with the third, distillation."),
  v:()=>spF([[spBarley(36,120,.9),w3("orzo","orge","barley")],[spBarley(96,120,.9,"#e8cf8a"),w3("frumento","blé","wheat")],[spBarley(156,120,.9,"#a88a5a"),w3("segale","seigle","rye")],[spPotato(218,110,1.4),w3("patate","pommes de terre","potatoes")]].map(([g,l],i)=>fD(.3+i*.5,g+fT([36,96,156,218][i],140,l,10,"#3a2a2f"))).join("")
   +fD(2.4,fArrow("M244 90H254")+fTank(258,60,50,80,{col:"#e9dc8c",bub:5})+fT(283,160,w3("fermentazione","fermentation","fermentation"),8.5,"#3a2a2f")),"summer")},
 {h:I3_("Un distillato neutro","Un alcool neutre","A neutral spirit"),
  c:I3_("La vodka è un distillato neutro diluito. Per essere neutro, il distillato deve arrivare almeno al 95 o 96% vol., secondo la legge del paese che la produce. Un grado così alto si ottiene solo con l'alambicco a colonna, anche se qualcuno usa l'alambicco discontinuo per una parte del processo. A quel livello non resta quasi nessun aroma.",
   "La vodka est un alcool neutre dilué. Pour être neutre, l'alcool doit atteindre au moins 95 ou 96 % vol., selon la loi du pays producteur. Un degré aussi élevé ne s'obtient qu'avec une colonne, même si certains utilisent l'alambic à repasse pour une partie du processus. À ce niveau, il ne reste presque aucun arôme.",
   "Vodka is a diluted neutral spirit. To count as neutral, the spirit must reach at least 95 or 96% abv, depending on the law of the producing country. Such a high strength needs a column still, although some producers use pot stills for part of the process. At that level almost no aroma remains."),
  v:()=>spF(spColumn(120,182,166,12,{liq:"#dfe9f0"})+spAbv(230,160,120,96,"",`#9fd3f0`,.6)+fD(2,fChip(230,180,w3("almeno 95–96%","au moins 95–96 %","at least 95–96%"),"#8c1d40"))+fD(2.8,fChip(52,40,w3("colonna","colonne","column still"))+fChip(280,64,w3("neutro","neutre","neutral"),"#5c646b")))},
 {h:I3_("Non invecchiata, diluita","Non vieillie, diluée","Unaged, then diluted"),
  c:I3_("Dopo la distillazione la vodka non va in botte: resta non invecchiata e limpida. Poi si diluisce con acqua pura fino al grado di imbottigliamento, di solito il 40% vol. Pensala come una tela bianca: tutto il lavoro del produttore sta nel togliere, non nell'aggiungere, così nel bicchiere arriva un distillato pulito, quasi senza odore.",
   "Après la distillation, la vodka ne va pas en fût : elle reste non vieillie et limpide. Elle est ensuite diluée à l'eau pure jusqu'au degré de mise en bouteille, en général 40 % vol. Voyez-la comme une toile blanche : tout le travail du producteur consiste à enlever, non à ajouter, pour qu'arrive dans le verre un alcool net, presque sans odeur.",
   "After distillation, vodka does not go into barrels: it stays unaged and clear. It is then diluted with pure water to bottling strength, typically 40% abv. Think of a blank canvas: the producer's effort goes into taking away rather than adding, so the glass holds a clean spirit with almost no smell."),
  v:()=>spF(fBarrel(50,56,.6)+`<path d="M28 38L72 74M72 38L28 74" stroke="#e2622a" stroke-width="4" stroke-linecap="round"/>`+fChip(50,98,w3("niente botte","pas de fût","no barrel"),"#8c1d40")
   +spSteel(110,70,60,90)+fD(.8,spJug(206,70,1,150,76)+fChip(218,30,w3("acqua pura","eau pure","pure water"),"#3f7fa8"))+fD(1.8,fArrow("M176 140H232")+spBottle(262,140,"rgba(230,240,255,.55)",{lab:"40%"}))+fD(2.6,fChip(130,186,w3("una tela bianca","une toile blanche","a blank canvas"))))},
 {h:I3_("Perfetta per i drink","Parfaite pour les mélanges","Made for mixing"),
  c:I3_("La maggior parte delle vodka punta alla neutralità più completa possibile. Proprio questa assenza di aroma la rende così amata nei drink e nei cocktail: si fonde con succhi, bibite e liquori senza imporre il suo gusto. Il barman che vuole un drink più forte senza cambiarne il sapore prende per prima la vodka.",
   "La plupart des vodkas visent la neutralité la plus complète possible. C'est justement cette absence d'arômes qui la rend si populaire dans les mélanges et les cocktails : elle se fond dans les jus, les sodas et les liqueurs sans imposer son goût. Le barman qui veut un verre plus fort sans en changer le goût prend d'abord la vodka.",
   "Most vodka aims for the most complete neutrality possible. That lack of aroma is exactly what makes it so popular in mixed drinks and cocktails: it blends into juices, sodas and liqueurs without imposing its own taste. A bartender who wants a stronger drink without changing its flavour reaches for vodka first."),
  v:()=>spF(spBottle(44,120,"rgba(230,240,255,.55)",{s:.9,lab:"VODKA"})+fD(.6,spPour(58,78,120,96,"rgba(230,240,255,.8)",2)+spCocktail(130,170,"highball","#f0a060",{ice:1,gar:ORANGE})+fT(130,190,w3("succo","jus","juice"),9))
   +fD(1.2,spCocktail(196,170,"highball","rgba(220,235,240,.6)",{ice:1,bub:1,gar:LIME})+fT(196,190,"soda",9))+fD(1.8,spCocktail(266,170,"coupe","#c03a5a")+fT(266,190,w3("liquore","liqueur","liqueur"),9))
   +fD(2.6,fChip(200,40,w3("aggiunge alcol","ajoute de l'alcool","adds alcohol"),"#8c1d40")+fChip(200,66,w3("non il suo gusto","pas son goût","not its taste"),"#5c646b")))},
 {h:I3_("Un pizzico di carattere","Une pointe de caractère","A hint of character"),
  c:I3_("Alcune vodka però conservano un pizzico di carattere: lievi tocchi della materia prima, come una nota di cereale o di patata, al naso e in bocca. Restano molto delicati, lontanissimi da un whisky o da un brandy, e si descrivono comunque come neutre. È come l'acqua minerale accanto all'acqua distillata: una differenza sottile, ma percepibile.",
   "Certaines vodkas gardent toutefois une pointe de caractère : de légères touches de la matière première, comme une note de céréale ou de pomme de terre, au nez et en bouche. Elles restent très délicates, loin d'un whisky ou d'un brandy, et se décrivent toujours comme neutres. C'est comme une eau minérale à côté d'une eau distillée : subtil, mais perceptible.",
   "Some vodkas, however, keep a hint of character: faint touches of the raw material, such as a note of grain or potato, on the nose and palate. They stay very delicate, nowhere near a whisky or a brandy, and are still correctly described as neutral. It is like mineral water next to distilled water: subtle, but noticeable."),
  v:()=>spF(spTulip(90,150,"rgba(230,240,255,.6)",1.4)+fChip(90,44,w3("neutra","neutre","neutral"),"#5c646b")
   +fD(1,spTulip(230,150,"rgba(235,235,220,.6)",1.4)+spVapour(230,84,2,22,"rgba(240,220,160,.55)")+`<g opacity=".8">${spBarley(206,70,.45)}${spPotato(258,58,.6)}</g>`)+fD(1.8,fChip(230,44,w3("lieve cereale o patata","légère céréale, patate","faint grain or potato"),"#5e8c31"))+fD(2.6,fChip(160,190,w3("sempre neutra","toujours neutre","still neutral"),"#8c1d40")))}
]},
/* ===================== s3 Scotch ===================== */
{id:"s1_scotch", sec:"c", ch:"s3", ic:"maps", t:I3_("Whisky scozzese","Whisky écossais","Scotch whisky"), s:[
 {h:I3_("Dal chicco: amido, non zucchero","Le grain : amidon, pas sucre","Grain: starch, not sugar"),
  c:I3_("Il whisky parte sempre dai cereali: puoi immaginarlo come una birra passata nell'alambicco. C'è però un ostacolo: un chicco d'orzo è secco, duro e pieno di amido, non di zucchero. I lieviti non sanno che farsene dell'amido, quindi va trasformato in zucchero prima che la fermentazione possa cominciare.",
   "Le whisky part toujours des céréales : on peut l'imaginer comme une bière passée à l'alambic. Il y a pourtant un obstacle : un grain d'orge est sec, dur et rempli d'amidon, pas de sucre. Les levures ne peuvent rien faire de l'amidon, il faut donc le transformer en sucre avant que la fermentation puisse commencer.",
   "Whisky always starts with grain; you can picture it as beer that has been through a still. There is one obstacle, though: a barley grain is dry, hard and packed with starch rather than sugar. Yeast can do nothing with starch, so it has to be turned into sugar before fermentation can begin."),
  v:()=>spF(`<g transform="rotate(-18 100 100)"><ellipse cx="100" cy="100" rx="62" ry="30" fill="#e0b85a" stroke="#9a7a32" stroke-width="2"/><ellipse cx="100" cy="100" rx="52" ry="22" fill="#f4ead2"/>${Array.from({length:18},(_,i)=>`<circle cx="${60+(i*17)%82}" cy="${88+(i*7)%26}" r="3" fill="#fff" stroke="#d8cdb8"/>`).join("")}</g>`+fCall(100,104,100,170,w3("amido","amidon","starch"),.6)
   +fD(1.2,fYeast(244,96)+fT(258,80,"?",18,"#f3cd8a"))+fD(1.6,fChip(244,128,w3("niente zucchero","pas de sucre","no sugar"),"#8c1d40"))+fD(2.4,fChip(244,40,w3("una birra distillata","une bière distillée","a distilled beer"))))},
 {h:I3_("La maltazione","Le maltage","Malting"),
  c:I3_("Il primo passo è la maltazione. Si lascia germogliare l'orzo, e crescendo il chicco produce enzimi, minuscoli strumenti chimici capaci di trasformare l'amido. Al momento giusto si soffia aria calda per fermare la crescita. Da lì si chiama orzo maltato: ha tutto ciò che serve, ma lo zucchero non è ancora stato liberato.",
   "La première étape est le maltage. On laisse l'orge commencer à germer, et en poussant le grain produit des enzymes, de minuscules outils chimiques capables de transformer l'amidon. Au bon moment, on souffle de l'air chaud pour stopper la croissance. On parle alors d'orge maltée : elle a tout ce qu'il faut, mais le sucre n'est pas encore libéré.",
   "The first step is malting. The barley is allowed to start growing, and as it grows the grain makes enzymes, tiny chemical tools that can change starch. At the right moment hot air is blown through to stop the growth. From then on it is called malted barley: it carries everything it needs, but the sugar is not released yet."),
  v:()=>spF(`<rect x="20" y="140" width="200" height="8" rx="3" fill="#6b4a32"/>`+[0,1,2,3,4,5,6].map(i=>{ const x=36+i*28; return `<ellipse cx="${x}" cy="134" rx="9" ry="5" fill="#e0b85a" stroke="#9a7a32"/><path d="M${x+6} 131q6 -10 2 -22" stroke="#9cc65a" stroke-width="2" fill="none" stroke-dasharray="26" stroke-dashoffset="26"><animate attributeName="stroke-dashoffset" from="26" to="0" begin="${.3+i*.15}s" dur="1.2s" fill="freeze"/></path>`; }).join("")
   +fD(.8,fChip(120,40,w3("germoglia","germe","sprouts"),"#5e8c31"))+fD(1.5,[50,110,170].map(x=>`<path d="M${x} 112l3 -6 3 6 -3 6z" fill="#f6e27a"><animate attributeName="opacity" values="0;1;0" dur="1.2s" repeatCount="indefinite"/></path>`).join("")+fChip(120,72,w3("produce enzimi","crée des enzymes","makes enzymes"),"#d4a23a","#2a1b20"))
   +fD(2.4,fHeater(272,176)+fArrow("M262 134Q240 120 226 132",null,1)+fChip(272,96,w3("aria calda: stop","air chaud : stop","hot air: stop"),"#8c1d40"))+fD(3.2,fChip(120,176,w3("orzo maltato","orge maltée","malted barley"))))},
 {h:I3_("Macinare e aggiungere acqua calda","Broyer et ajouter de l'eau chaude","Crush, then add warm water"),
  c:I3_("Poi l'orzo maltato si macina in una farina grossolana, a volte con altri cereali, e si mescola con acqua calda. In questo bagno gli enzimi trasformano l'amido in zucchero, dando un liquido dolce pronto per i lieviti. Ogni cereale lascia la sua firma: l'orzo porta note di cereale, il mais di mais dolce, la segale un tocco speziato e pepato.",
   "Ensuite l'orge maltée est broyée en farine grossière, parfois avec d'autres céréales, puis mélangée à de l'eau chaude. Dans ce bain, les enzymes transforment l'amidon en sucre, ce qui donne un liquide sucré prêt pour les levures. Chaque céréale laisse sa signature : l'orge des notes de céréale, le maïs de maïs doux, le seigle une touche épicée et poivrée.",
   "Next the malted barley is crushed into a rough flour, sometimes with other grains, and mixed with warm water. In this bath the enzymes convert the starch into sugar, giving a sweet liquid ready for yeast. Each grain leaves its signature: barley brings cereal notes, corn sweetcorn, and rye a spicy, peppery edge."),
  v:()=>spF([44,68].map((x,i)=>`<g transform="translate(${x} 60)"><circle r="12" fill="url(#fst)" stroke="#5c646b"/><path d="M-10 0H10M0 -10V10" stroke="#5c646b"><animateTransform attributeName="transform" type="rotate" from="0" to="${i?-360:360}" dur="2s" repeatCount="indefinite"/></path></g>`).join("")+fDrops(56,30,46,"#e0b85a",3)+fT(56,92,w3("macinatura","broyage","crushing"),9)
   +fD(.8,fArrow("M84 80Q100 92 108 104")+fTank(110,90,80,80,{col:"#cfe3ea",colTo:"#e9c86a",cb:1.4,cd:3})+fT(150,186,w3("acqua calda","eau chaude","warm water"),9))+fD(1.6,fChip(150,74,w3("amido → zucchero","amidon → sucre","starch → sugar"),"#8c1d40"))
   +fD(2.4,spBarley(222,72,.5)+fT(266,58,w3("cereale","céréale","cereal"),9,null,"middle")+spCorn(222,120,.45)+fT(266,106,w3("mais dolce","maïs doux","sweetcorn"),9)+spBarley(222,170,.5,"#a88a5a")+fT(266,156,w3("speziato","épicé","spicy"),9)))},
 {h:I3_("Le regole dello Scotch","Les règles du Scotch","The rules of Scotch"),
  c:I3_("Scotch è il nome del whisky scozzese, e le regole sono precise. Deve essere distillato in Scozia e poi invecchiato in Scozia per almeno tre anni. Contano entrambe le condizioni: un distillato scozzese mandato a invecchiare oltre confine perde il diritto al nome, anche se tutto il resto è identico.",
   "Scotch est le nom du whisky écossais, et ses règles sont précises. Il doit être distillé en Écosse puis vieilli en Écosse pendant au moins trois ans. Les deux conditions comptent : une eau-de-vie écossaise envoyée vieillir de l'autre côté de la frontière perd le droit au nom, même si tout le reste est identique.",
   "Scotch is whisky from Scotland, and the rules are precise. It must be distilled in Scotland and then aged in Scotland for at least three years. Both conditions matter: a Scottish spirit sent to mature across the border loses the right to the name, even if everything else about it is identical."),
  v:()=>spF(fBox(10,22,214,164,"",{dash:1,fill:"rgba(63,111,152,.18)"})+fT(117,40,w3("Scozia","Écosse","Scotland"),12,"#9fd3f0")+spPotStill(36,150,.5)+fD(.6,fChip(66,174,w3("distillato","distillé","distilled")))
   +fD(1.4,fBarrel(186,110,.7)+fClock(186,62,w3("3+ anni","3 ans et +","3+ years"))+fChip(186,148,w3("invecchiato","vieilli","aged")))+fD(2.6,fArrow("M216 130H252")+fBarrel(284,130,.5)+`<path d="M266 112L302 148M302 112L266 148" stroke="#e2622a" stroke-width="4" stroke-linecap="round"/>`+fChip(276,178,w3("niente Scotch","plus de Scotch","no longer Scotch"),"#8c1d40")))},
 {h:I3_("Due grandi famiglie","Deux grandes familles","Two big families"),
  c:I3_("Il passaggio in rovere è obbligatorio: le botti danno colore e aromi, e il whisky si concentra mentre un po' di acqua e alcol evaporano. Poi lo Scotch si divide in due grandi famiglie: Single Malt e Blended. La differenza non è il prestigio né l'età, ma tre domande: quali cereali, quale alambicco, quante distillerie.",
   "Le passage en fût de chêne est obligatoire : les fûts donnent couleur et arômes, et le whisky se concentre tandis qu'un peu d'eau et d'alcool s'évapore. Le Scotch se divise ensuite en deux grandes familles : Single Malt et Blended. La différence n'est ni le prestige ni l'âge, mais trois questions : quelles céréales, quel alambic, combien de distilleries.",
   "Time in oak is compulsory: the barrels give colour and aromas, and the whisky concentrates as some water and alcohol evaporate. Scotch then splits into two big families: Single Malt and Blended. The difference is not prestige or age but three questions: which grains, which kind of still, and how many distilleries."),
  v:()=>spF(fBox(98,14,104,30,"Single Malt",{fill:"rgba(140,29,64,.7)"})+fBox(208,14,104,30,"Blended",{fill:"rgba(94,140,49,.7)"})
   +[[w3("cereali","céréales","grains"),w3("solo orzo maltato","orge maltée seule","malted barley only"),w3("malto + cereali","malt + grain","malt + grain")],[w3("alambicco","appareil","still"),w3("discontinuo","alambic à repasse","pot still"),w3("discontinuo + colonna","alambic + colonne","pot + column")],[w3("distillerie","distilleries","distilleries"),w3("una sola","une seule","just one"),w3("diverse","plusieurs","several")]]
   .map(([a,b,c],i)=>fD(.6+i*.8,fBox(8,52+i*44,84,36,a,{fill:"rgba(212,162,58,.3)"})+fBox(98,52+i*44,104,36,b)+fBox(208,52+i*44,104,36,c))).join(""))},
 {h:I3_("Single Malt","Single Malt","Single Malt"),
  c:I3_("Uno Single Malt Scotch rispetta tre requisiti: solo orzo maltato, distillazione in alambicchi discontinui, una sola distilleria. «Single» indica un solo luogo di produzione, non una sola botte. L'alambicco discontinuo dà un distillato pieno di carattere: cereale, frutta, fiori e miele, poi torta di frutta e spezie dolci dopo il passaggio in rovere.",
   "Un Single Malt Scotch répond à trois exigences : uniquement de l'orge maltée, une distillation en alambics à repasse, une seule distillerie. « Single » désigne un seul lieu de production, pas un seul fût. L'alambic donne une eau-de-vie pleine de caractère : céréale, fruits, fleurs et miel, puis cake aux fruits et épices douces après le passage en fût.",
   "A Single Malt Scotch meets three requirements: it is made only from malted barley, distilled in pot stills, and comes from a single distillery. 'Single' means one place of production, not one barrel. Pot stills give a characterful spirit: cereal, fruit, flowers and honey, then fruit cake and sweet spice after time in oak."),
  v:()=>spF(spBarley(34,100,1)+fChip(40,118,w3("orzo maltato","orge maltée","malted barley"))+fD(.7,spPotStill(108,100,.45)+fChip(130,118,w3("discontinuo","alambic","pot still")))
   +fD(1.4,`<path d="M222 96V64L254 46L286 64V96Z" fill="#8a6a4a" stroke="#4e321c"/><path d="M246 46L254 26L262 46Z" fill="#5c4030"/><rect x="246" y="76" width="16" height="20" fill="#3a2a20"/>`+fChip(254,118,w3("una distilleria","une distillerie","one distillery"),"#8c1d40"))
   +[w3("cereale","céréale","cereal"),w3("frutta","fruits","fruit"),w3("fiori","fleurs","flowers"),w3("miele","miel","honey")].map((l,i)=>fD(2.2+i*.3,fChip(42+i*78,152,l,"#5e8c31"))).join("")+[w3("torta di frutta","cake aux fruits","fruit cake"),w3("spezie dolci","épices douces","sweet spice")].map((l,i)=>fD(3.6+i*.3,fChip(100+i*120,180,l,"rgba(212,162,58,.85)","#2a1b20"))).join(""))},
 {h:I3_("Il fumo della torba","La fumée de tourbe","Peat smoke"),
  c:I3_("Alcuni Single Malt hanno un aroma in più: il fumo. Viene dalla torba, un combustibile naturale che si brucia quando si scalda l'orzo maltato alla fine della maltazione. Il fumo avvolge i chicchi e li aromatizza, e quel sapore arriva fino al bicchiere. Sono una minoranza: solo pochi Single Malt sono torbati, alcuni in modo molto deciso.",
   "Certains Single Malts portent un arôme de plus : la fumée. Elle vient de la tourbe, un combustible naturel que l'on brûle pour chauffer l'orge maltée à la fin du maltage. La fumée enveloppe les grains et les parfume, et ce goût voyage jusqu'au verre. Ils sont minoritaires : seuls quelques Single Malts sont tourbés, certains très fortement.",
   "Some Single Malts carry one extra aroma: smoke. It comes from peat, a natural fuel burned when the malted barley is heated at the end of malting. The smoke wraps around the grains and flavours them, and that flavour travels all the way to the glass. Only a few Single Malts are peaty, some of them very strongly."),
  v:()=>spF(`<path d="M50 96H210" stroke="#7d868e" stroke-width="3" stroke-dasharray="4 3"/>`+Array.from({length:14},(_,i)=>`<ellipse cx="${58+i*11}" cy="90" rx="5" ry="3" fill="#d9b45a" stroke="#9a7a32"/>`).join("")+spPeat(130,170)+fD(.6,spVapour(100,124,3,40,"rgba(170,170,170,.7)")+spVapour(160,124,3,40,"rgba(170,170,170,.7)")+spVapour(130,80,4,40,"rgba(170,170,170,.6)"))
   +fCall(150,162,250,170,w3("torba","tourbe","peat"),1)+fD(1.8,fChip(250,96,w3("fumo nel malto","fumée dans le malt","smoke in the malt"),"#5c646b"))+fD(2.8,fChip(250,40,w3("solo pochi","seulement quelques-uns","only a few"),"#8c1d40")))},
 {h:I3_("Il whisky di cereali","Le whisky de grain","Grain whisky"),
  c:I3_("La Scozia produce anche il whisky di cereali. Usa orzo maltato insieme ad altri cereali e si distilla in alambicco a colonna invece che discontinuo. Il risultato ha un aroma leggero e una consistenza morbida. Raramente arriva da solo sugli scaffali, perché il suo vero compito è nell'assemblaggio.",
   "L'Écosse produit aussi du whisky de grain. Il utilise de l'orge maltée avec d'autres céréales et se distille en colonne plutôt qu'en alambic à repasse. Le résultat a un arôme léger et une texture souple. Il arrive rarement seul sur les étagères, car son vrai rôle est dans l'assemblage.",
   "Scotland also makes grain whisky. It uses malted barley together with other grains and is distilled in a column still rather than a pot still. The result has a light aroma and a smooth texture. It rarely reaches the shelf on its own, because its real job is in the blend."),
  v:()=>spF(spBarley(30,110,.8)+spCorn(62,110,.7)+spBarley(92,110,.8,"#e8cf8a")+fChip(62,130,w3("orzo + altri cereali","orge + autres céréales","barley + other grains"))+fD(.8,fArrow("M110 80H130")+spColumn(160,180,150,9,{steam:false}))
   +fD(1.8,spTulip(260,140,"rgba(240,225,170,.7)",1.2)+fChip(260,40,w3("leggero","léger","light"),"#5c646b")+fChip(260,186,w3("morbido","souple","smooth"),"#5e8c31")))},
 {h:I3_("Il Blended Scotch","Le Blended Scotch","Blended Scotch"),
  c:I3_("Il Blended Scotch, la categoria più diffusa, unisce whisky di malto e whisky di cereali di distillerie diverse, e di età diverse. Pensa a un'orchestra: i malti intensi sono i solisti, il whisky di cereali leggero tiene tutto insieme. L'assemblaggio dà costanza e complessità; di solito i blended sono più morbidi dei Single Malt, dal semplice al complesso.",
   "Le Blended Scotch, la catégorie la plus répandue, réunit des whiskies de malt et des whiskies de grain de distilleries différentes, et d'âges différents. Pensez à un orchestre : les malts intenses sont les solistes, le whisky de grain léger tient l'ensemble. L'assemblage apporte constance et complexité ; les blends sont en général plus souples que les Single Malts, du simple au complexe.",
   "Blended Scotch, the most widespread category, combines malt whiskies and grain whiskies from different distilleries, and of different ages. Think of an orchestra: the intense malts are the soloists, while the light grain whisky holds everything together. Blending gives consistency and complexity, and blends are usually smoother than Single Malts, from simple to complex."),
  v:()=>spF(["#c98a3a","#b06a2a","#d9a441"].map((c,i)=>fD(.2+i*.3,spBottle(30+i*34,70,c,{s:.6}))).join("")+fChip(64,112,w3("malti: i solisti","malts : solistes","malts: soloists"),"#8c1d40")+fD(1,spSteel(20,134,90,46,"rgba(240,225,170,.75)")+fChip(64,194,w3("cereali: la base","grain : la base","grain: the base"),"#5e8c31"))
   +fD(1.6,spPour(110,70,160,100,"#c98a3a")+spPour(110,150,160,130,"#efe0a8"))+fD(1.8,fTank(160,80,64,80,{col:"#d9a441"}))+fD(2.6,fArrow("M228 120H244")+spBottle(272,120,"#d9a441",{lab:"BLEND"}))+fD(3.2,fChip(272,40,w3("più morbido","plus souple","smoother"))))}
]},
/* ===================== s4 American and other whiskies ===================== */
{id:"s1_whiskies", sec:"c", ch:"s4", ic:"maps", t:I3_("Whiskey americano e altri whisky","Whiskey américain et autres whiskies","American and other whiskies"), s:[
 {h:I3_("Bourbon: tre scelte","Bourbon : trois choix","Bourbon: three choices"),
  c:I3_("Il Bourbon è il whiskey americano più conosciuto. Molti lo associano al Kentucky, ed è lo stato che ne produce di più, ma la legge permette di farlo ovunque negli Stati Uniti. Il suo stile dipende da tre scelte chiare: la ricetta dei cereali, il modo di distillare e il tipo di botte.",
   "Le Bourbon est le whiskey américain le plus connu. Beaucoup l'associent au Kentucky, et c'est bien l'État qui en produit le plus, mais la loi permet de le faire partout aux États-Unis. Son style tient à trois choix clairs : la recette des céréales, la façon de distiller et le type de fût.",
   "Bourbon is the best-known American whiskey. Many people link it to Kentucky, and that state does make the most, but the law allows Bourbon to be made anywhere in the United States. Its style comes down to three clear choices: the grain recipe, the way it is distilled and the type of barrel."),
  v:()=>spF(`<path d="M40 40L120 34L200 38L268 30L284 52L270 84L250 100L240 128L210 120L170 130L150 148L120 120L70 112L48 90Z" fill="#4f6e45" stroke="#e8dccf" stroke-width="1.4"/>`+fT(130,80,"USA",12,"rgba(255,244,220,.6)")
   +fD(.6,`<ellipse cx="214" cy="84" rx="16" ry="8" fill="#d4a23a" opacity=".7"/>`+spPin(214,82))+fCall(214,78,240,20,"Kentucky",1)+fD(1.6,fChip(110,140,w3("ovunque negli USA","partout aux États-Unis","anywhere in the USA"),"#8c1d40"))
   +[w3("cereali","céréales","grain"),w3("alambicco","appareil","still"),w3("botte","fût","barrel")].map((l,i)=>fD(2.2+i*.4,fBox(30+i*90,160,80,26,l,{fill:"rgba(140,29,64,.6)"}))).join(""))},
 {h:I3_("Almeno 51% di mais, colonna a grado basso","Au moins 51 % de maïs, colonne à bas degré","51%+ corn, column at low strength"),
  c:I3_("Prima scelta: almeno il 51% dei cereali deve essere mais, di solito completato da orzo e segale; il mais porta note di mais dolce. Seconda: il Bourbon si distilla di norma in colonna, ma solo a grado basso, così conserva molto carattere. Una colonna non deve per forza dare un distillato leggero: dipende da quanto sale il grado.",
   "Premier choix : au moins 51 % des céréales doivent être du maïs, en général complété par de l'orge et du seigle ; le maïs apporte des notes de maïs doux. Deuxième : le Bourbon se distille d'ordinaire en colonne, mais seulement à bas degré, et garde ainsi beaucoup de caractère. Une colonne ne donne pas forcément un alcool léger : tout dépend du degré atteint.",
   "First choice: at least 51% of the grain must be corn, usually topped up with barley and rye; corn brings sweetcorn notes. Second: Bourbon is normally distilled in a column still, but only to a low strength, so it keeps plenty of character. A column does not have to make a light spirit: it all depends on how high the strength goes."),
  v:()=>spF(`<rect x="30" y="30" width="44" height="140" rx="4" fill="rgba(255,255,255,.1)" stroke="#e8dccf"/>`+fD(.2,`<rect x="32" y="98" width="40" height="70" fill="#f2c443"/>`+fT(52,138,"51%+",10,"#2a1b20"))+fD(.9,`<rect x="32" y="60" width="40" height="38" fill="#e0b85a"/><rect x="32" y="32" width="40" height="28" fill="#a88a5a"/>`+fT(104,50,w3("segale","seigle","rye"),9,null,"start")+fT(104,82,w3("orzo","orge","barley"),9,null,"start"))+spCorn(108,170,.6)+fT(126,140,w3("mais","maïs","corn"),9,"#f3cd8a","start")
   +fD(1.8,spColumn(210,176,96,5)+fChip(210,60,w3("colonna","colonne","column still")))+fD(2.6,fChip(260,120,w3("grado basso","bas degré","low strength"),"#8c1d40")+fChip(260,146,w3("= carattere","= caractère","= character"),"#5e8c31")))},
 {h:I3_("Botti nuove carbonizzate","Fûts neufs brûlés","New charred barrels"),
  c:I3_("Terza scelta: le botti devono essere di rovere nuovo, carbonizzate all'interno. Una botte mai usata dà il massimo di colore e aroma, e la carbonizzazione aggiunge ancora intensità. Il risultato è un whiskey pronunciato e complesso, con note di mais dolce, cereale, frutta, vaniglia e cocco.",
   "Troisième choix : les fûts doivent être en chêne neuf, brûlés à l'intérieur. Un fût jamais utilisé donne le maximum de couleur et d'arômes, et le brûlage ajoute encore de l'intensité. Le résultat est un whiskey prononcé et complexe, aux notes de maïs doux, de céréale, de fruits, de vanille et de noix de coco.",
   "Third choice: the barrels must be new oak, charred on the inside. A barrel that has never been used gives the most colour and aroma, and the charring adds even more intensity. The result is a pronounced, complex whiskey with notes of sweetcorn, cereal, fruit, vanilla and coconut."),
  v:()=>spF(`<g transform="translate(90 104) scale(1.7)"><path d="M-30 -20Q0 -27 30 -20Q37 0 30 20Q0 27 -30 20Q-37 0 -30 -20Z" fill="url(#fwood)" stroke="#4e321c" stroke-width="1.5"/><path d="M-25 -14Q0 -19 25 -14Q30 0 25 14Q0 19 -25 14Q-30 0 -25 -14Z" fill="#1c1210"/><path d="M-31 -11Q0 -17 31 -11M-31 11Q0 17 31 11" stroke="#3a3a3a" stroke-width="2.4" fill="none"/></g>`+fFire(90,128)+fD(.6,fChip(90,40,w3("rovere nuovo","chêne neuf","new oak"),"#5e8c31")+fChip(90,170,w3("carbonizzato","brûlé à l'intérieur","charred inside"),"#8c1d40"))
   +[w3("mais dolce","maïs doux","sweetcorn"),w3("cereale","céréale","cereal"),w3("frutta","fruits","fruit"),w3("vaniglia","vanille","vanilla"),w3("cocco","coco","coconut")].map((l,i)=>fD(1.4+i*.4,fChip(250,36+i*28,l,"rgba(212,162,58,.85)","#2a1b20"))).join(""))},
 {h:I3_("Sembra dolce, ma è secco","Il semble doux, mais il est sec","Seems sweet, but it is dry"),
  c:I3_("Una trappola comune: si dice spesso che il Bourbon è dolce. In realtà non ha zucchero aggiunto ed è secco. L'impressione di dolcezza viene dagli aromi di vaniglia, frutta e cocco, che il naso associa ai dessert. Nel linguaggio della degustazione, dolce indica solo il sapore dello zucchero, percepito in bocca.",
   "Un piège courant : on dit souvent que le Bourbon est sucré. En réalité, il n'a pas de sucre ajouté et il est sec. L'impression de douceur vient des arômes de vanille, de fruits et de coco, que le nez associe aux desserts. En dégustation, sucré désigne uniquement le goût du sucre, perçu en bouche.",
   "A common trap: people often call Bourbon sweet. In fact it has no added sugar and is dry. The impression of sweetness comes from the vanilla, fruit and coconut aromas, which the nose links with desserts. In tasting language, sweet refers only to the taste of sugar, felt on the palate."),
  v:()=>spF(spTulip(100,150,"#c98a3a",1.5)+spVapour(100,80,4,26,"#f3cd8a")+fD(.4,fChip(100,36,w3("vaniglia, cocco","vanille, coco","vanilla, coconut"),"rgba(212,162,58,.85)","#2a1b20"))
   +fD(1.4,spSugar(232,92,2)+spNo(242,86,18)+fChip(242,126,w3("niente zucchero","aucun sucre ajouté","no added sugar"),"#8c1d40"))+fD(2.4,fChip(242,160,w3("in bocca: secco","en bouche : sec","on the palate: dry"),"#5c646b")))},
 {h:I3_("Tennessee: il passaggio nel carbone","Tennessee : le passage au charbon","Tennessee: through the charcoal"),
  c:I3_("Il Tennessee whiskey si fa come il Bourbon, con la stessa maggioranza di mais, la stessa distillazione e le stesse botti nuove carbonizzate, ma solo nello stato del Tennessee. In più ha un passaggio: il distillato nuovo si filtra su carbone d'acero prima della botte. Toglie impurità e lo rende più morbido, senza aggiungere sapore: niente acero, niente fumo.",
   "Le Tennessee whiskey se fait comme le Bourbon, avec la même majorité de maïs, la même distillation et les mêmes fûts neufs brûlés, mais uniquement dans l'État du Tennessee. Il ajoute une étape : l'eau-de-vie neuve est filtrée sur charbon d'érable avant le fût. Cela retire des impuretés et l'assouplit, sans ajouter de goût : ni érable, ni fumée.",
   "Tennessee whiskey is made like Bourbon, with the same corn majority, distillation and new charred barrels, but only in the state of Tennessee. It adds one step: the new spirit is filtered through maple charcoal before going into the barrel. This removes some impurities and makes it smoother, without adding any flavour: no maple, no smoke."),
  v:()=>spF(spColumn(40,176,110,6,{steam:false,out:false})+fArrow("M60 80H96")+fD(.6,spCharcoal(100,80,90)+fChip(145,150,w3("carbone d'acero","charbon d'érable","maple charcoal"))+fLeaf(145,64,1,0,"#c7642e"))
   +fD(1.6,fArrow("M196 104H226")+fBarrel(264,104,.8))+fD(2.4,fChip(264,40,w3("solo in Tennessee","Tennessee seulement","only in Tennessee"),"#8c1d40")+fChip(200,186,w3("più morbido","plus souple","smoother"),"#5e8c31")))},
 {h:I3_("Rye e come distinguerli","Le Rye, et comment les distinguer","Rye, and how to tell them apart"),
  c:I3_("Il Rye americano è il gemello speziato del Bourbon: stessa distillazione in colonna, stesse botti nuove carbonizzate, ma almeno il 51% dei cereali deve essere segale. Ne nascono aromi speziati e pepati, con la vaniglia dietro. Per riconoscerli: soprattutto mais, Bourbon; mais più carbone d'acero in Tennessee, Tennessee whiskey; soprattutto segale, Rye.",
   "Le Rye américain est le jumeau épicé du Bourbon : même distillation en colonne, mêmes fûts neufs brûlés, mais au moins 51 % des céréales doivent être du seigle. Il en naît des arômes épicés et poivrés, avec la vanille derrière. Pour les distinguer : surtout du maïs, Bourbon ; maïs plus charbon d'érable au Tennessee, Tennessee whiskey ; surtout du seigle, Rye.",
   "American Rye whiskey is Bourbon's spicy twin: same column distillation, same new charred barrels, but at least 51% of the grain must be rye. That brings spicy, peppery aromas, with the vanilla sitting behind. To sort the three: mostly corn is Bourbon; corn plus maple charcoal in Tennessee is Tennessee whiskey; mostly rye is Rye."),
  v:()=>spF([[spCorn(30,60,.5),w3("51%+ mais","51 % + maïs","51%+ corn"),"Bourbon"],[spCorn(30,116,.5)+`<rect x="44" y="96" width="14" height="14" rx="2" fill="#1e1a1a"/>`,w3("mais + carbone","maïs + charbon","corn + charcoal"),"Tennessee"],[spBarley(30,172,.55,"#a88a5a"),w3("51%+ segale","51 % + seigle","51%+ rye"),"Rye"]]
   .map(([ic,a,b],i)=>fD(.3+i*.9,ic+fBox(66,24+i*56,120,32,a)+fArrow(`M190 ${40+i*56}H206`)+fBox(210,24+i*56,100,32,b,{fill:i===2?"rgba(140,29,64,.7)":"rgba(94,140,49,.6)"}))).join("")+fD(2.8,fChip(260,192,w3("speziato, pepato","épicé, poivré","spicy, peppery"),"#8c1d40")))},
 {h:I3_("Irlanda","Irlande","Ireland"),
  c:I3_("In Irlanda la maggior parte dei whiskey unisce distillati di alambicco discontinuo e di colonna, e lo stile tipico è leggero e morbido, facile da bere. Alcuni whiskey irlandesi si fanno solo in alambicco discontinuo, e alcuni usano un ingrediente insolito: l'orzo non maltato, che dà una consistenza oleosa e un carattere di frutta secca.",
   "En Irlande, la plupart des whiskeys réunissent des eaux-de-vie d'alambic et de colonne, et le style typique est léger et souple, facile à boire. Certains whiskeys irlandais se font uniquement en alambic, et certains utilisent un ingrédient inhabituel : l'orge non maltée, qui donne une texture huileuse et un caractère de fruits secs.",
   "In Ireland, most whiskeys combine pot-still and column-still spirits, and the typical style is light and smooth, easy to drink. Some Irish whiskeys are made only in pot stills, and some use an unusual ingredient: unmalted barley, which gives an oily texture and a nutty character."),
  v:()=>spF(spPotStill(24,100,.42)+fT(60,124,w3("alambicco","alambic","pot still"),9)+spColumn(150,110,84,5,{steam:false,out:false})+fT(150,124,w3("colonna","colonne","column"),9)+fD(.8,fArrow("M100 70Q116 50 132 66",null,1)+fChip(240,72,w3("leggero e morbido","léger et souple","light and smooth"),"#5e8c31"))
   +fD(1.8,spBarley(60,190,.7)+`<text x="86" y="166" font-size="9" fill="#f3cd8a" font-weight="700" font-family="DM Sans,system-ui,sans-serif">${esc(w3("orzo non maltato","orge non maltée","unmalted barley"))}</text>`+fArrow("M180 160H200")+fChip(256,148,w3("oleoso","huileux","oily texture"),"#d4a23a","#2a1b20")+fChip(256,174,w3("frutta secca","fruits secs","nutty"),"#8a5a33")))},
 {h:I3_("Canada","Canada","Canada"),
  c:I3_("Il Canada usa molti cereali diversi e di solito assembla distillati ad alta gradazione, più leggeri, con distillati a bassa gradazione, più saporiti. Il risultato sono whisky equilibrati e versatili. Nei migliori whisky canadesi, però, c'è un filo comune: la segale. È il sapore distintivo, speziato e pepato.",
   "Le Canada utilise de nombreuses céréales et assemble en général des eaux-de-vie à haut degré, plus légères, avec des eaux-de-vie à bas degré, plus savoureuses. Le résultat : des whiskies équilibrés et polyvalents. Dans les meilleurs whiskies canadiens, un fil conducteur : le seigle. C'est la saveur signature, épicée et poivrée.",
   "Canada uses many different grains and usually blends high-strength spirits, which are lighter, with low-strength spirits, which have more flavour. The result is balanced, versatile whisky. In the best Canadian whiskies, though, one thread runs through them all: rye, the signature flavour, spicy and peppery."),
  v:()=>spF(spBarley(26,80,.6)+spCorn(50,80,.5)+spBarley(74,80,.6,"#e8cf8a")+spBarley(98,80,.6,"#a88a5a")+fChip(64,96,w3("molti cereali","nombreuses céréales","many grains"))
   +fD(.9,spAbv(150,176,60,90,w3("alto grado","haut degré","high strength"),"#9fd3f0",.9,1)+spAbv(214,176,60,60,w3("basso grado","bas degré","low strength"),"#d4a23a",1.2,1)+fD(1.6,fT(150,106,w3("leggero","léger","lighter"),9,"#9fd3f0")+fT(214,106,w3("saporito","savoureux","flavourful"),9,"#f3cd8a"))+fArrow("M232 140H250"))+fD(2,spBottle(280,140,"#d9a441",{s:.8}))
   +fD(2.8,spBarley(240,60,.6,"#a88a5a")+fChip(250,74,w3("firma: segale","signature : seigle","signature: rye"),"#8c1d40")))},
 {h:I3_("Giappone","Japon","Japan"),
  c:I3_("Il Giappone ha costruito la sua industria del whisky prendendo la Scozia come modello: per questo si trovano sia whisky di malto sia blended, proprio come per lo Scotch. Lo stile tradizionale è elegante e raffinato, preciso nei dettagli. Negli ultimi anni però molti produttori giapponesi esplorano stili e sapori nuovi, e la categoria continua a evolvere.",
   "Le Japon a bâti son industrie du whisky en prenant l'Écosse pour modèle : on y trouve donc des whiskies de malt et des blends, comme pour le Scotch. Le style traditionnel est élégant et raffiné, précis dans ses détails. Ces dernières années, de nombreux producteurs japonais explorent pourtant de nouveaux styles et saveurs, et la catégorie continue d'évoluer.",
   "Japan built its whisky industry using Scotland as the model, so you find both malt and blended whiskies there, just as with Scotch. The traditional style is elegant and refined, precise in every detail. In recent years, though, many Japanese producers have explored new styles and flavours, and the category keeps evolving."),
  v:()=>spF(fBox(20,30,100,30,w3("modello scozzese","modèle écossais","Scottish model"))+fD(.8,fArrow("M124 45H160")+fBox(166,30,130,30,w3("Giappone","Japon","Japan"),{fill:"rgba(140,29,64,.7)"}))
   +fD(1.4,spBottle(196,130,"#d9a441",{s:.8})+fT(196,176,"malt",9)+spBottle(262,130,"#c98a3a",{s:.8})+fT(262,176,"blended",9))
   +fD(2.2,fChip(70,96,w3("elegante","élégant","elegant"),"#5e8c31")+fChip(70,124,w3("raffinato","raffiné","refined"),"#5e8c31"))+fD(3,fChip(70,160,w3("stili nuovi","nouveaux styles","new styles"),"#8c1d40")))}
]},
/* ===================== s5 Rum ===================== */
{id:"s1_rum", sec:"c", ch:"s5", ic:"maps", t:I3_("Rum dei Caraibi","Rhum des Caraïbes","Caribbean rum"), s:[
 {h:I3_("Canna da zucchero e Caraibi","Canne à sucre et Caraïbes","Sugar cane and the Caribbean"),
  c:I3_("Il rum si fa con la canna da zucchero, una pianta che ama il caldo: per questo la produzione è concentrata nei paesi caldi, e il suo cuore storico sono i Caraibi. La regione è un mosaico di piccoli paesi, ognuno con tradizioni e regole proprie. Classificare il rum per colore o lingua funziona male: è molto più utile seguire le quattro fasi di produzione.",
   "Le rhum se fait avec la canne à sucre, une plante qui aime la chaleur : la production se concentre donc dans les pays chauds, et son berceau historique est la Caraïbe. La région est une mosaïque de petits pays, chacun avec ses traditions et ses règles. Classer le rhum par couleur ou par langue marche mal : il est bien plus utile de suivre les quatre étapes de production.",
   "Rum is made from sugar cane, a plant that loves heat, so production is centred on hot countries, and its historic heartland is the Caribbean. The region is a patchwork of small countries, each with its own traditions and rules. Sorting rum by colour or language works poorly: it is far more useful to follow the four stages of production."),
  v:()=>spF(fSun(270,36,14)+spCane(46,168,.9)+`<rect x="100" y="110" width="210" height="60" rx="10" fill="#3f8fb8" opacity=".8"/>`+[[130,140,14],[170,128,9],[205,146,11],[236,132,6],[262,148,8],[288,136,5]].map(([x,y,r],i)=>fD(.4+i*.2,`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.6}" fill="#7fae46"/>`)).join("")
   +fD(1.2,fChip(200,96,w3("Caraibi","Caraïbes","Caribbean"),"#3f7fa8"))+fD(2.2,fChip(200,186,w3("fasi, non colore","étapes, pas couleur","stages, not colour"),"#8c1d40")),"summer")},
 {h:I3_("Succo di canna: erbaceo","Jus de canne : herbacé","Cane juice: grassy"),
  c:I3_("La prima scelta è la materia prima. La canna appena tagliata si può schiacciare e fermentare subito il suo succo dolce. I rum di succo di canna hanno spesso un sapore erbaceo molto pronunciato, come l'erba appena tagliata. Gli esempi migliori sono i rhum agricole, che nei Caraibi devono venire dalla Martinica o dalla Guadalupa.",
   "Le premier choix est la matière première. La canne fraîchement coupée peut être broyée et son jus sucré fermenté tout de suite. Les rhums de jus de canne ont souvent un goût herbacé très prononcé, comme l'herbe fraîchement coupée. Les meilleurs exemples sont les rhums agricoles, qui dans la Caraïbe doivent venir de Martinique ou de Guadeloupe.",
   "The first choice is the raw material. Freshly cut cane can be crushed and its sweet juice fermented straight away. Cane juice rums often have a very pronounced grassy, herbaceous flavour, like freshly mown grass. The best examples are rhum agricole, which in the Caribbean must come from Martinique or Guadeloupe."),
  v:()=>spF(spCane(36,170,.8)+fD(.4,spRollers(108,70,1.1))+fD(.6,fDrops(108,84,120,"#c8d77a",4)+`<path d="M86 124H130V160Q130 164 126 164H90Q86 164 86 160Z" fill="url(#spgl)" stroke="#e8dccf"/><rect x="88" y="134" width="40" height="28" fill="#c8d77a"/>`+fT(108,182,w3("succo di canna","jus de canne","cane juice"),9,"#3a2a2f"))
   +fD(1.6,fChip(220,40,w3("erbaceo","herbacé","grassy"),"#5e8c31")+fLeaf(170,46,.8,-20,"#7fae46"))+fD(2.4,fChip(230,96,"rhum agricole","#8c1d40")+fChip(230,124,"Martinique · Guadeloupe")),"summer")},
 {h:I3_("Melassa: caramello","Mélasse : caramel","Molasses: caramel"),
  c:I3_("La maggior parte dei distillatori caraibici usa però la melassa: un sottoprodotto nero e appiccicoso dell'industria che trasforma il succo di canna in zucchero. Va mescolata con acqua prima che la fermentazione possa partire. I rum di melassa hanno sapori di caramello e zucchero di canna scuro, un profilo più rotondo della freschezza erbacea del succo.",
   "La plupart des distillateurs de la Caraïbe utilisent pourtant la mélasse : un sous-produit noir et collant de l'industrie qui transforme le jus de canne en sucre. Il faut la mélanger à de l'eau avant que la fermentation puisse démarrer. Les rhums de mélasse ont des saveurs de caramel et de sucre roux, un profil plus rond que la fraîcheur herbacée du jus.",
   "Most Caribbean distillers, however, use molasses: a black, sticky by-product of the industry that turns cane juice into sugar. It must be mixed with water before fermentation can start. Molasses rums have flavours of caramel and brown sugar, a rounder profile than the grassy freshness of cane juice."),
  v:()=>spF(fBox(14,30,96,28,w3("succo di canna","jus de canne","cane juice"))+fD(.5,fArrow("M62 62V84")+fBox(14,88,96,28,w3("zuccherificio","sucrerie","sugar factory"))+fArrow("M112 102H130")+fCrystals(136,104)+fT(150,124,w3("zucchero","sucre","sugar"),9))
   +fD(1.2,fArrow("M62 120V140")+spMolasses(62,182)+fT(62,196,w3("melassa","mélasse","molasses"),9,"#f3cd8a"))+fD(2,spJug(150,170,1,196,150)+fTank(200,110,60,70,{col:"#6b3a1a",bub:5})+fT(170,196,w3("+ acqua","+ eau","+ water"),9))
   +fD(2.8,fChip(250,40,w3("caramello","caramel","caramel"),"rgba(212,162,58,.85)","#2a1b20")+fChip(250,68,w3("zucchero scuro","sucre roux","brown sugar"),"#8a5a33")))},
 {h:I3_("Fermentazione e frutta tropicale","Fermentation et fruits tropicaux","Fermentation and tropical fruit"),
  c:I3_("La fermentazione trasforma lo zucchero in alcol, ma crea anche aromi, e nel rum può diventare protagonista. Gestita in un certo modo, produce aromi di frutta tropicale come banana o ananas, a volte molto pronunciati. I distillatori della Giamaica sono famosi per questo stile intensamente fruttato, che nasce dalla fermentazione, non da aromi aggiunti.",
   "La fermentation transforme le sucre en alcool, mais elle crée aussi des arômes, et dans le rhum elle peut passer au premier plan. Conduite d'une certaine façon, elle produit des arômes de fruits tropicaux comme la banane ou l'ananas, parfois très prononcés. Les distillateurs de la Jamaïque sont célèbres pour ce style intensément fruité, né de la fermentation, pas d'arômes ajoutés.",
   "Fermentation turns sugar into alcohol, but it also creates aromas, and in rum it can take centre stage. Managed in a certain way, it produces tropical fruit aromas such as banana or pineapple, sometimes very pronounced. Jamaican distillers are famous for this intensely fruity style, which comes from fermentation, not from added flavourings."),
  v:()=>spF(fTank(50,60,90,110,{col:"#c88a4a",bub:10})+fD(.3,fYeast(80,130)+fYeast(110,112))+fD(1,spBanana(200,70,1.2))+fD(1.5,spPineapple(262,100,1.1))+fD(2,spBanana(200,140,1)+fChip(220,40,w3("frutta tropicale","fruits tropicaux","tropical fruit"),"#5e8c31"))
   +fD(2.8,fChip(230,180,w3("Giamaica","Jamaïque","Jamaica"),"#8c1d40")))},
 {h:I3_("Alambicco o colonna: l'intensità","Alambic ou colonne : l'intensité","Pot or column: intensity"),
  c:I3_("Nei Caraibi quasi ogni distillatore sceglie il suo alambicco, e questa scelta decide l'intensità. L'alambicco discontinuo dà un rum pronunciato e pieno di carattere. Anche una colonna corta, con poche sezioni, dà un distillato saporito: è così che si fa il rhum agricole. Le colonne alte, ad alta gradazione, danno rum leggeri, come a Cuba e Porto Rico. Molte distillerie hanno entrambi.",
   "Dans la Caraïbe, presque chaque distillateur choisit son appareil, et ce choix décide de l'intensité. L'alambic à repasse donne un rhum prononcé, plein de caractère. Une colonne courte, avec peu de sections, donne aussi une eau-de-vie savoureuse : c'est ainsi qu'on fait le rhum agricole. Les hautes colonnes, à haut degré, donnent des rhums légers, comme à Cuba et à Porto Rico. Beaucoup de distilleries ont les deux.",
   "Caribbean distillers can choose their still, and that choice sets the intensity. A pot still gives a pronounced rum full of character. A short column with few sections also gives a flavourful spirit: this is how rhum agricole is made. Tall columns distilling to a high strength give light rums, as in Cuba and Puerto Rico. Many distilleries own both types."),
  v:()=>spF(spPotStill(28,150,.44)+fChip(56,176,w3("pronunciato","prononcé","pronounced"),"#8c1d40")+fD(1,spColumn(160,150,66,3,{steam:false})+fChip(160,176,"rhum agricole","#5e8c31"))
   +fD(2,spColumn(266,150,130,10,{steam:false,liq:"#dfe9f0"})+fChip(262,176,w3("leggero","léger","light"),"#5c646b")+fChip(200,30,"Cuba · Puerto Rico")))},
 {h:I3_("Rovere, acciaio e filtri al carbone","Chêne, inox et filtres au charbon","Oak, steel and charcoal filters"),
  c:I3_("Un rum può essere invecchiato o no. Il rovere aggiunge vaniglia, spezie dolci e colore, e in alcuni paesi caraibici il passaggio in botte è obbligatorio. Il rum non invecchiato riposa in acciaio e resta incolore. E se la botte è obbligatoria ma si vuole un rum bianco? La filtrazione al carbone toglie il colore del legno: un rum limpido che ha visto il rovere.",
   "Un rhum peut être vieilli ou non. Le chêne ajoute vanille, épices douces et couleur, et dans certains pays de la Caraïbe le passage en fût est obligatoire. Le rhum non vieilli repose en cuve inox et reste incolore. Et si le fût est obligatoire mais qu'on veut un rhum blanc ? La filtration au charbon retire la couleur du bois : un rhum limpide qui a connu le chêne.",
   "A rum can be aged or not. Oak adds vanilla, sweet spice and colour, and some Caribbean countries require time in the barrel. Unaged rum rests in steel tanks and stays colourless. And if oak is required but the producer wants a white rum? Charcoal filtering removes the colour taken from the wood: a clear rum that has seen oak."),
  v:()=>spF(spSteel(14,50,50,60)+fT(39,128,w3("non invecchiato","non vieilli","unaged"),9)+fD(.8,fBarrel(120,80,.8,{cut:1,col:"#c98a3a"})+fChip(120,124,w3("vaniglia, spezie","vanille, épices","vanilla, spice"),"rgba(212,162,58,.85)","#2a1b20"))
   +fD(1.8,fArrow("M150 80H176")+spCharcoal(180,56,64)+fChip(212,152,w3("filtro al carbone","filtre au charbon","charcoal filter")))+fD(2.6,fArrow("M248 80H262")+spBottle(288,90,"rgba(230,240,255,.55)",{s:.75})+fChip(260,170,w3("rum bianco invecchiato","rhum blanc vieilli","aged white rum"),"#8c1d40")))},
 {h:I3_("Assemblaggio, zucchero e caramello","Assemblage, sucre et caramel","Blending, sugar and caramel"),
  c:I3_("Poi c'è l'assemblaggio: distillati di alambicco e di colonna, di età diverse e perfino di distillerie diverse, costruiscono ogni stile. Alcuni rum vengono addolciti, pratica comune in America Centrale e del Sud, mentre alcuni paesi la vietano. Molti ricevono caramello per il colore, a volte quasi tutto il colore. Infine l'acqua pura porta il rum al grado di imbottigliamento.",
   "Vient ensuite l'assemblage : eaux-de-vie d'alambic et de colonne, d'âges différents et même de distilleries différentes, construisent chaque style. Certains rhums sont sucrés, pratique courante en Amérique centrale et du Sud, tandis que certains pays l'interdisent. Beaucoup reçoivent du caramel pour la couleur, parfois presque toute leur couleur. Enfin, l'eau pure amène le rhum à son degré de mise en bouteille.",
   "Then comes blending: pot and column spirits, of different ages and even from different distilleries, build each style. Some rums are sweetened, a common practice in Central and South America, while some countries forbid it. Many get caramel for colour, sometimes almost all of it. Finally, pure water brings the rum down to bottling strength."),
  v:()=>spF(["#efe0a8","#c98a3a","#8a4a1a"].map((c,i)=>fD(i*.3,spBottle(30+i*36,70,c,{s:.6})+spPour(30+i*36,40,140,90,c,2))).join("")+fD(.8,fTank(120,80,64,80,{col:"#b9742e"}))
   +fD(1.6,spSugar(214,58,2)+fChip(250,86,w3("Am. Centrale e del Sud","Am. centrale et du Sud","Central/South America"),"#5e8c31")+fChip(250,112,w3("vietato in certi paesi","interdit par endroits","banned in some places"),"#8c1d40"))
   +fD(2.6,spMolasses(222,170)+fT(222,188,w3("caramello","caramel","caramel"),9))+fD(3.2,spJug(280,170,0)+fT(280,188,w3("acqua","eau","water"),9)))}
]},
/* ===================== s6 Tequila ===================== */
{id:"s1_tequila", sec:"c", ch:"s6", ic:"maps", t:I3_("Tequila","Tequila","Tequila"), s:[
 {h:I3_("Agave blu, solo in Messico","Agave bleu, seulement au Mexique","Blue agave, only in Mexico"),
  c:I3_("La Tequila è un distillato messicano dall'identità chiara: si può fare solo in alcuni stati del Messico indicati dalla legge, e solo con l'agave blu, una pianta originaria del Messico. Non è un cactus: lunghe foglie spinose si aprono intorno a un grande cuore duro. Alla raccolta le foglie si tagliano via, e resta solo il cuore che serve al distillatore.",
   "La Tequila est un spiritueux mexicain à l'identité claire : on ne peut la faire que dans certains États du Mexique désignés par la loi, et uniquement avec l'agave bleu, une plante originaire du Mexique. Ce n'est pas un cactus : de longues feuilles piquantes s'ouvrent autour d'un gros cœur dur. À la récolte, on coupe les feuilles pour ne garder que le cœur.",
   "Tequila is a Mexican spirit with a clear identity: it can only be made in certain Mexican states named by law, and only from blue agave, a plant native to Mexico. It is not a cactus: long, spiky leaves fan out around a large, hard core. At harvest the leaves are cut away, leaving only the core the distiller wants."),
  v:()=>spF(fGround()+spAgave(80,170,1.7)+fD(.5,fChip(80,30,w3("agave blu","agave bleu","blue agave"),"#3f7fa8"))+fD(1.2,fChip(80,56,w3("non è un cactus","pas un cactus","not a cactus"),"#8c1d40"))
   +fD(2,fArrow("M150 130H194")+spPina(240,166,1.6)+fChip(240,96,w3("il cuore","le cœur","the core"),"#d4a23a","#2a1b20"))+fD(2.8,fChip(240,30,w3("stati del Messico","États du Mexique","Mexican states"))),"summer")},
 {h:I3_("Cottura e aromi dell'agave","Cuisson et arômes de l'agave","Cooking and agave aromas"),
  c:I3_("Come i cereali, un cuore d'agave appena raccolto non ha zucchero pronto da fermentare. I cuori cuociono lentamente in forno finché diventano morbidi e si formano zuccheri, un po' come una patata dura che dopo la cottura si schiaccia con la forchetta. Poi si schiacciano e danno un succo dolce con gli aromi inconfondibili dell'agave blu: erbacei, vegetali, oliva, terra e pepe.",
   "Comme les céréales, un cœur d'agave fraîchement récolté n'a pas de sucre prêt à fermenter. Les cœurs cuisent lentement au four jusqu'à devenir tendres et former des sucres, un peu comme une pomme de terre dure qu'on écrase à la fourchette une fois cuite. On les broie ensuite, et ils donnent un jus sucré aux arômes inimitables de l'agave bleu : herbacés, végétaux, olive, terre et poivre.",
   "Like grain, a fresh agave core has no sugar ready to ferment. The cores are cooked slowly in ovens until they turn soft and sugars form, a bit like a hard potato you can mash once cooked. Then they are crushed, releasing a sweet juice with the unmistakable aromas of blue agave: herbaceous, vegetal, olive, earthy and peppery."),
  v:()=>spF(spOven(70,150,1.2)+fChip(70,176,w3("cottura in forno","cuisson au four","oven cooking"))+fD(1,fArrow("M130 110H150")+spRollers(176,100,1)+fDrops(176,114,140,"#e6d58a",4)+fChip(176,176,w3("schiacciatura","broyage","crushing")))
   +[w3("erbaceo","herbacé","herbaceous"),w3("vegetale","végétal","vegetal"),w3("oliva","olive","olive"),w3("terra","terre","earthy"),w3("pepe","poivre","peppery")].map((l,i)=>fD(1.8+i*.35,fChip(272,32+i*26,l,"#5e8c31"))).join(""))},
 {h:I3_("Tequila o 100% agave?","Tequila ou 100 % agave ?","Tequila or 100% agave?"),
  c:I3_("Il succo d'agave si mescola con acqua prima della fermentazione, e il produttore può aggiungere anche altri zuccheri. La legge fissa un minimo: almeno il 51% degli zuccheri deve venire dall'agave blu. In etichetta, «100% agave» significa nessun altro zucchero e un carattere d'agave più marcato. Riguarda solo gli zuccheri: invecchiata o no, ogni Tequila può essere l'una o l'altra.",
   "Le jus d'agave est mélangé à de l'eau avant la fermentation, et le producteur peut ajouter d'autres sucres. La loi fixe un plancher : au moins 51 % des sucres doivent venir de l'agave bleu. « 100 % agave » sur l'étiquette veut dire aucun autre sucre, et un caractère d'agave plus marqué. Seuls les sucres comptent : vieillie ou non, toute Tequila peut être l'une ou l'autre.",
   "The agave juice is mixed with water before fermentation, and the producer may add other sugars too. The law sets a floor: at least 51% of the sugars must come from blue agave. A label saying '100% agave' means no other sugars at all, and a more pronounced agave character. This is about sugars only: aged or unaged, any Tequila can be either."),
  v:()=>spF([["Tequila",.51],["100% agave",1]].map(([l,f],i)=>{ const x=60+i*130; return fD(.3+i*1.2,`<rect x="${x}" y="40" width="70" height="120" rx="4" fill="rgba(255,255,255,.1)" stroke="#e8dccf"/><rect x="${x+2}" y="${158-116*f}" width="66" height="${116*f}" fill="#7aa79c"/>${f<1?`<rect x="${x+2}" y="42" width="66" height="${116*(1-f)-2}" fill="#e8c25a" opacity=".8"/>`+fT(x+35,72,w3("altri zuccheri","autres sucres","other sugars"),8.5,"#2a1b20"):""}`+fT(x+35,124,f<1?"51%+ agave":"agave",10,"#13302a")+fChip(x+35,184,l,i?"#8c1d40":undefined)); }).join("")
   +fD(2.6,fChip(225,22,w3("più agave","plus d'agave","more agave"),"#5e8c31")))},
 {h:I3_("Distillare per tenere l'agave","Distiller pour garder l'agave","Distilling to keep the agave"),
  c:I3_("La Tequila si può fare in colonna, ma le migliori si distillano due volte in alambicco discontinuo, fermandosi a un grado decisamente basso. Più il grado è basso, più restano nel distillato gli aromi erbacei e pepati dell'agave. È l'esatto contrario della vodka, spinta a gradi altissimi proprio per togliere l'aroma.",
   "La Tequila peut se faire en colonne, mais les meilleures sont distillées deux fois en alambic à repasse, en s'arrêtant à un degré nettement bas. Plus le degré est bas, plus les arômes herbacés et poivrés de l'agave restent dans l'eau-de-vie. C'est l'exact opposé de la vodka, poussée à très haut degré justement pour effacer les arômes.",
   "Tequila may be made in column stills, but the best ones are distilled twice in pot stills, stopping at a notably low strength. The lower the strength, the more of the agave's herbaceous, peppery aromas stay in the spirit. It is the exact opposite of vodka, pushed to a very high strength precisely to strip the aroma away."),
  v:()=>spF(spPotStill(30,150,.48)+fChip(66,40,w3("2 volte","2 fois","twice"),"#d4a23a","#2a1b20")+fD(.8,spTulip(176,150,"rgba(235,240,220,.6)",1.3)+spVapour(176,86,4,26,"#9cc65a")+fChip(176,186,w3("più agave","plus d'agave","more agave"),"#5e8c31"))
   +fD(1.8,`<g opacity=".55">${spColumn(280,150,120,9,{steam:false,out:false})}</g>`+fChip(276,176,w3("meno carattere","moins de caractère","less character"),"#5c646b")))},
 {h:I3_("Blanco e Joven","Blanco et Joven","Blanco and Joven"),
  c:I3_("Dopo la distillazione il produttore sceglie se invecchiare la Tequila. Ci sono due versioni non invecchiate. Blanco, detta anche Silver, è incolore e amata perché mostra l'agave allo stato puro. Joven, detta anche Oro o Gold, ha un bel colore dorato ma non ha mai visto una botte: il colore viene dal caramello, e altri additivi ne ammorbidiscono la consistenza.",
   "Après la distillation, le producteur choisit de vieillir ou non la Tequila. Il existe deux versions non vieillies. La Blanco, aussi appelée Silver, est incolore et appréciée parce qu'elle montre l'agave à l'état pur. La Joven, aussi appelée Oro ou Gold, a une belle couleur dorée mais n'a jamais vu de fût : la couleur vient du caramel, et d'autres additifs adoucissent sa texture.",
   "After distillation the producer chooses whether to age the Tequila. There are two unaged versions. Blanco, also called Silver, is colourless and prized for showing agave at its purest. Joven, also called Oro or Gold, has a golden colour but has never seen a barrel: the colour comes from caramel, and other additives soften its texture."),
  v:()=>spF(spBottle(80,110,"rgba(230,240,255,.55)",{lab:"BLANCO"})+fChip(80,164,"Blanco · Silver")+fChip(80,190,w3("agave pura","l'agave pure","pure agave"),"#5e8c31")
   +fD(1.2,spBottle(230,110,"#e8b84a",{lab:"JOVEN"})+fChip(230,164,"Joven · Oro · Gold")+spMolasses(282,70)+fChip(230,190,w3("colore: caramello","couleur : caramel","colour: caramel"),"#8c1d40"))+fD(2.2,fBarrel(150,40,.45)+spNo(150,40,14)+fT(150,68,w3("niente botte","pas de fût","no barrel"),9)))},
 {h:I3_("Reposado e Añejo","Reposado et Añejo","Reposado and Añejo"),
  c:I3_("Ci sono poi due versioni invecchiate in rovere. Reposado, cioè riposata, passa da 2 a 12 mesi in botte: è più morbida, ma il legno raramente si sente molto e l'agave resta protagonista. Añejo, cioè invecchiata, passa almeno 12 mesi in botte e unisce l'agave a note di rovere come vaniglia e spezie.",
   "Il existe aussi deux versions vieillies en fût de chêne. La Reposado, c'est-à-dire reposée, passe de 2 à 12 mois en fût : elle est plus souple, mais le bois se sent rarement beaucoup et l'agave reste au premier plan. L'Añejo, c'est-à-dire vieillie, passe au moins 12 mois en fût et associe l'agave à des notes de chêne comme la vanille et les épices.",
   "There are also two oak-aged versions. Reposado, meaning rested, spends between 2 and 12 months in oak: it is softer, but the wood rarely shows strongly and agave stays in the lead. Añejo, meaning aged, spends at least 12 months in barrel and combines agave with oak notes such as vanilla and spice."),
  v:()=>spF(`<path d="M20 100H300" stroke="#e8dccf" stroke-width="2"/>`+[[20,"0"],[50,"2"],[160,"12"],[300,"…"]].map(([x,l])=>`<path d="M${x} 94V106" stroke="#e8dccf" stroke-width="2"/>`+fT(x,120,l,10)).join("")+fT(160,140,w3("mesi in rovere","mois en fût","months in oak"),9,"#f3cd8a")
   +fD(.6,`<rect x="50" y="84" width="110" height="10" rx="4" fill="#e8c25a"/>`+spBottle(105,50,"#efd27a",{s:.55})+fChip(105,170,"Reposado","#5e8c31")+fChip(105,194,w3("agave in testa","l'agave d'abord","agave leads")))
   +fD(1.8,`<rect x="160" y="84" width="140" height="10" rx="4" fill="#c98a3a"/>`+spBottle(240,50,"#c98a3a",{s:.55})+fChip(240,170,"Añejo","#8c1d40")+fChip(240,194,w3("agave + rovere","agave + chêne","agave + oak"))))},
 {h:I3_("Equilibrio tra agave e legno","Équilibre entre agave et bois","Balancing agave and wood"),
  c:I3_("Perché le Tequile invecchiate restano poco in botte? Perché il produttore cerca l'equilibrio: un po' di vaniglia e spezie, senza coprire il carattere d'agave che rende unica la Tequila. Le versioni invecchiate vengono poi assemblate, possono ricevere caramello per uniformare il colore e sono diluite con acqua prima dell'imbottigliamento.",
   "Pourquoi les Tequilas vieillies restent-elles peu de temps en fût ? Parce que le producteur cherche l'équilibre : un peu de vanille et d'épices, sans couvrir le caractère d'agave qui rend la Tequila unique. Les versions vieillies sont ensuite assemblées, peuvent recevoir du caramel pour uniformiser la couleur et sont diluées à l'eau avant la mise en bouteille.",
   "Why do aged Tequilas spend fairly little time in barrel? Because the producer is looking for balance: some vanilla and spice, without burying the agave character that makes Tequila unique. Aged versions are then blended, may receive caramel to even out the colour, and are diluted with water before bottling."),
  v:()=>spF(spScale(160,150,spPina(-70,-42,.55),fBarrel(70,-48,.32))+fT(90,176,"agave",11,"#9cc65a")+fT(230,176,w3("rovere","chêne","oak"),11,"#f3cd8a")+fD(2.6,fChip(160,30,w3("equilibrio","équilibre","balance"),"#5e8c31"))
   +fD(3.2,fChip(160,190,w3("poi caramello, acqua","puis caramel, eau","then caramel, water"))))}
]},
/* ===================== s7 Flavoured spirits and liqueurs ===================== */
{id:"s1_flavoured", sec:"s", ch:"s7", ic:"order", t:I3_("Distillati aromatizzati e liquori","Spiritueux aromatisés et liqueurs","Flavoured spirits and liqueurs"), s:[
 {h:I3_("Una base comprata e i botanici","Une base achetée et les botaniques","A bought-in base and botanicals"),
  c:I3_("I distillati aromatizzati partono in modo diverso: di solito il produttore non coltiva e non fermenta nulla, ma compra un distillato già pronto, quasi sempre lo stesso distillato neutro che diluito diventa vodka. A volte la base è un rum, un whisky o un brandy. I prodotti migliori aggiungono poi ingredienti naturali, frutta, semi, erbe e spezie: i botanici.",
   "Les spiritueux aromatisés commencent autrement : en général le producteur ne cultive et ne fait fermenter rien, il achète un alcool tout prêt, presque toujours le même alcool neutre qui, dilué, devient vodka. Parfois la base est un rhum, un whisky ou un brandy. Les meilleurs produits ajoutent ensuite des ingrédients naturels, fruits, graines, herbes et épices : les botaniques.",
   "Flavoured spirits start differently: the producer usually grows and ferments nothing, but buys in a ready-made spirit, most often the same neutral spirit that becomes vodka once diluted. Now and then the base is a rum, whisky or brandy. The best products then add natural ingredients, fruits, seeds, herbs and spices, known as botanicals."),
  v:()=>spF(spSteel(30,60,70,100)+fT(65,130,w3("neutro","neutre","neutral"),11,"#2a1b20")+fChip(65,40,w3("comprato","acheté","bought in"),"#8c1d40")+fD(.8,fChip(65,186,w3("o rum, whisky, brandy","ou rhum/whisky/brandy","or rum, whisky, brandy")))
   +fD(1.4,spCitrus(160,60,12,ORANGE)+fT(160,90,w3("frutta","fruits","fruits"),9))+fD(1.8,spSeeds(222,52)+fT(229,90,w3("semi","graines","seeds"),9))+fD(2.2,fLeaf(160,146,1.4,0,"#5e9a32")+fT(160,164,w3("erbe","herbes","herbs"),9))+fD(2.6,spRoot(224,120,"#8a5a33")+fT(229,164,w3("spezie","épices","spices"),9))
   +fD(3.2,fChip(270,30,w3("= botanici","= botaniques","= botanicals"),"#5e8c31")))},
 {h:I3_("Ridistillazione: aromatico e incolore","Redistillation : aromatisé et incolore","Redistillation: flavoured, colourless"),
  c:I3_("Il primo metodo è la ridistillazione. Distillato neutro diluito e botanici entrano insieme in un alambicco discontinuo e si distillano. Il vapore porta gli aromi delle piante nel condensatore, e ciò che esce è profumato ma incolore. È il metodo con cui si fanno di solito i gin migliori.",
   "La première méthode est la redistillation. Alcool neutre dilué et botaniques entrent ensemble dans un alambic à repasse et sont distillés. La vapeur emporte les arômes des plantes vers le condenseur, et ce qui sort est parfumé mais incolore. C'est la méthode qu'utilisent en général les meilleurs gins.",
   "The first method is redistillation. Diluted neutral spirit and botanicals go into a pot still together and are distilled. The vapour carries the aromas of the plants into the condenser, and what comes out is fragrant but colourless. It is the method usually behind the best gins."),
  v:()=>spF(spPotStill(90,160,.95,{liq:"rgba(220,235,240,.7)"})+fD(.3,spJuniper(90,140,.6)+spPeel(74,146)+spSeeds(100,138))+fCall(70,140,40,90,w3("neutro + botanici","neutre + botaniques","neutral + botanicals"),.8)
   +fD(2,fChip(250,40,w3("profumato","parfumé","fragrant"),"#5e8c31")+fChip(250,66,w3("incolore","incolore","colourless"),"#5c646b")))},
 {h:I3_("Macerazione: aroma e colore","Macération : arôme et couleur","Maceration: flavour and colour"),
  c:I3_("Il secondo metodo è la macerazione: i botanici restano in infusione nel distillato, come una tisana fredda, e cedono sia aroma sia colore. Può durare pochi giorni o diversi mesi; più dura, più aroma si estrae, e un leggero riscaldamento accelera il processo.",
   "La deuxième méthode est la macération : les botaniques infusent dans l'alcool, comme une tisane froide, et cèdent à la fois arôme et couleur. Elle peut durer quelques jours ou plusieurs mois ; plus elle dure, plus on extrait d'arômes, et un léger chauffage accélère le processus.",
   "The second method is maceration: the botanicals steep in the spirit, like a cold herbal tea, giving up both flavour and colour. It can last a few days or several months; the longer it goes on, the more flavour is drawn out, and gentle heating speeds things up."),
  v:()=>spF(`<path d="M70 50H170V160Q170 168 162 168H78Q70 168 70 160Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.6"/><rect x="73" y="70" width="94" height="96" rx="4" fill="#e9dc8c" opacity=".25"><animate attributeName="fill" from="#e9dc8c" to="#b8452a" dur="5s" begin=".5s" fill="freeze"/><animate attributeName="opacity" from=".25" to=".8" dur="5s" begin=".5s" fill="freeze"/></rect>`+spPeel(100,120)+spSeeds(120,138)+fLeaf(150,110,.9,20,"#5e9a32")+spCitrus(96,150,8,ORANGE)+fChip(120,186,w3("aroma + colore","arôme + couleur","flavour + colour"),"#8c1d40")
   +fD(1.4,fClock(250,60,w3("giorni → mesi","jours → mois","days → months")))+fD(2.4,fHeater(250,170)+fChip(250,118,w3("il calore accelera","la chaleur accélère","heat speeds it up"),"#d4a23a","#2a1b20")))},
 {h:I3_("Aromi acquistati","Arômes achetés","Bought-in flavourings"),
  c:I3_("Il terzo metodo è il più semplice: aggiungere aromi acquistati, naturali o artificiali. Sono molto concentrati, quindi ne bastano piccole dosi. Di solito questa strada si sceglie per contenere i costi, al posto dei veri botanici. Molte vodka aromatizzate si fanno proprio così.",
   "La troisième méthode est la plus simple : ajouter des arômes achetés, naturels ou artificiels. Très concentrés, ils s'utilisent en petites doses. On choisit en général cette voie pour réduire les coûts, à la place de vraies botaniques. Beaucoup de vodkas aromatisées sont faites exactement ainsi.",
   "The third method is the simplest: adding bought-in flavourings, natural or artificial. They are very concentrated, so only small amounts are needed. This route is usually chosen for cost reasons, instead of real botanicals. Many flavoured vodkas are made exactly this way."),
  v:()=>spF(fTank(60,80,90,90,{col:"rgba(230,240,255,.6)"})+fD(.4,spBitters(105,48,true))+fD(1,fChip(105,186,w3("poche gocce","quelques gouttes","a few drops"),"#5e8c31"))
   +fD(1.8,fChip(250,60,w3("naturali o artificiali","naturels/artificiels","natural or artificial")))+fD(2.6,fChip(250,96,w3("molto concentrati","très concentrés","very concentrated"),"#8c1d40"))+fD(3.2,fChip(250,132,w3("costo più basso","coût plus bas","lower cost"),"#5c646b")))},
 {h:I3_("La vodka aromatizzata","La vodka aromatisée","Flavoured vodka"),
  c:I3_("La vodka aromatizzata è il caso più intuitivo: una base neutra con un solo aroma chiaro. Le possibilità sono infinite: vaniglia, frutta come mela o limone, perfino spezie come il pepe. La maggior parte dei produttori aggiunge aromi acquistati, anche se alcuni ridistillano. Al naso si riconosce subito: un solo aroma, netto e diretto.",
   "La vodka aromatisée est le cas le plus intuitif : une base neutre avec un seul arôme bien net. Les possibilités sont infinies : vanille, fruits comme la pomme ou le citron, même des épices comme le poivre. La plupart des producteurs ajoutent des arômes achetés, certains redistillent. Au nez, on la reconnaît vite : un seul arôme, net et direct.",
   "Flavoured vodka is the most intuitive case: a neutral base given one clear flavour. The options are endless: vanilla, fruits such as apple or lemon, even spices like pepper. Most producers simply add bought-in flavourings, although some use redistillation. On the nose it is easy to spot: one flavour, clean and direct."),
  v:()=>spF([[`<path d="M-14 0Q0 -6 14 -18" stroke="#9a6a3a" stroke-width="4" stroke-linecap="round" fill="none"/>`,w3("vaniglia","vanille","vanilla")],[`<circle r="11" fill="#c0392b"/><path d="M0 -10q2 -6 6 -8" stroke="#5e8c31" stroke-width="2" fill="none"/>`,w3("mela","pomme","apple")],[spCitrus(0,0,11,LEMON),w3("limone","citron","lemon")],[[-6,0,6,-3,3].map((a,i)=>`<circle cx="${a}" cy="${i<3?0:-7}" r="3.2" fill="#4a3a36" stroke="#e8dccf" stroke-width=".8"/>`).join(""),w3("pepe","poivre","pepper")]]
   .map(([ic,l],i)=>fD(.3+i*.5,`<g transform="translate(${46+i*76} 44)">${ic}</g>`+spBottle(46+i*76,124,"rgba(230,240,255,.5)",{s:.8})+fT(46+i*76,170,l,10))).join("")+fD(2.6,fChip(160,196,w3("un solo aroma, netto","un seul arôme, net","one clean flavour"),"#8c1d40")))},
 {h:I3_("Il gin: il ginepro in testa","Le gin : le genièvre d'abord","Gin: juniper first"),
  c:I3_("Il gin ha una regola essenziale: il ginepro deve essere l'aroma principale, con le sue note resinose, di pino. Accanto ci sono spesso semi di coriandolo, radice di angelica, radice di iris e scorza di agrumi. La base è di solito un distillato neutro, anche se negli USA sono ammessi altri distillati. Un gin tipico è incolore e non invecchiato.",
   "Le gin a une règle essentielle : le genièvre doit être l'arôme dominant, avec ses notes résineuses, de pin. À côté, on trouve souvent des graines de coriandre, de la racine d'angélique, de la racine d'iris et des zestes d'agrumes. La base est en général un alcool neutre, même si d'autres spiritueux sont permis aux États-Unis. Un gin typique est incolore et non vieilli.",
   "Gin has one essential rule: juniper must be the leading flavour, with its resinous, piney notes. Alongside it you often find coriander seed, angelica root, orris root and citrus peel. The base is usually neutral spirit, although other distilled spirits are allowed in the USA. A typical gin is colourless and unaged."),
  v:()=>spF(spJuniper(160,96,2.2)+fD(.4,fChip(160,40,w3("ginepro in testa","genièvre d'abord","juniper leads"),"#3d4f8a"))+fD(.8,fChip(160,150,w3("resinoso, pino","résineux, pin","resinous, piney"),"#5e8c31"))
   +fD(1.6,spSeeds(28,60)+fT(36,92,w3("coriandolo","coriandre","coriander"),9))+fD(2,spRoot(270,48)+fT(276,96,w3("angelica","angélique","angelica"),9))+fD(2.4,spRoot(30,128,"#c9a0b8")+fT(36,176,w3("radice di iris","racine d'iris","orris root"),9))+fD(2.8,spPeel(276,146,LEMON)+fT(276,176,w3("scorza di agrumi","zestes d'agrumes","citrus peel"),9)))},
 {h:I3_("London Dry Gin","London Dry Gin","London Dry Gin"),
  c:I3_("I gin migliori si ridistillano di solito con i loro botanici, anche se alcuni aromi molto delicati si aggiungono dopo; altri produttori aggiungono semplicemente aromi acquistati. In etichetta, London Dry Gin significa che gli aromi sono stati dati durante la ridistillazione. Nonostante il nome, non è un luogo: un London Dry Gin si può fare ovunque nel mondo.",
   "Les meilleurs gins sont en général redistillés avec leurs botaniques, même si certains arômes très délicats s'ajoutent après ; d'autres producteurs ajoutent simplement des arômes achetés. Sur l'étiquette, London Dry Gin signifie que les arômes ont été apportés pendant la redistillation. Malgré le nom, ce n'est pas un lieu : un London Dry Gin peut se faire partout dans le monde.",
   "The best gins are usually redistilled with their botanicals, though some very delicate flavours are added afterwards; other producers simply add bought-in flavourings. On a label, London Dry Gin means the flavours were added during redistillation. Despite the name, it is not a place: a London Dry Gin can be made anywhere in the world."),
  v:()=>spF(spPotStill(40,150,.6)+spJuniper(40,130,.5)+fChip(80,180,w3("ridistillazione","redistillation","redistillation"),"#5e8c31")+fD(1.2,fArrow("M136 120H160")+spBottle(190,110,"rgba(230,240,255,.5)",{lab:"GIN"}))
   +fD(2.2,`<circle cx="272" cy="96" r="30" fill="#3f6f98" stroke="#e8dccf"/><path d="M252 86q10 -8 18 -2q2 8 -6 10ZM276 80q12 -4 16 6q-2 8 -12 6ZM266 106q10 -2 12 6q-4 10 -10 8Z" fill="#5e8c4a"/>`+spPin(258,90)+spPin(286,104)+fChip(272,150,w3("ovunque","partout","anywhere"),"#8c1d40")))},
 {h:I3_("Amari e bitter da cocktail","Amers et bitters à cocktail","Bitter spirits and cocktail bitters"),
  c:I3_("I distillati amari contengono almeno un botanico amaro, come genziana, chinino o arancia amara. L'amaro si sente solo in bocca: il naso non lo percepisce. I bitter da cocktail vanno oltre: concentratissimi e molto amari, non si bevono mai da soli ma si usano a gocce, come sale e pepe in cucina, per dare complessità.",
   "Les spiritueux amers contiennent au moins une botanique amère, comme la gentiane, la quinine ou l'orange amère. L'amertume ne se perçoit qu'en bouche : le nez ne la détecte pas. Les bitters à cocktail vont plus loin : très concentrés et très amers, ils ne se boivent jamais seuls mais s'utilisent à la goutte, comme le sel et le poivre en cuisine, pour la complexité.",
   "Bitter spirits contain at least one bitter botanical, such as gentian, quinine or bitter orange. Bitterness shows only in the mouth: the nose cannot detect it. Cocktail bitters go further: highly concentrated and intensely bitter, they are never drunk alone but used by the dash, like salt and pepper in cooking, to add complexity."),
  v:()=>spF(spBottle(54,110,"#b5243a",{s:.9})+[w3("genziana","gentiane","gentian"),w3("chinino","quinine","quinine"),w3("arancia amara","orange amère","bitter orange")].map((l,i)=>fD(.4+i*.4,fChip(130,60+i*24,l,"#8a5a33"))).join("")+fD(1.8,fChip(92,180,w3("amaro solo in bocca","amertume : en bouche","bitter only in mouth"),"#8c1d40"))
   +fD(2.4,spBitters(260,70,true)+spCocktail(260,150,"rocks","#c98a3a",{ice:1})+fChip(260,180,w3("a gocce","à la goutte","by the dash"),"#5e8c31")))},
 {h:I3_("Il rum speziato","Le rhum épicé","Spiced rum"),
  c:I3_("Il rum speziato è una famiglia molto varia. Molti partono da un rum leggero non invecchiato, aromatizzato e colorato con caramello; solo pochi usano un rum invecchiato in rovere. Si usano sia veri botanici sia altri aromi. Quindi attenzione: un rum speziato color ambra non significa per forza anni in botte.",
   "Le rhum épicé est une famille très variée. Beaucoup partent d'un rhum léger non vieilli, aromatisé et coloré au caramel ; seuls quelques-uns utilisent un rhum vieilli en fût. On emploie de vraies botaniques comme d'autres arômes. Attention donc : un rhum épicé couleur ambre ne veut pas forcément dire des années en fût.",
   "Spiced rum is a very varied family. Many start from a light, unaged rum that is flavoured and coloured with caramel; only a handful use an oak-aged rum. Both real botanicals and other flavourings are used. So be careful: an amber spiced rum does not necessarily mean years in a barrel."),
  v:()=>spF(spBottle(40,110,"rgba(230,240,255,.5)",{s:.8})+fT(40,156,w3("rum leggero","rhum léger","light rum"),9)+fD(.6,fT(84,110,"+",18,"#f3cd8a")+spRoot(110,80,"#8a5a33")+spSeeds(104,124,"#5a3a22")+fT(118,156,w3("spezie, aromi","épices, arômes","spices, flavourings"),9))
   +fD(1.4,fT(150,110,"+",18,"#f3cd8a")+spMolasses(184,130)+fT(184,156,w3("caramello","caramel","caramel"),9))+fD(2.2,fArrow("M210 110H230")+spBottle(262,110,"#b9742e",{s:.9}))+fD(3,fBarrel(262,40,.4)+spNo(262,40,12)+fChip(262,180,w3("ambra ≠ anni","ambre ≠ années","amber ≠ years"),"#8c1d40")))},
 {h:I3_("I liquori: aromatizzati e dolci","Les liqueurs : aromatisées et sucrées","Liqueurs: flavoured and sweet"),
  c:I3_("Un liquore è un distillato aromatizzato e anche addolcito, e la legge fissa una dolcezza minima. La maggior parte usa distillato neutro, alcuni brandy, rum o whisky. Ogni aroma è possibile: agrumi, caffè, erbe, nocciola, perfino panna, per una consistenza vellutata. Molti sono colorati, spesso con coloranti artificiali, più stabili e più vivaci.",
   "Une liqueur est un spiritueux aromatisé et aussi sucré, et la loi fixe une douceur minimale. La plupart partent d'un alcool neutre, certaines d'un brandy, d'un rhum ou d'un whisky. Toute saveur est possible : agrumes, café, herbes, noisette, même la crème, pour une texture veloutée. Beaucoup sont colorées, souvent avec des colorants artificiels, plus stables et plus vifs.",
   "A liqueur is a flavoured spirit that has also been sweetened, and the law sets a minimum sweetness. Most use neutral spirit, some brandy, rum or whisky. Any flavour is possible: citrus, coffee, herbs, hazelnut, even cream for a velvety texture. Many are coloured too, often artificially, because those colours are more stable and brighter."),
  v:()=>spF(fBox(14,22,110,28,w3("aromatizzato","aromatisé","flavoured"))+fT(140,42,"+",16,"#f3cd8a")+fD(.6,spSugar(162,44,2)+fChip(240,36,w3("dolcezza minima","douceur minimale","minimum sweetness"),"#8c1d40"))
   +[["#f39a2b",w3("agrumi","agrumes","citrus")],["#3a2214",w3("caffè","café","coffee")],["#3fae6a",w3("erbe","herbes","herbs")],["#a8662a",w3("nocciola","noisette","hazelnut")],["#efe3c8",w3("panna","crème","cream")],["#3f6fd0",w3("colorato","coloré","coloured")]].map(([c,l],i)=>fD(1.2+i*.35,spBottle(30+i*52,130,c,{s:.7})+fT(30+i*52,170,l,9))).join(""))}
]},
/* ===================== s8 Aromatised wines ===================== */
{id:"s1_aromwine", sec:"s", ch:"s8", ic:"grapes", t:I3_("Vini aromatizzati","Vins aromatisés","Aromatised wines"), s:[
 {h:I3_("Non sono distillati, ma…","Ce ne sont pas des spiritueux, mais…","Not spirits, but…"),
  c:I3_("I vini aromatizzati non sono distillati, eppure ogni bar li ha, perché sono utilissimi nei cocktail: un solo ingrediente porta insieme dolcezza, amaro e acidità. La categoria è varia, ma la ricetta di base non cambia mai, ed è costruita con quattro componenti.",
   "Les vins aromatisés ne sont pas des spiritueux, et pourtant chaque bar en a, car ils sont très utiles dans les cocktails : un seul ingrédient apporte à la fois douceur, amertume et acidité. La catégorie est variée, mais la recette de base ne change jamais, et elle repose sur quatre composants.",
   "Aromatised wines are not spirits, yet every bar has them, because they are so useful in cocktails: a single ingredient brings sweetness, bitterness and acidity at once. The category is varied, but the basic recipe never changes, and it is built from four components."),
  v:()=>spF(fBottle(80,110,{col:"#8a2a1a",label:1,cork:1})+fT(80,166,w3("vino aromatizzato","vin aromatisé","aromatised wine"),9.5)
   +[[w3("dolce","sucré","sweet"),"#d4a23a"],[w3("amaro","amer","bitter"),"#8a5a33"],[w3("acido","acide","acidic"),"#5e8c31"]].map(([l,c],i)=>fD(.6+i*.6,fChip(230,46+i*30,l,c))).join("")+fD(2.6,fChip(230,150,w3("in un solo ingrediente","en un seul ingrédient","in one ingredient"),"#8c1d40")))},
 {h:I3_("I quattro componenti","Les quatre composants","The four components"),
  c:I3_("I quattro componenti sono un vino di base, aromi che includono sempre qualcosa di amaro, zucchero e un po' di distillato. A volte si aggiunge anche caramello. Immaginalo come una scheda di ricetta: cambiando il vino, i botanici o la quantità di zucchero si ottiene un prodotto diverso, ma questi quattro mattoni ci sono sempre.",
   "Les quatre composants sont un vin de base, des arômes qui comprennent toujours quelque chose d'amer, du sucre et un peu de spiritueux. On ajoute parfois du caramel. Voyez-le comme une fiche recette : en changeant le vin, les botaniques ou la dose de sucre, on obtient un autre produit, mais ces quatre briques sont toujours là.",
   "The four components are a base wine, flavourings that always include something bitter, sugar, and a little spirit. Caramel is sometimes added too. Think of it as a recipe card: change the wine, the botanicals or the amount of sugar and you get a different product, but those four building blocks are always there."),
  v:()=>spF([[fStemGlass(0,0,"white","#e9dc8c"),w3("vino di base","vin de base","base wine")],[spWormwood(0,10,.7),w3("aromi + amaro","arômes + amer","bitter flavourings")],[spSugar(-10,4,2),w3("zucchero","sucre","sugar")],[spBottle(0,-6,"rgba(230,240,255,.55)",{s:.55}),w3("distillato","spiritueux","spirit")]]
   .map(([ic,l],i)=>fD(.3+i*.6,`<g transform="translate(${44+i*77} 90)">${ic}</g>`+fT(44+i*77,132,l,9,"#f3cd8a","middle",700,12)+(i<3?fT(82+i*77,96,"+",16,"#f3cd8a"):""))).join("")+fD(3,fChip(160,176,w3("+ caramello (facolt.)","+ caramel (option)","+ caramel (optional)"),"#5c646b")))},
 {h:I3_("Il vino e gli aromi amari","Le vin et les arômes amers","The wine and the bitter flavourings"),
  c:I3_("Il vino di base è quasi sempre bianco e spesso piuttosto neutro, una tela bianca per gli aromi; alcuni produttori usano vini aromatici, oppure rossi o rosati. Gli aromi vanno direttamente nel vino o si aggiungono come distillati aromatizzati. Le ricette variano molto, ma tutte hanno botanici amari come assenzio, genziana o chinino.",
   "Le vin de base est presque toujours blanc et souvent assez neutre, une toile blanche pour les arômes ; certains producteurs utilisent des vins aromatiques, ou du rouge, ou du rosé. Les arômes vont directement dans le vin ou s'ajoutent sous forme de spiritueux aromatisés. Les recettes varient beaucoup, mais toutes contiennent des botaniques amères comme l'absinthe, la gentiane ou la quinine.",
   "The base wine is nearly always white and often fairly neutral, a blank canvas for the flavours; some producers use aromatic wines, or red or rosé. Flavourings go straight into the wine or are added as flavoured spirits. Recipes vary a lot, but all include bitter botanicals such as wormwood, gentian or quinine."),
  v:()=>spF(fStemGlass(54,100,"white","#e9dc8c")+fChip(54,130,w3("bianco, neutro","blanc, neutre","white, neutral"),"#5e8c31")+fD(.8,`<g opacity=".8">${fStemGlass(110,100,"white","#c0392b")+fStemGlass(140,100,"white","#f0a3a0")}</g>`+fT(110,158,w3("a volte rosso, rosato","parfois rouge, rosé","sometimes red, rosé"),9))
   +fD(1.6,spWormwood(200,120,1)+fChip(200,140,w3("assenzio","absinthe","wormwood"),"#8a5a33"))+fD(2.2,spRoot(250,60,"#c9a04a")+fChip(270,108,w3("genziana","gentiane","gentian"),"#8a5a33"))+fD(2.8,fChip(270,40,w3("chinino","quinine","quinine"),"#8a5a33")))},
 {h:I3_("Distillato, zucchero, caramello","Spiritueux, sucre, caramel","Spirit, sugar, caramel"),
  c:I3_("Una piccola quantità di distillato, quasi sempre neutro, alza la gradazione e allunga la vita del prodotto, soprattutto a bottiglia aperta. Quasi nessun vino aromatizzato è del tutto secco: la dolcezza viene dal vino stesso o da zucchero aggiunto. Il caramello è facoltativo, serve per il colore e nei prodotti rossi fatti da vino bianco può dare note di caramello.",
   "Une petite quantité de spiritueux, presque toujours neutre, relève le degré et allonge la vie du produit, surtout une fois la bouteille ouverte. Presque aucun vin aromatisé n'est tout à fait sec : la douceur vient du vin lui-même ou de sucre ajouté. Le caramel est facultatif, il sert pour la couleur et, dans les produits rouges faits de vin blanc, il peut donner des notes de caramel.",
   "A small amount of spirit, nearly always neutral, raises the alcohol and gives the product a longer life, especially once the bottle is open. Almost no aromatised wine is fully dry: sweetness comes from the wine itself or from added sugar. Caramel is optional, used for colour, and in red products made from white wine it can add caramel notes."),
  v:()=>spF(spBottle(50,110,"rgba(230,240,255,.55)",{s:.7})+spPour(62,82,110,96,"rgba(230,240,255,.8)",2)+fBottle(140,110,{col:"#8a2a1a",cork:1})+fD(.8,fChip(140,170,w3("più alcol","plus d'alcool","more alcohol"),"#8c1d40")+fChip(140,192,w3("dura di più aperto","se garde mieux ouvert","lasts longer once open")))
   +fD(1.8,spSugar(244,50,2)+fChip(256,82,w3("quasi mai secco","presque jamais sec","almost never dry"),"#d4a23a","#2a1b20"))+fD(2.6,spMolasses(256,140)+fChip(256,164,w3("caramello: colore","caramel : couleur","caramel: colour"))))},
 {h:I3_("Il vermut","Le vermouth","Vermouth"),
  c:I3_("I vini aromatizzati si possono fare ovunque, ma due zone sono particolarmente famose: il sud-est della Francia e il nord-ovest dell'Italia. In entrambe il tipo più prodotto è il vermut. Due regole lo definiscono: si fa con una base di vino bianco e deve essere aromatizzato con l'assenzio, un botanico dal gusto molto amaro.",
   "Les vins aromatisés peuvent se faire partout, mais deux zones sont particulièrement célèbres : le sud-est de la France et le nord-ouest de l'Italie. Dans les deux, le type le plus produit est le vermouth. Deux règles le définissent : il est fait à partir d'une base de vin blanc et doit être aromatisé à l'absinthe, une botanique au goût très amer.",
   "Aromatised wines can be made anywhere, but two areas are especially famous: south-east France and north-west Italy. In both, the most widely made type is vermouth. Two rules define it: it is made from a white wine base, and it must be flavoured with wormwood, a botanical with a strongly bitter taste."),
  v:()=>spF(`<path d="M30 40L80 30L104 52L96 92L106 126L70 140L40 128L44 92L28 68Z" fill="#4f6e45" stroke="#e8dccf" stroke-width="1.2"/><path d="M118 70L150 62L160 80L176 108L196 128L190 140L170 126L150 104L130 92Z" fill="#4f6e45" stroke="#e8dccf" stroke-width="1.2"/>`+fD(.5,spPin(94,112)+spPin(124,82))+fD(.9,fChip(70,162,w3("SE Francia","SE France","SE France"))+fChip(160,162,w3("NO Italia","NO Italie","NW Italy")))
   +fD(1.8,fStemGlass(240,80,"white","#e9dc8c")+fT(270,72,"+",16,"#f3cd8a")+spWormwood(294,96,.8)+fChip(256,128,w3("vino bianco + assenzio","vin blanc + absinthe","white wine + wormwood"),"#8c1d40")))},
 {h:I3_("Dry e rosso","Dry et rouge","Dry and red"),
  c:I3_("Attenzione alle etichette: un vermut con la scritta dry contiene quasi sempre zucchero aggiunto, solo meno. I vermut rossi sono di solito molto zuccherati. E il loro colore? Poiché la base è un vino bianco, la tinta rossa viene di solito dal caramello, che può dare anche un leggero aroma di caramello.",
   "Attention aux étiquettes : un vermouth marqué dry contient presque toujours du sucre ajouté, seulement moins. Les vermouths rouges sont en général très sucrés. Et leur couleur ? Comme la base est un vin blanc, la teinte rouge vient le plus souvent du caramel, qui peut aussi apporter un léger arôme de caramel.",
   "Watch the labels: a vermouth marked dry nearly always contains added sugar, just less of it. Red vermouths are usually heavily sweetened. And their colour? Since the base is a white wine, the red shade usually comes from caramel, which can also add a light caramel aroma."),
  v:()=>spF(fBottle(80,100,{col:"#e9dc8c",label:1,cork:1})+fChip(80,30,"dry","#5c646b")+fD(.6,spSugar(74,166,1)+fChip(80,186,w3("un po' di zucchero","un peu de sucre","some sugar")))
   +fD(1.4,fBottle(230,100,{col:"#7a1a12",label:1,cork:1})+fChip(230,30,w3("rosso","rouge","red"),"#8c1d40")+spSugar(218,166,3)+fChip(230,186,w3("molto dolce","très sucré","very sweet"),"#d4a23a","#2a1b20"))+fD(2.4,spMolasses(290,90)+fT(290,110,w3("caramello","caramel","caramel"),9)))},
 {h:I3_("Il vermut dietro il bancone","Le vermouth derrière le bar","Vermouth behind the bar"),
  c:I3_("Dietro il bancone il vermut è un vero tuttofare. Un vermut dry dà secchezza e profumo a un drink a base di gin, mentre uno rosso, dolce con un bordo amaro, arrotonda un cocktail di whiskey. In ogni caso bilancia dolcezza, amaro e acidità in un solo gesto: conviene conoscerne stile e dolcezza prima di prendere la bottiglia.",
   "Derrière le bar, le vermouth est un vrai couteau suisse. Un vermouth dry apporte sécheresse et parfum à un drink à base de gin, tandis qu'un rouge, sucré avec une pointe d'amertume, arrondit un cocktail au whiskey. Dans les deux cas, il équilibre douceur, amertume et acidité en un seul geste : mieux vaut connaître son style et sa douceur avant de saisir la bouteille.",
   "Behind the bar, vermouth is a real all-rounder. A dry vermouth adds dryness and perfume to a gin-based drink, while a red one, sweet with a bitter edge, rounds out a whiskey cocktail. Either way it balances sweetness, bitterness and acidity in one pour, so it pays to know its style and sweetness before reaching for the bottle."),
  v:()=>spF(spDrink(80,"gin + dry","martini","rgba(240,240,220,.75)",{olive:1,s:1.3},[w3("secchezza, profumo","sécheresse, parfum","dryness, perfume")],.3)+spDrink(240,w3("whiskey + rosso","whiskey + rouge","whiskey + red"),"coupe","#8a3a1a",{s:1.3},[w3("rotondità","rondeur","roundness")],1.4)
   +fD(2.6,fChip(160,186,w3("dolce · amaro · acido","sucré · amer · acide","sweet · bitter · sour"),"#5e8c31")))}
]},
/* ===================== t1 Tasting a spirit ===================== */
{id:"s1_tasting", sec:"t", ch:"t1", ic:"sat", t:I3_("Degustare un distillato","Déguster un spiritueux","Tasting a spirit"), s:[
 {h:I3_("Un metodo sempre uguale","Une méthode toujours identique","Always the same method"),
  c:I3_("Degustare un distillato significa osservarlo da vicino, e per farlo bene serve un metodo da ripetere ogni volta allo stesso modo. Se ogni campione è trattato in modo identico, le note di oggi si possono confrontare con quelle del mese prossimo. Prima di versare, però, conviene preparare l'ambiente.",
   "Déguster un spiritueux, c'est l'observer de près, et pour bien le faire il faut une méthode répétée chaque fois de la même façon. Si chaque échantillon est traité de manière identique, les notes d'aujourd'hui pourront se comparer à celles du mois prochain. Avant de verser quoi que ce soit, mieux vaut toutefois préparer le lieu.",
   "Tasting a spirit means looking at it closely, and doing that well needs a method you repeat the same way every time. If every sample is treated identically, the notes you write today can be compared with those you write next month. Before pouring anything, though, it pays to prepare the setting."),
  v:()=>spF([0,1].map(i=>fD(.3+i*1.2,`<g transform="translate(${50+i*150} 40)"><rect width="90" height="110" rx="6" fill="#fbf3e2" stroke="#d8cdb8"/>${[0,1,2,3,4,5].map(k=>`<path d="M12 ${22+k*14}H${50+(k*17)%28}" stroke="#8c1d40" stroke-width="2.4" stroke-linecap="round"/>`).join("")}</g>`+fChip(95+i*150,166,i?w3("il mese prossimo","le mois prochain","next month"):w3("oggi","aujourd'hui","today")))).join("")+fD(2.2,fT(160,104,"=",26,"#f3cd8a")+fChip(160,30,w3("stesso metodo","même méthode","same method"),"#5e8c31")))},
 {h:I3_("Preparare l'ambiente","Préparer le lieu","Setting the scene"),
  c:I3_("La stanza deve essere libera da odori che distraggono: niente profumi forti, cucina o candele profumate. Servono buona luce naturale e una superficie bianca, come un foglio di carta, per giudicare il colore senza riflessi ingannevoli. Conta anche chi degusta: bocca pulita, senza tracce di dentifricio o caffè, e un corpo ben idratato.",
   "La pièce doit être libre d'odeurs gênantes : pas de parfum fort, de cuisine ou de bougies parfumées. Il faut une bonne lumière naturelle et une surface blanche, comme une feuille de papier, pour juger la couleur sans reflets trompeurs. Le dégustateur compte aussi : une bouche propre, sans trace de dentifrice ou de café, et un corps bien hydraté.",
   "The room should be free of distracting smells: no strong perfume, cooking or scented candles. You need good natural light and a white surface, such as a sheet of paper, to judge colour without misleading reflections. The taster matters too: a clean palate, with no lingering toothpaste or coffee, and a well-hydrated body."),
  v:()=>spF(`<rect x="20" y="20" width="80" height="70" rx="4" fill="#bfe6f6" stroke="#e8dccf" stroke-width="3"/><path d="M60 20V90M20 55H100" stroke="#e8dccf" stroke-width="3"/>`+fSun(84,36,8)+fChip(60,104,w3("luce naturale","lumière naturelle","natural light"),"#d4a23a","#2a1b20")
   +fD(.8,`<rect x="120" y="120" width="90" height="56" rx="3" fill="#fbf6ec"/>`+spTulip(165,160,"#d9a441",1)+fChip(165,190,w3("superficie bianca","surface blanche","white surface")))
   +fD(1.6,[w3("profumo","parfum","perfume"),w3("cucina","cuisine","cooking"),w3("dentifricio","dentifrice","toothpaste"),w3("caffè","café","coffee")].map((l,i)=>fD(i*.35,fChip(268,30+i*26,l,"#5c646b")+`<path d="M222 ${30+i*26-3}H314" stroke="#e2622a" stroke-width="2"/>`)).join(""))+fD(3,spTumbler(268,170,"#9fd3f0",1)+fT(268,186,w3("acqua","eau","water"),9)))},
 {h:I3_("Il bicchiere giusto","Le bon verre","The right glass"),
  c:I3_("Poi viene il bicchiere. La forma ideale ha una coppa ampia che si stringe verso il bordo, un po' come un tulipano. La parte larga dà spazio agli aromi per salire, e l'apertura più stretta li raccoglie e li porta al naso. In un bicchiere dritto e aperto i profumi si disperdono, e il distillato sembra meno espressivo.",
   "Vient ensuite le verre. La forme idéale a un large calice qui se resserre vers le bord, un peu comme une tulipe. La partie large laisse de la place aux arômes pour monter, et l'ouverture plus étroite les rassemble et les conduit vers le nez. Dans un verre droit et ouvert, les parfums s'échappent, et le spiritueux paraît moins expressif.",
   "Then comes the glass. The ideal shape has a wide bowl that narrows towards the rim, a little like a tulip. The wide part gives the aromas room to rise, and the narrower opening gathers them and channels them to your nose. In a straight, open tumbler the scents drift away and the spirit seems less expressive."),
  v:()=>spF(spTulip(90,150,"#d9a441",1.7)+`<path d="M78 120Q90 100 88 74M102 120Q90 100 92 74" stroke="#f3cd8a" stroke-width="2" fill="none" stroke-dasharray="4 3"><animate attributeName="stroke-dashoffset" from="14" to="0" dur=".8s" repeatCount="indefinite"/></path>`+spNose(96,46)+fChip(90,186,w3("aromi concentrati","arômes concentrés","aromas gathered"),"#5e8c31")
   +fD(1.4,spTumbler(240,150,"#d9a441",1.6)+[-1,1].map(k=>`<path d="M${240+k*12} 92Q${240+k*30} 70 ${240+k*44} 60" stroke="#f3cd8a" stroke-width="2" fill="none" stroke-dasharray="4 3" opacity=".7"><animate attributeName="stroke-dashoffset" from="14" to="0" dur=".8s" repeatCount="indefinite"/></path>`).join("")+fChip(240,186,w3("aromi dispersi","arômes dispersés","aromas drift away"),"#5c646b")))},
 {h:I3_("Un campione piccolo","Un petit échantillon","A small sample"),
  c:I3_("Anche dopo la diluizione, un distillato resta una bevanda molto forte: al 40% vol. l'alcol punge il naso e scalda la bocca, nascondendo molti dettagli. Per questo si lavora con un campione piccolo, circa 1,5 cL, più o meno un cucchiaio. Dà tutto ciò che serve senza stancare i sensi.",
   "Même après la dilution, un spiritueux reste une boisson très forte : à 40 % vol., l'alcool pique le nez et chauffe la bouche, masquant beaucoup de détails. On travaille donc avec un petit échantillon, environ 1,5 cL, à peu près une cuillère à soupe. Cela donne tout le nécessaire sans fatiguer les sens.",
   "Even after dilution, a spirit is a very strong drink: at 40% abv the alcohol stings the nose and warms the mouth, hiding many details. So you work with a small sample of about 1.5 cL, roughly a tablespoon. It gives you everything you need without tiring your senses."),
  v:()=>spF(spBottle(50,110,"#d9a441",{lab:"40%"})+fD(.6,fChip(50,166,w3("l'alcol punge","l'alcool pique","alcohol stings"),"#8c1d40"))+fD(1.2,spPour(64,64,150,104,"#d9a441",2)+spTulip(160,150,"#d9a441",1.4))
   +fD(2,spSpoon(226,110)+fChip(250,60,"≈ 1,5 cL","#d4a23a","#2a1b20")+fChip(250,150,w3("un cucchiaio","une cuillère","a tablespoon"))))},
 {h:I3_("Guardare, annusare, acqua, annusare","Regarder, sentir, eau, sentir","Look, smell, water, smell again"),
  c:I3_("Il percorso è semplice. Prima si guarda il campione e lo si annusa puro. Poi si aggiunge la stessa quantità d'acqua, altri 1,5 cL, che dimezza il grado. Si annusa di nuovo: spesso compaiono aromi che l'alcol nascondeva, come aprire una finestra in una stanza affollata. Solo allora si passa all'assaggio.",
   "Le parcours est simple. D'abord on regarde l'échantillon et on le sent pur. Puis on ajoute la même quantité d'eau, encore 1,5 cL, ce qui divise le degré par deux. On sent à nouveau : des arômes que l'alcool cachait apparaissent souvent, comme quand on ouvre une fenêtre dans une pièce bondée. Ensuite seulement, on goûte.",
   "The route is simple. First look at the sample and smell it neat. Then add the same amount of water, another 1.5 cL, which halves the strength. Smell again: aromas the alcohol was hiding often appear, like opening a window in a crowded room. Only then do you move on to tasting."),
  v:()=>spF(spEye(40,40)+spTulip(40,140,"#d9a441",1)+fT(40,176,"1",14,"#f3cd8a")+fD(.8,spNose(118,46)+spTulip(116,140,"#d9a441",1)+spVapour(116,98,2,16,"#f3cd8a")+fT(116,176,"2",14,"#f3cd8a"))
   +fD(1.6,spJug(186,64,1,192,104)+spTulip(196,140,"#e3bf6a",1)+fT(196,176,"3",14,"#f3cd8a")+fChip(196,30,w3("stessa quantità","même quantité","same amount"),"#3f7fa8"))
   +fD(2.6,spNose(280,46)+spTulip(276,140,"#e3bf6a",1)+spVapour(276,98,4,18,"#f6a43a")+fT(276,176,"4",14,"#f3cd8a")+fChip(250,192,w3("nuovi aromi","nouveaux arômes","new aromas"),"#5e8c31")))},
 {h:I3_("Assaggiare e sputare","Goûter et recracher","Taste and spit"),
  c:I3_("In bocca si fa girare il liquido per qualche secondo, si cercano i sapori e poi si sputa. Sputare non è maleducato: permette di assaggiare più campioni restando lucidi, e di giudicare l'ultimo con la stessa attenzione del primo. In breve: campione piccolo, occhi e naso, acqua in pari quantità, di nuovo naso, bocca, sputare.",
   "En bouche, on fait tourner le liquide quelques secondes, on cherche les saveurs, puis on recrache. Recracher n'est pas impoli : cela permet de goûter plusieurs échantillons en gardant les idées claires, et de juger le dernier avec autant de soin que le premier. En bref : petit échantillon, yeux et nez, autant d'eau, nez encore, bouche, recracher.",
   "In the mouth, roll the liquid around for a few seconds, look for the flavours and then spit it out. Spitting is not rude: it lets you taste several samples while staying clear-headed, and judge the last one as carefully as the first. In short: small sample, eyes and nose, equal water, nose again, palate, spit."),
  v:()=>spF([w3("1,5 cL","1,5 cL","1.5 cL"),w3("occhi","yeux","eyes"),w3("naso","nez","nose"),w3("+ acqua","+ eau","+ water"),w3("naso","nez","nose"),w3("bocca","bouche","palate"),w3("sputare","recracher","spit")].map((l,i)=>fD(.2+i*.35,fBox(8+(i%4)*78,30+Math.floor(i/4)*44,70,28,l,{fill:i===6?"rgba(140,29,64,.7)":undefined})+(i%4<3&&i<6?fArrow(`M${80+(i%4)*78} ${44+Math.floor(i/4)*44}H${84+(i%4)*78}`):""))).join("")
   +fD(3,spSpittoon(250,180)+fChip(120,166,w3("resti lucido","on reste lucide","stay clear-headed"),"#5e8c31")))},
 {h:I3_("L'aspetto: il colore","L'aspect : la couleur","Appearance: colour"),
  c:I3_("Le note seguono l'ordine della degustazione: occhi, naso, bocca. Per l'aspetto basta il colore. Molti distillati non invecchiati sono incolori, mentre quelli passati nel legno vanno dal limone all'oro, all'ambra e al marrone. Alcuni prodotti aromatizzati, soprattutto i liquori, sono vivaci: rosa, rosso, verde, blu, perfino nero. Il colore è un indizio, non una prova.",
   "Les notes suivent l'ordre de la dégustation : yeux, nez, bouche. Pour l'aspect, la couleur suffit. Beaucoup de spiritueux non vieillis sont incolores, tandis que ceux passés en fût vont du citron à l'or, à l'ambre et au brun. Certains produits aromatisés, surtout les liqueurs, sont vifs : rose, rouge, vert, bleu, même noir. La couleur est un indice, pas une preuve.",
   "Notes follow the order of the tasting: eyes, nose, palate. For appearance, colour is all you need. Many unaged spirits are colourless, while those aged in wood range from lemon to gold, amber and brown. Some flavoured products, especially liqueurs, can be vivid: pink, red, green, blue, even black. Colour is a first clue, not proof."),
  v:()=>spF(spEye(160,26)+spSwatches(28,74,["#eef3f6","#f3eaa0","#e8c25a","#c98a3a","#7a4a22"],[w3("incolore","incolore","colourless"),w3("limone","citron","lemon"),w3("oro","or","gold"),w3("ambra","ambre","amber"),w3("marrone","brun","brown")],.4,66)
   +fD(2.4,fT(160,136,w3("prodotti aromatizzati","produits aromatisés","flavoured products"),9.5,"#f3cd8a")+["#f0a3c0","#c0392b","#3fae6a","#3f6fd0","#1a1416"].map((c,i)=>`<circle cx="${80+i*40}" cy="164" r="12" fill="${c}" stroke="#e8dccf"/>`).join(""))+fD(3.2,fChip(160,194,w3("indizio, non prova","indice, pas preuve","a clue, not proof"),"#8c1d40")))},
 {h:I3_("Il naso: intensità e aromi","Le nez : intensité et arômes","Nose: intensity and aromas"),
  c:I3_("Al naso si giudica prima l'intensità: neutra, quasi senza odore come molte vodka, poi leggera, media o pronunciata. Poi si descrivono gli aromi raggruppati per origine: la materia prima, come frutta o cereale; il modo in cui è stato fatto; il legno e l'invecchiamento, come vaniglia, spezie o note tostate.",
   "Au nez, on juge d'abord l'intensité : neutre, presque sans odeur comme beaucoup de vodkas, puis légère, moyenne ou prononcée. Ensuite, on décrit les arômes regroupés selon leur origine : la matière première, comme les fruits ou la céréale ; la façon dont il a été fait ; le bois et le vieillissement, comme la vanille, les épices ou le grillé.",
   "On the nose, first judge intensity: neutral, with almost no smell like many vodkas, then light, medium or pronounced. Then describe the aromas grouped by where they come from: the raw material, such as fruit or grain; the way it was made; and the oak and maturation, such as vanilla, spice or toasty notes."),
  v:()=>spF(spNose(24,44)+[w3("neutro","neutre","neutral"),w3("leggero","léger","light"),w3("medio","moyen","medium"),w3("pronunciato","prononcé","pronounced")].map((l,i)=>fD(.3+i*.4,`<rect x="${50+i*66}" y="${46-i*8}" width="58" height="${10+i*8}" rx="3" fill="${mixC("#5c646b","#d4a23a",i/3)}"/>`+fT(79+i*66,72,l,9))).join("")
   +[[w3("materia prima","matière première","raw material"),w3("frutta, cereale","fruits, céréale","fruit, grain"),"#5e8c31"],[w3("lavorazione","élaboration","how it was made"),w3("fermentazione…","fermentation…","fermentation…"),"#3f7fa8"],[w3("legno e tempo","bois et temps","oak and maturation"),w3("vaniglia, spezie","vanille, épices","vanilla, spice"),"#8a5a33"]]
   .map(([a,b,c],i)=>fD(2+i*.6,fBox(10+i*104,98,96,30,a,{fill:c})+fT(58+i*104,146,b,9,"#f3cd8a"))).join("")+fD(3.6,fChip(160,180,w3("da dove viene?","d'où vient-il ?","where is it from?"),"#8c1d40")))},
 {h:I3_("Bocca, finale e complessità","Bouche, finale et complexité","Palate, finish and complexity"),
  c:I3_("In bocca si ritrovano gli stessi gruppi di sapori, più due osservazioni: quanto zucchero si sente e la consistenza, sottile o più ricca. Dopo aver sputato si misura il finale, cioè quanto durano i sapori: corto, medio o lungo. Infine si giudica la complessità, da neutra e semplice fino a molto complessa, quando tanti sapori continuano a cambiare.",
   "En bouche, on retrouve les mêmes familles de saveurs, plus deux observations : le sucre perçu et la texture, fine ou plus riche. Après avoir recraché, on mesure la finale, c'est-à-dire la durée des saveurs : courte, moyenne ou longue. Enfin, on juge la complexité, de neutre et simple jusqu'à très complexe, quand de nombreuses saveurs continuent d'évoluer.",
   "On the palate you find the same groups of flavours, plus two observations: how much sugar you sense, and the texture, thin or richer. After spitting, measure the finish, how long the flavours linger: short, medium or long. Finally judge complexity, from neutral and simple up to very complex, when many flavours keep changing."),
  v:()=>spF(fChip(70,30,w3("zucchero?","sucre ?","sugar?"),"#d4a23a","#2a1b20")+fChip(220,30,w3("consistenza","texture","texture"),"#5c646b")
   +fD(.8,fT(20,74,w3("finale","finale","finish"),10,"#f3cd8a","start")+[w3("corto","courte","short"),w3("medio","moyenne","medium"),w3("lungo","longue","long")].map((l,i)=>`<rect x="90" y="${62+i*16}" width="0" height="10" rx="4" fill="#d4a23a"><animate attributeName="width" from="0" to="${50+i*70}" dur="1.2s" begin="${1+i*.5}s" fill="freeze"/></rect>`+fD(1+i*.5,fT(86,71+i*16,l,8.5,null,"end"))).join(""))
   +fD(2.8,`<path d="M40 160H280" stroke="rgba(243,227,195,.35)" stroke-width="2"/>`+fT(20,140,w3("complessità","complexité","complexity"),10,"#f3cd8a","start")+[w3("neutro","neutre","neutral"),w3("semplice","simple","simple"),w3("un po' complesso","assez complexe","some complexity"),w3("molto complesso","très complexe","very complex")].map((l,i)=>fD(3+i*.4,`<circle cx="${40+i*80}" cy="160" r="${4+i*2}" fill="${mixC("#5c646b","#d4a23a",i/3)}"/>`+fT(40+i*80,184,l,9))).join("")))}
]},
/* ===================== t2 A balanced cocktail ===================== */
{id:"s1_balance", sec:"t", ch:"t2", ic:"bub", t:I3_("Il cocktail equilibrato","Le cocktail équilibré","A balanced cocktail"), s:[
 {h:I3_("Due bilance, quattro elementi","Deux balances, quatre éléments","Two scales, four elements"),
  c:I3_("Buoni ingredienti e strumenti aiutano, ma ciò che rende memorabile un cocktail è l'equilibrio. Immagina due bilance. La prima pesa la parte forte contro la parte leggera; la seconda pesa il dolce contro l'amaro e l'acido. Insieme danno quattro punti d'equilibrio, e ogni cocktail classico è costruito proprio con questi quattro elementi.",
   "De bons ingrédients et de bons outils aident, mais ce qui rend un cocktail mémorable, c'est l'équilibre. Imaginez deux balances. La première pèse la partie forte contre la partie légère ; la seconde pèse le sucré contre l'amer et l'acide. Ensemble, elles donnent quatre points d'équilibre, et chaque cocktail classique est bâti sur ces quatre éléments.",
   "Good ingredients and tools help, but what makes a cocktail memorable is balance. Picture two sets of scales. The first weighs the strong part against the weak part; the second weighs sweet against bitter and sour. Together they give four points of balance, and every classic cocktail is built from these four elements."),
  v:()=>spF(`<g transform="translate(80 150) scale(.82)">${spScale(0,0,"","")}</g>`+fChip(26,150,w3("forte","fort","strong"),"#8c1d40")+fChip(134,150,w3("leggero","léger","weak"),"#3f7fa8")
   +fD(1.2,`<g transform="translate(240 150) scale(.82)">${spScale(0,0,"","")}</g>`+fChip(186,150,w3("dolce","sucré","sweet"),"#d4a23a","#2a1b20")+fChip(290,150,w3("amaro/acido","amer/acide","bitter/sour"),"#5e8c31"))+fD(3,fChip(160,190,w3("4 punti d'equilibrio","4 points d'équilibre","4 points of balance"))))},
 {h:I3_("La parte forte","La partie forte","The strong part"),
  c:I3_("La parte forte è il distillato di base, di solito al 40% vol. o più, ed è il cuore del sapore: il rum nel Daiquiri, il gin nel Martini. Cambia il distillato e cambi il drink. Anche un altro prodotto della stessa categoria cambia il risultato, e sostituire del tutto la base crea una variante, come un Old Fashioned fatto con il rum.",
   "La partie forte est le spiritueux de base, en général à 40 % vol. ou plus, et c'est le cœur du goût : le rhum dans le Daiquiri, le gin dans le Martini. Changez le spiritueux et vous changez le drink. Même un autre produit de la même catégorie modifie le résultat, et remplacer complètement la base crée une variante, comme un Old Fashioned au rhum.",
   "The strong part is the base spirit, usually 40% abv or more, and it is the heart of the flavour: rum in a Daiquiri, gin in a Martini. Change the spirit and you change the drink. Even another product from the same category alters the result, and replacing the base entirely creates a variation, such as an Old Fashioned made with rum."),
  v:()=>spF(spDrink(56,"Daiquiri","coupe","#efe7b0",{gar:LIME},[w3("base: rum","base : rhum","base: rum")],.2)+spDrink(160,"Martini","martini","rgba(240,240,220,.75)",{olive:1},[w3("base: gin","base : gin","base: gin")],.8)
   +fD(1.6,spDrink(264,"Old Fashioned","rocks","#b9742e",{ice:1,gar:ORANGE},[w3("whiskey → rum","whiskey → rhum","whiskey → rum"),w3("= variante","= variante","= variation")],0))+fD(2.6,fChip(160,190,w3("40% vol o più","40 % vol ou plus","40% abv or more"),"#8c1d40")))},
 {h:I3_("La parte leggera","La partie légère","The weak part"),
  c:I3_("La parte leggera smorza la potenza dell'alcol. Una fonte c'è sempre: il ghiaccio, che si scioglie un po' mentre si mescola o si shakera e aggiunge acqua. Le altre sono facoltative e analcoliche: succhi di frutta, panna o latte, bibite, acqua gassata e tonica. In un gin tonic il gin è la parte forte, tonica e ghiaccio lo bilanciano.",
   "La partie légère adoucit la puissance de l'alcool. Une source est toujours là : la glace, qui fond un peu quand on remue ou qu'on secoue et ajoute de l'eau. Les autres sont facultatives et sans alcool : jus de fruits, crème ou lait, sodas, eau gazeuse et tonic. Dans un gin tonic, le gin est la partie forte, le tonic et la glace l'équilibrent.",
   "The weak part softens the power of the alcohol. One source is always there: ice, which melts a little as you stir or shake and adds water. Others are optional and non-alcoholic: fruit juices, cream or milk, sodas, club soda and tonic. In a gin and tonic, gin is the strong part, while tonic and ice balance it."),
  v:()=>spF(fBucket(56,110)+fDrops(56,114,140,"#bfe6f6",3)+fChip(56,160,w3("ghiaccio: sempre","glace : toujours","ice: always"),"#3f7fa8")
   +[[ORANGE,w3("succhi","jus","juices")],["#f4ecd8",w3("panna, latte","crème, lait","cream, milk")],["#c9e6ef",w3("soda, tonica","soda, tonic","soda, tonic")]].map(([c,l],i)=>fD(.8+i*.4,spBottle(124+i*50,80,c,{s:.6})+fT(124+i*50,114,l,8.5,null,"middle",700,8))).join("")
   +fD(2.4,spCocktail(276,120,"highball","rgba(220,235,240,.6)",{ice:1,bub:1,gar:LIME})+fChip(276,150,"gin tonic","#8c1d40")+fChip(220,186,w3("gin = forte","gin = fort","gin = strong"))))},
 {h:I3_("Il dolce","Le sucré","Sweetness"),
  c:I3_("Molti cocktail prima si addolciscono, poi si condiscono. La dolcezza può venire dallo zucchero, dallo sciroppo semplice, cioè zucchero sciolto in acqua, o da un liquore. Arrotonda e lega gli ingredienti, ma da sola stanca il palato: un cocktail troppo dolce risulta stucchevole e pesante.",
   "Beaucoup de cocktails sont d'abord sucrés, puis assaisonnés. Le sucré peut venir du sucre, du sirop simple, c'est-à-dire du sucre dissous dans l'eau, ou d'une liqueur. Il arrondit et lie les ingrédients, mais seul il fatigue le palais : un cocktail trop sucré paraît écœurant et lourd.",
   "Many cocktails are first sweetened, then seasoned. Sweetness can come from sugar, from simple syrup, which is sugar dissolved in water, or from a liqueur. It rounds things off and binds them together, but on its own it tires the palate: a cocktail that is too sweet tastes cloying and heavy."),
  v:()=>spF(spSugar(48,70,2)+fT(58,96,w3("zucchero","sucre","sugar"),9.5)+fD(.6,spBottle(150,70,"rgba(250,245,230,.7)",{s:.7})+fT(150,108,w3("sciroppo semplice","sirop simple","simple syrup"),9.5)+fT(150,121,w3("zucchero + acqua","sucre + eau","sugar + water"),8,"#f3cd8a"))+fD(1.2,spBottle(250,70,"#c03a5a",{s:.7})+fT(250,108,w3("liquore","liqueur","liqueur"),9.5))
   +fD(2.2,fChip(100,160,w3("arrotonda, lega","arrondit, lie","rounds, binds"),"#5e8c31"))+fD(3,fChip(230,160,w3("troppo: stucchevole","trop : écœurant","too much: cloying"),"#8c1d40")))},
 {h:I3_("L'acido e l'amaro","L'acide et l'amer","Sour and bitter"),
  c:I3_("Il contrappeso è il modificatore, che porta una nota acida, una nota amara o entrambe. L'acidità viene soprattutto dagli agrumi: un po' di succo di lime o di limone rende il sorso vivace. L'amaro viene dai bitter da cocktail, usati a gocce, o dai distillati amari. Funziona come in cucina: un pizzico di sale o un filo di limone ravviva un piatto piatto.",
   "Le contrepoids est le modificateur, qui apporte une note acide, une note amère ou les deux. L'acidité vient surtout des agrumes : un peu de jus de citron vert ou jaune rend la gorgée vive. L'amertume vient des bitters à cocktail, utilisés à la goutte, ou des spiritueux amers. C'est comme en cuisine : une pincée de sel ou un trait de citron réveille un plat fade.",
   "The counterweight is the modifier, which brings a sour note, a bitter note or both. Sourness comes mainly from citrus: a little lime or lemon juice makes the sip lively. Bitterness comes from cocktail bitters, used by the dash, or from bitter spirits. It works like cooking: a pinch of salt or a squeeze of lemon lifts a flat dish."),
  v:()=>spF(fChip(160,24,w3("il modificatore","le modificateur","the modifier"),"#8c1d40")+fD(.4,spCitrus(50,90,18,LIME)+spCitrus(100,96,16,LEMON)+fChip(76,136,w3("acido: agrumi","acide : agrumes","sour: citrus"),"#5e8c31"))
   +fD(1.4,spBitters(220,96,true)+spBottle(270,96,"#b5243a",{s:.6})+fChip(246,136,w3("amaro: bitter","amer : bitters","bitter: bitters"),"#8a5a33"))+fD(2.4,fChip(160,180,w3("come sale e limone","comme sel et citron","like salt and lemon"))))},
 {h:I3_("Ingredienti con più ruoli","Des ingrédients à plusieurs rôles","Ingredients with several roles"),
  c:I3_("Un solo ingrediente può avere più ruoli. I vini aromatizzati come il vermut portano insieme dolcezza, amaro e acidità; un liquore porta sia alcol sia dolcezza. L'obiettivo è un insieme coeso in cui nessuna parte domina le altre: se il drink sa solo di zucchero, di limone o di alcol, non è ancora equilibrato.",
   "Un seul ingrédient peut jouer plusieurs rôles. Les vins aromatisés comme le vermouth apportent à la fois douceur, amertume et acidité ; une liqueur apporte de l'alcool et du sucre. Le but est un ensemble cohérent où aucune partie ne domine : si le drink n'a le goût que du sucre, du citron ou de l'alcool, il n'est pas encore équilibré.",
   "A single ingredient can play several roles. Aromatised wines such as vermouth bring sweetness, bitterness and acidity at once; a liqueur brings both alcohol and sweetness. The goal is a cohesive whole where no part dominates: if the drink tastes only of sugar, lemon or alcohol, it is not balanced yet."),
  v:()=>spF(fBottle(50,90,{col:"#7a1a12",label:1,cork:1})+fT(50,146,w3("vermut","vermouth","vermouth"),9.5)+[[w3("dolce","sucré","sweet"),"#d4a23a"],[w3("amaro","amer","bitter"),"#8a5a33"],[w3("acido","acide","sour"),"#5e8c31"]].map(([l,c],i)=>fD(.4+i*.4,fChip(118,50+i*26,l,c))).join("")
   +fD(1.8,spBottle(214,90,"#c03a5a",{s:.8})+fT(214,140,w3("liquore","liqueur","liqueur"),9.5)+fChip(276,62,w3("alcol","alcool","alcohol"),"#8c1d40")+fChip(276,88,w3("dolcezza","douceur","sweetness"),"#d4a23a"))+fD(2.8,fChip(160,182,w3("nessuno domina","aucun ne domine","nothing dominates"))))},
 {h:I3_("Drink corti e drink lunghi","Short drinks et long drinks","Short drinks and long drinks"),
  c:I3_("Una prima divisione aiuta a orientarsi: drink corti e drink lunghi. I corti hanno pochi ingredienti e poco volume; la parte leggera è quasi solo l'acqua del ghiaccio mentre si mescola o si shakera. Qui stanno i cocktail spirit-forward e i sour corti. I lunghi si allungano con bibite, succhi o latticini: highball e sour lunghi.",
   "Une première séparation aide à s'orienter : short drinks et long drinks. Les courts ont peu d'ingrédients et peu de volume ; leur partie légère est presque seulement l'eau de la glace pendant qu'on remue ou qu'on secoue. On y trouve les cocktails spirit-forward et les sours courts. Les longs s'allongent de sodas, jus ou produits laitiers : highballs et sours longs.",
   "One first split helps you find your way: short drinks and long drinks. Short drinks have few ingredients and a small volume; their weak part is almost only the water from ice during stirring or shaking. Spirit-forward cocktails and short sours belong here. Long drinks are lengthened with sodas, juices or dairy: highballs and long sours."),
  v:()=>spF(fChip(80,22,w3("corti","courts","short"),"#8c1d40")+spCocktail(50,110,"rocks","#b9742e",{ice:1})+spCocktail(110,110,"coupe","#efe7b0")+fT(50,128,"spirit-forward",8.5)+fT(110,128,w3("sour corto","sour court","short sour"),8.5)+fD(.6,fChip(80,160,w3("solo ghiaccio","glace seulement","ice only"),"#3f7fa8"))
   +`<path d="M160 20V180" stroke="rgba(243,227,195,.3)" stroke-dasharray="4 4"/>`+fD(1.6,fChip(240,22,w3("lunghi","longs","long"),"#5e8c31")+spCocktail(210,110,"highball","rgba(220,235,240,.6)",{ice:1,bub:1})+spCocktail(270,110,"highball","#efe7b0",{ice:1,bub:1,gar:LEMON})+fT(210,128,"highball",8.5)+fT(270,128,w3("sour lungo","sour long","long sour"),8.5)+fChip(240,160,w3("+ soda, succo","+ soda, jus","+ soda, juice"),"#3f7fa8")))},
 {h:I3_("Da corto a lungo","Du court au long","From short to long"),
  c:I3_("Un esempio mostra il legame. Un gin sour corto, shakerato e servito in un bicchiere piccolo, diventa un drink lungo se lo versi sul ghiaccio e lo completi con acqua gassata. Gli ingredienti di base restano gli stessi; cambia la quantità della parte leggera, e con lei la forza, il volume e il momento in cui berlo.",
   "Un exemple montre le lien. Un gin sour court, secoué et servi dans un petit verre, devient un long drink si on le verse sur glace et qu'on le complète d'eau gazeuse. Les ingrédients de base restent les mêmes ; ce qui change, c'est la quantité de partie légère, et avec elle la force, le volume et le moment où on le boit.",
   "An example shows the link. A short gin sour, shaken and served in a small glass, becomes a long drink if you pour it over ice and top it with club soda. The core ingredients stay the same; what changes is the amount of the weak part, and with it the strength, the volume and the moment you might enjoy it."),
  v:()=>spF(spShaker(50,90,1.2,true)+fD(.6,spCocktail(110,150,"coupe","#efe7b0",{s:1.3})+fChip(110,176,"gin sour"))+fD(1.6,fArrow("M150 120H186")+fChip(176,66,w3("+ ghiaccio, soda","+ glace, soda","+ ice, club soda"),"#3f7fa8"))
   +fD(2.2,spCocktail(240,150,"highball","#efe7b0",{ice:1,bub:1,gar:LEMON,s:1.3})+fChip(240,176,w3("drink lungo","long drink","long drink"),"#5e8c31")))}
]},
/* ===================== t3 Cocktail families ===================== */
{id:"s1_cocktails", sec:"t", ch:"t3", ic:"bub", t:I3_("Famiglie di cocktail","Familles de cocktails","Cocktail families"), s:[
 {h:I3_("Quattro famiglie","Quatre familles","Four families"),
  c:I3_("I cocktail classici si dividono in quattro grandi famiglie. Due sono corte: gli spirit-forward, dove comanda il distillato, e i sour corti, che uniscono distillato, agrumi e dolcezza. Due sono lunghe: gli highball, un distillato con una bibita analcolica, e i sour lunghi, sour corti allungati con soda o vino spumante. Conosciamole una per una.",
   "Les cocktails classiques se répartissent en quatre grandes familles. Deux sont courtes : les spirit-forward, où le spiritueux commande, et les sours courts, qui réunissent spiritueux, agrumes et douceur. Deux sont longues : les highballs, un spiritueux avec une boisson sans alcool, et les sours longs, des sours courts allongés de soda ou de vin effervescent. Découvrons-les une à une.",
   "Classic cocktails fall into four big families. Two are short: spirit-forward drinks, where the spirit leads, and short sours, which combine spirit, citrus and sweetness. Two are long: highballs, a spirit with a non-alcoholic mixer, and long sours, short sours lengthened with soda or sparkling wine. Let us meet them one by one."),
  v:()=>spF([["Spirit-forward","rocks","#b9742e",{ice:1,gar:ORANGE}],[w3("Sour corto","Sour court","Short sour"),"coupe","#efe7b0",{foam:1}],["Highball","highball","rgba(220,235,240,.6)",{ice:1,bub:1,gar:LIME}],[w3("Sour lungo","Sour long","Long sour"),"highball","#efe7b0",{ice:1,bub:1,gar:LEMON}]]
   .map(([l,ty,c,o],i)=>fD(.3+i*.6,fBox(10+(i%2)*154,14+Math.floor(i/2)*92,146,84,"",{fill:i<2?"rgba(140,29,64,.35)":"rgba(94,140,49,.35)"})+spCocktail(50+(i%2)*154,88+Math.floor(i/2)*92,ty,c,Object.assign({s:.95},o))+fT(124+(i%2)*154,58+Math.floor(i/2)*92,l,10.5,null,"middle",800,12))).join("")
   +fD(2.8,fChip(160,98,w3("corti ↑ · lunghi ↓","courts ↑ · longs ↓","short ↑ · long ↓"))))},
 {h:I3_("Old Fashioned e Manhattan","Old Fashioned et Manhattan","Old Fashioned and Manhattan"),
  c:I3_("Gli spirit-forward sono i cocktail più forti, quelli che mettono in mostra il distillato; si preparano nel bicchiere o si mescolano, e il ghiaccio raffredda e diluisce. L'Old Fashioned è il modello: whiskey americano, una zolletta di zucchero e bitter aromatico. Il Manhattan usa rye o Bourbon con lo stesso bitter, ma sostituisce lo zucchero con vermut rosso dolce.",
   "Les spirit-forward sont les cocktails les plus forts, ceux qui mettent le spiritueux en avant ; on les prépare dans le verre ou on les remue, et la glace refroidit et dilue. L'Old Fashioned est le modèle : whiskey américain, un morceau de sucre et des bitters aromatiques. Le Manhattan prend du rye ou du Bourbon avec les mêmes bitters, mais remplace le sucre par du vermouth rouge doux.",
   "Spirit-forward cocktails are the strongest, putting the spirit on show; they are built in the glass or stirred, and the ice both chills and dilutes. The Old Fashioned is the template: American whiskey, a sugar cube and aromatic bitters. The Manhattan uses rye or Bourbon with the same bitters, swapping the sugar for sweet red vermouth."),
  v:()=>spF(spDrink(80,"Old Fashioned","rocks","#b9742e",{ice:1,gar:ORANGE,s:1.2},[w3("whiskey americano","whiskey américain","American whiskey"),w3("zolletta di zucchero","morceau de sucre","sugar cube"),w3("bitter aromatico","bitters aromatiques","aromatic bitters")],.2)
   +spDrink(240,"Manhattan","coupe","#8a3a1a",{s:1.2},[w3("rye o Bourbon","rye ou Bourbon","rye or Bourbon"),w3("vermut rosso dolce","vermouth rouge doux","sweet red vermouth"),w3("bitter aromatico","bitters aromatiques","aromatic bitters")],1.4)+fD(2.6,fChip(160,186,w3("costruito o mescolato","au verre ou remué","built or stirred"),"#5c646b")))},
 {h:I3_("Sazerac e Rusty Nail","Sazerac et Rusty Nail","Sazerac and Rusty Nail"),
  c:I3_("Il Sazerac parte da Cognac o rye, con zucchero, un altro stile di bitter e un tocco di assenzio. Il Rusty Nail è il più semplice di tutti: whisky scozzese e un liquore a base di Scotch, solo due ingredienti. Entrambi seguono la stessa idea: un distillato bilanciato da un po' di dolcezza e, spesso, da un po' di amaro.",
   "Le Sazerac part du Cognac ou du rye, avec du sucre, un autre style de bitters et une touche d'absinthe. Le Rusty Nail est le plus simple de tous : whisky écossais et une liqueur à base de Scotch, deux ingrédients seulement. Tous deux suivent la même idée : un spiritueux équilibré par un peu de douceur et, souvent, un peu d'amertume.",
   "The Sazerac starts from Cognac or rye, with sugar, a different style of bitters and a touch of absinthe. The Rusty Nail is the simplest of all: Scotch whisky with a Scotch-based liqueur, just two ingredients. Both follow the same idea: a spirit balanced by a little sweetness and, often, a little bitterness."),
  v:()=>spF(spDrink(80,"Sazerac","rocks","#b9742e",{gar:LEMON,s:1.2},[w3("Cognac o rye","Cognac ou rye","Cognac or rye"),w3("zucchero","sucre","sugar"),w3("bitter","bitters","bitters"),w3("tocco di assenzio","touche d'absinthe","touch of absinthe")],.2)
   +spDrink(240,"Rusty Nail","rocks","#c98a3a",{ice:1,s:1.2},[w3("whisky scozzese","whisky écossais","Scotch whisky"),w3("liquore allo Scotch","liqueur au Scotch","Scotch liqueur")],1.4)+fD(2.6,fChip(240,186,w3("solo 2 ingredienti","2 ingrédients","just 2 ingredients"),"#5e8c31")))},
 {h:I3_("Martini, Negroni, Alexander","Martini, Negroni, Alexander","Martini, Negroni, Alexander"),
  c:I3_("Il gin dà due grandi classici. Il Martini unisce gin e vermut dry, che da solo porta sia la nota dolce sia quella amara. Il Negroni unisce gin, vermut rosso dolce e un distillato amaro rosso: tre ingredienti, tre ruoli chiari. Aggiungendo panna a questo tipo di drink nasce la famiglia degli Alexander, come il Brandy Alexander.",
   "Le gin donne deux grands classiques. Le Martini associe gin et vermouth dry, qui apporte à lui seul la note douce et la note amère. Le Negroni réunit gin, vermouth rouge doux et un spiritueux amer rouge : trois ingrédients, trois rôles clairs. En ajoutant de la crème à ce type de drink, on obtient la famille des Alexander, comme le Brandy Alexander.",
   "Gin gives two great classics. The Martini pairs gin with dry vermouth, which alone provides both the sweet and the bitter note. The Negroni combines gin, sweet red vermouth and a red bitter spirit: three ingredients, three clear roles. Add cream to this kind of drink and you get the Alexander family, such as the Brandy Alexander."),
  v:()=>spF(spDrink(56,"Martini","martini","rgba(240,240,220,.75)",{olive:1},[w3("gin","gin","gin"),w3("vermut dry","vermouth dry","dry vermouth")],.2)+spDrink(160,"Negroni","rocks","#b5243a",{ice:1,gar:ORANGE},[w3("gin","gin","gin"),w3("vermut rosso","vermouth rouge","sweet red vermouth"),w3("amaro rosso","amer rouge","red bitter spirit")],1.1)
   +spDrink(264,"Brandy Alexander","coupe","#e8d8b8",{},[w3("brandy","brandy","brandy"),w3("+ panna","+ crème","+ cream")],2))},
 {h:I3_("I sour corti","Les sours courts","Short sours"),
  c:I3_("Il sour corto si basa su un trio: forte, acido, dolce, shakerato per una consistenza leggera, quasi spumosa. Daiquiri: rum, lime e sciroppo semplice. Whiskey Sour: Bourbon o rye, limone e sciroppo, con albume e bitter facoltativi. Pisco Sour: pisco, lime, sciroppo, albume e un goccio di bitter. L'albume crea una schiuma setosa; l'aquafaba è l'alternativa vegana.",
   "Le sour court repose sur un trio : fort, acide, sucré, secoué pour une texture légère, presque mousseuse. Daiquiri : rhum, citron vert et sirop simple. Whiskey Sour : Bourbon ou rye, citron jaune et sirop, avec blanc d'œuf et bitters en option. Pisco Sour : pisco, citron vert, sirop, blanc d'œuf et un trait de bitters. Le blanc d'œuf crée une mousse soyeuse ; l'aquafaba est l'alternative végane.",
   "The short sour rests on a trio: strong, sour, sweet, shaken for a light, almost frothy texture. Daiquiri: rum, lime and simple syrup. Whiskey Sour: Bourbon or rye, lemon and syrup, with optional egg white and bitters. Pisco Sour: pisco, lime, syrup, egg white and a dash of bitters. Egg white makes a silky foam; aquafaba is the vegan alternative."),
  v:()=>spF(spDrink(56,"Daiquiri","coupe","#efe7b0",{gar:LIME},[w3("rum","rhum","rum"),"lime",w3("sciroppo","sirop","syrup")],.2)+spDrink(160,"Whiskey Sour","rocks","#d9a441",{ice:1,gar:LEMON},[w3("Bourbon o rye","Bourbon ou rye","Bourbon or rye"),w3("limone","citron jaune","lemon"),w3("sciroppo","sirop","syrup")],1)
   +spDrink(264,"Pisco Sour","coupe","#efe7b0",{foam:1},["pisco","lime",w3("sciroppo","sirop","syrup"),w3("albume","blanc d'œuf","egg white")],1.8)+fD(2.8,spShaker(26,170,.6,true)+fChip(200,190,w3("vegano: aquafaba","végane : aquafaba","vegan: aquafaba"),"#5e8c31")))},
 {h:I3_("Varianti del sour","Variantes du sour","Sour variations"),
  c:I3_("Le varianti cambiano il dolcificante, l'ingrediente acido o entrambi. Nel Sidecar il Cognac incontra limone e triple sec, un liquore all'arancia che sostituisce lo sciroppo. Il Margarita usa tequila, lime e triple sec, con bordo di sale facoltativo. Il Clover Club unisce gin, limone e sciroppo di lampone con albume: stesso schema, colore diverso.",
   "Les variantes changent l'édulcorant, l'ingrédient acide ou les deux. Dans le Sidecar, le Cognac rencontre citron jaune et triple sec, une liqueur d'orange qui remplace le sirop. La Margarita prend tequila, citron vert et triple sec, avec un bord de sel en option. Le Clover Club réunit gin, citron et sirop de framboise avec blanc d'œuf : même schéma, autre couleur.",
   "Variations change the sweetener, the sour ingredient or both. In the Sidecar, Cognac meets lemon and triple sec, an orange liqueur that replaces the syrup. The Margarita uses tequila, lime and triple sec, with an optional salt rim. The Clover Club combines gin, lemon and raspberry syrup with egg white: same pattern, different colour."),
  v:()=>spF(spDrink(56,"Sidecar","coupe","#e3a84a",{gar:ORANGE},["Cognac",w3("limone","citron jaune","lemon"),"triple sec"],.2)+spDrink(160,"Margarita","martini","#e6ec9a",{salt:1,gar:LIME},["tequila","lime","triple sec",w3("sale (facolt.)","sel (option)","salt (optional)")],1)
   +spDrink(264,"Clover Club","coupe","#e0607a",{foam:1},["gin",w3("limone","citron jaune","lemon"),w3("sciroppo lampone","sirop framboise","raspberry syrup"),w3("albume","blanc d'œuf","egg white")],1.8)+fD(2.8,fChip(160,194,w3("triple sec = arancia","triple sec = orange","triple sec = orange"),"#d4a23a","#2a1b20")))},
 {h:I3_("Gli highball","Les highballs","Highballs"),
  c:I3_("L'highball è il drink misto più semplice: un distillato e una bibita analcolica, serviti lunghi su ghiaccio a cubetti, come gin tonic o whisky e soda. Alcuni hanno un nome proprio. Il Cuba Libre è rum e cola con lime. Il Greyhound è vodka e succo di pompelmo, dove il succo un po' amaro e acido fa da modificatore.",
   "Le highball est le mélange le plus simple : un spiritueux et une boisson sans alcool, servis longs sur glace en cubes, comme le gin tonic ou le whisky soda. Certains ont leur propre nom. Le Cuba Libre, c'est rhum et cola avec du citron vert. Le Greyhound, c'est vodka et jus de pamplemousse, où le jus un peu amer et acide sert de modificateur.",
   "The highball is the simplest mixed drink: a spirit and a non-alcoholic mixer, served long over cubed ice, like gin and tonic or whisky and soda. Some have their own names. The Cuba Libre is rum and cola with lime. The Greyhound is vodka and grapefruit juice, where the slightly bitter, sour juice acts as the modifier."),
  v:()=>spF(fD(.2,spCocktail(56,116,"highball","rgba(220,235,240,.6)",{ice:1,bub:1,gar:LIME})+fChip(56,24,w3("distillato + bibita","spiritueux + soda","spirit + mixer"),"#5c646b")+fT(56,136,"gin tonic",8.6,"#f3cd8a")+fT(56,148,"whisky soda",8.6,"#f3cd8a"))
   +spDrink(160,"Cuba Libre","highball","#4a2416",{ice:1,bub:1,gar:LIME},[w3("rum","rhum","rum"),"cola","lime"],1)+spDrink(264,"Greyhound","highball","#f4b8a0",{ice:1,gar:GRAPEF},["vodka",w3("succo di pompelmo","jus de pamplemousse","grapefruit juice")],1.8)+fD(2.8,fChip(264,186,w3("pompelmo: modificatore","pamplemousse = modif.","grapefruit = modifier"),"#5e8c31")))},
 {h:I3_("Horse's Neck e Americano","Horse's Neck et Americano","Horse's Neck and Americano"),
  c:I3_("Altri highball aggiungono un dettaglio. Il Horse's Neck unisce Cognac, ginger ale e bitter: un accento amaro sopra distillato e bibita. L'Americano ha una base divisa: vermut rosso dolce e un distillato amaro rosso insieme, completati con acqua gassata. Più leggero di un Negroni, è quasi un Negroni allungato senza gin.",
   "D'autres highballs ajoutent un détail. Le Horse's Neck associe Cognac, ginger ale et bitters : un accent amer sur le spiritueux et le soda. L'Americano a une base partagée : vermouth rouge doux et spiritueux amer rouge ensemble, complétés d'eau gazeuse. Plus léger qu'un Negroni, c'est presque un Negroni allongé sans le gin.",
   "Other highballs add a detail. The Horse's Neck combines Cognac, ginger ale and bitters: a bitter accent on top of spirit and mixer. The Americano has a split base: sweet red vermouth and a red bitter spirit together, topped with club soda. Lighter than a Negroni, it is almost a lengthened Negroni without the gin."),
  v:()=>spF(spDrink(80,"Horse's Neck","highball","#d9a441",{ice:1,bub:1,gar:LEMON,s:1.1},["Cognac","ginger ale",w3("bitter","bitters","bitters")],.2)+spDrink(240,"Americano","highball","#c0392b",{ice:1,bub:1,gar:ORANGE,s:1.1},[w3("vermut rosso","vermouth rouge","sweet red vermouth"),w3("amaro rosso","amer rouge","red bitter spirit"),w3("acqua gassata","eau gazeuse","club soda")],1.4)
   +fD(2.6,fChip(240,190,w3("Negroni lungo, no gin","Negroni long sans gin","long Negroni, no gin"),"#8c1d40")))},
 {h:I3_("I sour lunghi","Les sours longs","Long sours"),
  c:I3_("Un sour lungo è un sour corto reso lungo. Il Tom Collins è il modello: gin, limone e sciroppo semplice su ghiaccio, completati con acqua gassata. Cambiando la soda la famiglia cresce: il Paloma unisce tequila e lime a una soda al pompelmo, mentre il French 75 completa Cognac o gin, limone e sciroppo con Champagne.",
   "Un sour long est un sour court rendu long. Le Tom Collins en est le modèle : gin, citron jaune et sirop simple sur glace, complétés d'eau gazeuse. En changeant le soda, la famille s'agrandit : la Paloma associe tequila et citron vert à un soda au pamplemousse, tandis que le French 75 complète Cognac ou gin, citron et sirop avec du Champagne.",
   "A long sour is a short sour made long. The Tom Collins is the model: gin, lemon and simple syrup over ice, topped with club soda. Swap the soda and the family grows: the Paloma pairs tequila and lime with a grapefruit soda, while the French 75 tops Cognac or gin, lemon and syrup with Champagne."),
  v:()=>spF(spDrink(56,"Tom Collins","highball","#efe7b0",{ice:1,bub:1,gar:LEMON},["gin",w3("limone","citron jaune","lemon"),w3("sciroppo","sirop","syrup"),w3("+ acqua gassata","+ eau gazeuse","+ club soda")],.2)
   +spDrink(160,"Paloma","highball","#f4b8a0",{ice:1,bub:1,gar:GRAPEF},["tequila","lime",w3("+ soda pompelmo","+ soda pamplemousse","+ grapefruit soda")],1)+spDrink(264,"French 75","flute","#f1e6a8",{},[w3("Cognac o gin","Cognac ou gin","Cognac or gin"),w3("limone, sciroppo","citron, sirop","lemon, syrup"),"+ Champagne"],1.8))},
 {h:I3_("Mojito e Singapore Sling","Mojito et Singapore Sling","Mojito and Singapore Sling"),
  c:I3_("Alcuni sour lunghi si arricchiscono di altri ingredienti. Il Mojito resta semplice: rum, lime e zucchero o sciroppo, con foglie di menta che lo rendono fresco e profumato. Il Singapore Sling è più complesso: gin e lime, addolciti con un liquore di ciliegia e un liquore alle erbe, con un goccio di bitter aromatico e acqua gassata per finire.",
   "Certains sours longs s'enrichissent d'autres ingrédients. Le Mojito reste simple : rhum, citron vert et sucre ou sirop, avec des feuilles de menthe qui le rendent frais et parfumé. Le Singapore Sling est plus complexe : gin et citron vert, adoucis par une liqueur de cerise et une liqueur aux herbes, avec un trait de bitters aromatiques et de l'eau gazeuse pour finir.",
   "Some long sours are enriched with extra ingredients. The Mojito stays simple: rum, lime and sugar or syrup, with mint leaves that make it fresh and fragrant. The Singapore Sling is more complex: gin and lime, sweetened with a cherry liqueur and a herbal liqueur, with a dash of aromatic bitters and a final top of club soda."),
  v:()=>spF(spDrink(80,"Mojito","highball","rgba(225,240,215,.7)",{ice:1,bub:1,mint:1,gar:LIME,s:1.1},[w3("rum","rhum","rum"),"lime",w3("zucchero o sciroppo","sucre ou sirop","sugar or syrup"),w3("menta","menthe","mint")],.2)
   +spDrink(240,"Singapore Sling","highball","#e0607a",{ice:1,bub:1,gar:ORANGE,s:1.1},["gin","lime",w3("liquore di ciliegia","liqueur de cerise","cherry liqueur"),w3("liquore alle erbe","liqueur aux herbes","herbal liqueur"),w3("bitter + soda","bitters + soda","bitters + soda")],1.4))}
]}
];
